(* Trimmed variant: strip the leading 4-byte ENDBR64 (0xf3 0x0f 0x1e 0xfa). *)
let sha256_block_data_order_nohw_tmc =
  define_trimmed "sha256_block_data_order_nohw_tmc" sha256_block_data_order_nohw_mc;;

let SHA256_BLOCK_DATA_ORDER_NOHW_EXEC =
  X86_MK_EXEC_RULE sha256_block_data_order_nohw_mc;;

let SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC =
  X86_MK_EXEC_RULE sha256_block_data_order_nohw_tmc;;

(* ========================================================================= *)
(* Phase 3: x86-ALU -> spec bridge for one SHA-256 compression round.        *)
(*                                                                           *)
(* The scalar nohw assembly lowers each FIPS-180-4 round function into a      *)
(* chain of ror/xor/and ALU ops, and accumulates T1 as a left-nested sum.    *)
(* These lemmas relate that concrete ALU shape to the spec round functions   *)
(* (sha256_Sigma0/Sigma1/Ch/Maj) and to sha256_compress_round, so that later *)
(* phases can fold a block of symbolic-execution output back into one clean  *)
(* spec-level round at each 1-round cut-point.                               *)
(*                                                                           *)
(* The shapes are read directly off round 0 of the assembly (mc offsets      *)
(* ~0x40-0x90), with the loop-entry working-variable mapping                 *)
(*   eax=a  ebx=b  ecx=c  edx=d  r8d=e  r9d=f  r10d=g  r11d=h                 *)
(* and the round temporaries                                                  *)
(*   r13d : Sigma1 chain   ror(ror(ror(e,14) xor e,5) xor e,6)               *)
(*   r14d : Sigma0 chain   ror(ror(ror(a,9)  xor a,11) xor a,2)              *)
(*   r15d : Ch     chain   ((f xor g) and e) xor g                            *)
(*   edi  : Maj    chain   b xor ((b xor c) and (a xor b))                    *)
(*   r12d : T1     accum   ((((W + h) + Ch) + K) + Sigma1)                    *)
(* with e' = d + T1 (into edx) and a' = (Maj + T1) + Sigma0 (into r11d).      *)
(* All four function bridges are pure bit-vector identities (WORD_BLAST);     *)
(* the round bridge then closes by ring-normalising the T1/T2 sums           *)
(* (WORD_RULE).                                                              *)
(* ========================================================================= *)

(* Ch(e,f,g): the asm computes ((f XOR g) AND e) XOR g. *)
let SHA256_CH_ALU = prove
 (`!e f g:int32. word_xor (word_and (word_xor f g) e) g = sha256_Ch e f g`,
  REWRITE_TAC[sha256_Ch] THEN CONV_TAC WORD_BLAST);;

(* Maj(a,b,c): the asm computes b XOR ((b XOR c) AND (a XOR b)). *)
let SHA256_MAJ_ALU = prove
 (`!a b c:int32. word_xor b (word_and (word_xor b c) (word_xor a b)) =
                 sha256_Maj a b c`,
  REWRITE_TAC[sha256_Maj] THEN CONV_TAC WORD_BLAST);;

(* Sigma0(a): three rotates folded via the r14d ror/xor chain.               *)
(* ror(a,9) is computed first, but ror by 9 then 11 then 2 (with the input   *)
(* xored back in between) realises the FIPS ROTR2 XOR ROTR13 XOR ROTR22.      *)
let SHA256_SIGMA0_ALU = prove
 (`!a:int32. word_ror (word_xor (word_ror (word_xor (word_ror a 9) a) 11) a) 2 =
             sha256_Sigma0 a`,
  REWRITE_TAC[sha256_Sigma0] THEN CONV_TAC WORD_BLAST);;

(* Sigma1(e): three rotates folded via the r13d ror/xor chain, realising     *)
(* the FIPS ROTR6 XOR ROTR11 XOR ROTR25.                                      *)
let SHA256_SIGMA1_ALU = prove
 (`!e:int32. word_ror (word_xor (word_ror (word_xor (word_ror e 14) e) 5) e) 6 =
             sha256_Sigma1 e`,
  REWRITE_TAC[sha256_Sigma1] THEN CONV_TAC WORD_BLAST);;

(* One compression round, in the exact flat ALU shape the assembly produces.  *)
(* Working state is [a;b;c;d;e;f;g;h]; the round constant is EL t sha256_K    *)
(* and the message word is sha256_W m t (already in a register, loaded and    *)
(* byte-swapped by the asm -- the bswap/memory aspects are a Phase 4          *)
(* concern).  The post-state is                                               *)
(*   [a'; a; b; c; e'; e; f; g]                                               *)
(* with T1 = (((W + h) + Ch e f g) + K) + Sigma1 e accumulated left-nested,   *)
(* e' = d + T1, and a' = (Maj a b c + T1) + Sigma0 a.                         *)
let SHA256_COMPRESS_ROUND_ALU = prove
 (`!m t a b c d e f g h:int32.
     sha256_compress_round m t [a;b;c;d;e;f;g;h] =
     [word_add (word_add (word_xor b (word_and (word_xor b c) (word_xor a b)))
                 (word_add (word_add (word_add (word_add (sha256_W m t) h)
                              (word_xor (word_and (word_xor f g) e) g))
                            (EL t sha256_K))
                  (word_ror (word_xor (word_ror (word_xor (word_ror e 14) e) 5) e) 6)))
               (word_ror (word_xor (word_ror (word_xor (word_ror a 9) a) 11) a) 2);
      a; b; c;
      word_add d (word_add (word_add (word_add (word_add (sha256_W m t) h)
                              (word_xor (word_and (word_xor f g) e) g))
                            (EL t sha256_K))
                  (word_ror (word_xor (word_ror (word_xor (word_ror e 14) e) 5) e) 6));
      e; f; g]`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[sha256_compress_round] THEN CONV_TAC(DEPTH_CONV let_CONV) THEN
  CONV_TAC(DEPTH_CONV EL_CONV) THEN
  REWRITE_TAC[SHA256_CH_ALU; SHA256_MAJ_ALU; SHA256_SIGMA0_ALU; SHA256_SIGMA1_ALU] THEN
  REWRITE_TAC[CONS_11] THEN
  CONV_TAC WORD_RULE);;

(* ========================================================================= *)
(* Phase 6: the LOWERCASE schedule-sigma ALU bridges + the W recurrence.       *)
(*                                                                           *)
(* The rounds_16_xx body computes each new schedule word W[t] (t >= 16) in    *)
(* registers from four stack-resident predecessors before running the         *)
(* compression round.  Two new function bridges lower the asm ror/shr/xor      *)
(* chains onto the spec's lowercase sigma0/sigma1 (FIPS-180-4 4.1.2):          *)
(*   sigma0(x) = ROTR7 x XOR ROTR18 x XOR SHR3  x                              *)
(*   sigma1(x) = ROTR17 x XOR ROTR19 x XOR SHR10 x                             *)
(* The asm realises sigma0 as  shr(x,3) XOR ror(ror(x,11) XOR x, 7)  (r12d     *)
(* chain: r12=x; r13=ror(x,11); r13=r13 XOR x; r12=shr(x,3); r13=ror(r13,7);   *)
(* r12 = r13 XOR r12), and sigma1 as  ror(ror(x,2) XOR x, 17) XOR shr(x,10)    *)
(* (r15d chain, symmetric).  Both are pure bit-vector identities (WORD_BLAST). *)
(* ========================================================================= *)

(* sigma0(x): the r12d ror/shr chain  shr(x,3) XOR ror(ror(x,11) XOR x, 7).   *)
let SHA256_LSIGMA0_ALU = prove
 (`!x:int32. word_xor (word_ushr x 3) (word_ror (word_xor (word_ror x 11) x) 7) =
             sha256_sigma0 x`,
  REWRITE_TAC[sha256_sigma0] THEN CONV_TAC WORD_BLAST);;

(* sigma1(x): the r15d ror/shr chain  ror(ror(x,2) XOR x, 17) XOR shr(x,10).  *)
let SHA256_LSIGMA1_ALU = prove
 (`!x:int32. word_xor (word_ror (word_xor (word_ror x 2) x) 17) (word_ushr x 10) =
             sha256_sigma1 x`,
  REWRITE_TAC[sha256_sigma1] THEN CONV_TAC WORD_BLAST);;

(* The schedule recurrence (FIPS-180-4 6.2.2), in the exact flat left-nested   *)
(* shape the asm accumulates it:                                               *)
(*   W[t] = ((sigma0(W[t-15]) + W[t-7]) + W[t-16]) + sigma1(W[t-2])            *)
(* (asm order: r12 = sigma0(W[t-15]); += W[t-7]; += W[t-16]; += sigma1(W[t-2]) *)
(* where the four stack slots feed t-15, t-7, t-16, t-2 respectively).  Folds  *)
(* one spec recurrence step (WORD_RULE absorbs the re-association).             *)
let SHA256_W_RECUR = prove
 (`!m t. 16 <= t ==>
     word_add
       (word_add (word_add (sha256_sigma0 (sha256_W m (t - 15))) (sha256_W m (t - 7)))
                 (sha256_W m (t - 16)))
       (sha256_sigma1 (sha256_W m (t - 2))) = sha256_W m t`,
  REPEAT STRIP_TAC THEN GEN_REWRITE_TAC RAND_CONV [sha256_W] THEN
  COND_CASES_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN CONV_TAC WORD_RULE);;

(* ========================================================================= *)
(* Phase 4: first fold of the Phase-3 round bridge against real symbolic      *)
(* execution, WITH memory.  This proves one round (round 0 of the prologue)   *)
(* of sha256_block_data_order_nohw as an `ensures x86`, exercising:           *)
(*   - the rodata K-table address threaded through the spec as a quantified   *)
(*     variable `kbytes` (the WHOLE_READONLY / K256 base), reached by the     *)
(*     "leaq K256(%rip),%rbp" whose riprel result is folded to `word kbytes`  *)
(*     via RIP_REL_ADDR_FOLD;                                                 *)
(*   - the message load + bswap ("mov (%rsi),%r12d; bswapl %r12d"), whose     *)
(*     output `word_bytereverse (word_bytereverse (m 0))` folds to `m 0`;     *)
(*   - the K materialisation ("addl (%rbp),%r12d"), whose value is read out   *)
(*     of the .rodata bytelist via the EXPLODE_BYTELIST_ASSUM_TAC /           *)
(*     INTRO_READ_MEMORY_FROM_BYTES8_TAC idiom (cf. x86/tutorial/rodata.ml);  *)
(*   - the byte-swapped W store to the stack ("mov %r12d,(%rsp)");            *)
(*   - the fold of the resulting deeply-nested ALU expression back onto       *)
(*     sha256_compress_round via SHA256_COMPRESS_ROUND_ALU.                   *)
(*                                                                           *)
(* Round 0 spans tmc offsets [0x4e, 0xc2) (35 instructions counting the       *)
(* 2-instruction loop preamble + the rip-relative LEA).  The loop-entry       *)
(* working-variable mapping is eax=a ebx=b ecx=c edx=d r8d=e r9d=f r10d=g     *)
(* r11d=h; after round 0 the new e' lands in edx (=EL 4 of the round output)  *)
(* and the new a' lands in r11d (=EL 0), with the other six registers         *)
(* unchanged.                                                                 *)
(*                                                                           *)
(* IMPORTANT modelling points discovered here (carry forward to the full      *)
(* 4-round group and beyond):                                                 *)
(*   1. State register pre/postconditions MUST use the full 64-bit reads      *)
(*      `read RDX s = word_zx d` (NOT `read EDX s = d`).  The named 32-bit    *)
(*      lenses are `bottom_32` and leave the upper half unconstrained, so the *)
(*      stepper drops the written-register facts entirely.                    *)
(*   2. The goal MUST carry nonoverlapping of the stack-write region against  *)
(*      BOTH the .rodata K table and the input data buffer, or the stepper    *)
(*      discards the K-table read / quantified-data read when the W-store     *)
(*      fires, and the subsequent K-load / W-load cannot resolve.             *)
(*   3. State the CORE fragment with the explicit MAYCHANGE register list     *)
(*      (not MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI) so that               *)
(*      ENSURES_FINAL_STATE_TAC's automatic frame discharge closes the        *)
(*      trailing MAYCHANGE.  The ABI frame is introduced by the subroutine    *)
(*      wrapper in a later phase.                                             *)
(*                                                                           *)
(* These two helper tactics are lifted verbatim from x86/tutorial/rodata.ml   *)
(* (where they are used for exactly this readonly-bytelist -> structured-int  *)
(* materialisation); they are reproduced here so this proof file is           *)
(* self-contained.                                                           *)
(* ========================================================================= *)

let INTRO_READ_MEMORY_FROM_BYTES8_TAC (t:term) =
  let r = REWRITE_CONV [READ_MEMORY_BYTESIZED_SPLIT] t in
  let r = REWRITE_RULE[WORD_ADD_ASSOC_CONSTS;WORD_ADD_0;ARITH] r in
  MP_TAC r THEN
  ASM (GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV)) [] THEN
  CONV_TAC (LAND_CONV WORD_REDUCE_CONV) THEN
  DISCH_TAC;;

let EXPLODE_BYTELIST_ASSUM_TAC const_data =
  FIRST_X_ASSUM (fun th ->
    let _ = find_term (fun t -> name_of t = "bytelist") (concl th) in
    let unfolded_bytes_loaded = REWRITE_RULE const_data th in
    MP_TAC (CONV_RULE (ONCE_DEPTH_CONV LENGTH_CONV THENC
                      LAND_CONV BYTELIST_EXPAND_CONV)
            unfolded_bytes_loaded)) THEN
  REWRITE_TAC [CONS_11] THEN
  STRIP_TAC;;

let SHA256_BLOCK_DATA_ORDER_NOHW_ROUND0 = prove
 (`!a b c d e f g h:int32. !m:num->int32. !kbytes:num. !pc stackpointer:int64.
   !datap:int64.
    riprel32_within_bounds kbytes (pc + 0x57) /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x4e) /\
              read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
              read RSI s = datap /\ read RSP s = stackpointer /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s =
                       word_bytereverse(m t)) /\
              read RAX s = word_zx a /\ read RBX s = word_zx b /\
              read RCX s = word_zx c /\ read RDX s = word_zx d /\
              read R8 s = word_zx e /\ read R9 s = word_zx f /\
              read R10 s = word_zx g /\ read R11 s = word_zx h)
         (\s. read RIP s = word (pc + 0xc2) /\
              read RDX s = word_zx (EL 4 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
              read R11 s = word_zx (EL 0 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))
         (MAYCHANGE [RIP; RDI; RBP; RDX; R11; R12; R13; R14; R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--2) THEN
  (*** Fold the rip-relative LEA so `read RBP s = word kbytes`. ***)
  FIRST_X_ASSUM (fun th -> MP_TAC th THEN IMP_REWRITE_TAC[RIP_REL_ADDR_FOLD] THEN
                           DISCH_TAC) THEN
  (*** Specialise the quantified message-word read for round 0 (t = 0). Use
       FIRST_ASSUM (non-consuming) so the quantified read survives. ***)
  FIRST_ASSUM(MP_TAC o SPEC `0` o check (is_forall o concl)) THEN
  CONV_TAC(LAND_CONV(ONCE_DEPTH_CONV NUM_REDUCE_CONV)) THEN
  REWRITE_TAC[WORD_ADD_0; MULT_CLAUSES] THEN DISCH_TAC THEN
  (*** Materialise the round-0 K constant from the .rodata bytelist. ***)
  SUBGOAL_THEN `read (memory :> bytes32 (word kbytes)) s2 = word 0x428a2f98`
    ASSUME_TAC THENL
   [EXPLODE_BYTELIST_ASSUM_TAC sha256_block_data_order_nohw_constants_data THEN
    FIRST_X_ASSUM(STRIP_ASSUME_TAC o check (fun th ->
      can (find_term (fun t -> name_of t = "bytes8")) (concl th))) THEN
    (fun (asl,w) -> INTRO_READ_MEMORY_FROM_BYTES8_TAC (lhs w) (asl,w)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (*** Symbolically execute the rest of round 0. ***)
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (3--35) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  (*** Fold each changed register (e' in RDX, a' in R11) back onto the spec
       round via the Phase-3 bridge, collapsing the 32->64->32 word_zx
       round-trips and the double bswap, then ring-normalising. ***)
  REPEAT CONJ_TAC THEN
  REWRITE_TAC[SHA256_COMPRESS_ROUND_ALU] THEN CONV_TAC(DEPTH_CONV EL_CONV) THEN
  SIMP_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH;
           WORD_BYTEREVERSE_BYTEREVERSE] THEN
  GEN_REWRITE_TAC (ONCE_DEPTH_CONV) [sha256_W] THEN
  REWRITE_TAC[ARITH_RULE `~(0 < 16) <=> F`; LT_REFL] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[sha256_K] THEN CONV_TAC(DEPTH_CONV EL_CONV) THEN
  CONV_TAC WORD_REDUCE_CONV THEN AP_TERM_TAC THEN CONV_TAC WORD_RULE);;

(* ========================================================================= *)
(* Phase 4 (continued): bridge infrastructure for the full first 4-round      *)
(* group, [tmc 0x4e, 0x1fd).  The 4-round `ensures` itself composes four      *)
(* 1-round folds at per-round cut-points; the reusable lemmas it needs --      *)
(* the EL-indexed round bridge and the round "shift-down" identities -- are    *)
(* proved here (both pure WORD_RULE/EL_CONV consequences of the Phase-3        *)
(* SHA256_COMPRESS_ROUND_ALU and the round-function ALU bridges).             *)
(*                                                                           *)
(* Cut-point plan (validated interactively round 0 -> round 1; see            *)
(* orchestrator session-007 notes for the remaining chaining detail):         *)
(*   - materialise ALL FOUR round constants K[0..3] up front from ONE         *)
(*     .rodata bytelist explode (EXPLODE_BYTELIST_ASSUM_TAC consumes the       *)
(*     bytelist read, so it must be done once for all four reads);            *)
(*   - after each ~32-instruction round, fold the two written working         *)
(*     registers (e' and a') back onto sha256_compress_round via the EL-form  *)
(*     bridge, expose the prior round's non-written inputs with the           *)
(*     shift identities, then discard the raw ALU hypotheses before the       *)
(*     next round.                                                            *)
(* Register rotation (e'/a' destinations): r0 e'=RDX a'=R11; r1 e'=RCX        *)
(* a'=R10; r2 e'=RBX a'=R9; r3 e'=RAX a'=R8.  After 4 rounds the working      *)
(* registers hold R8=EL0 R9=EL1 R10=EL2 R11=EL3 RAX=EL4 RBX=EL5 RCX=EL6       *)
(* RDX=EL7 of sha256_compress m 4 [a;b;c;d;e;f;g;h].                           *)
(* ========================================================================= *)

(* sha256_compress_round expressed on an OPAQUE length-8 state via EL i s, in *)
(* the exact flat ALU shape the assembly emits.  This is the fold target at   *)
(* each cut-point: with s := (sha256_compress m k S0) it rewrites the next    *)
(* round's output without expanding the running state.                        *)
let SHA256_COMPRESS_ROUND_ALU_EL = prove
 (`!m t s:int32 list.
     sha256_compress_round m t s =
     [word_add (word_add (word_xor (EL 1 s) (word_and (word_xor (EL 1 s) (EL 2 s)) (word_xor (EL 0 s) (EL 1 s))))
                 (word_add (word_add (word_add (word_add (sha256_W m t) (EL 7 s))
                              (word_xor (word_and (word_xor (EL 5 s) (EL 6 s)) (EL 4 s)) (EL 6 s)))
                            (EL t sha256_K))
                  (word_ror (word_xor (word_ror (word_xor (word_ror (EL 4 s) 14) (EL 4 s)) 5) (EL 4 s)) 6)))
               (word_ror (word_xor (word_ror (word_xor (word_ror (EL 0 s) 9) (EL 0 s)) 11) (EL 0 s)) 2);
      EL 0 s; EL 1 s; EL 2 s;
      word_add (EL 3 s)
               (word_add (word_add (word_add (word_add (sha256_W m t) (EL 7 s))
                              (word_xor (word_and (word_xor (EL 5 s) (EL 6 s)) (EL 4 s)) (EL 6 s)))
                            (EL t sha256_K))
                  (word_ror (word_xor (word_ror (word_xor (word_ror (EL 4 s) 14) (EL 4 s)) 5) (EL 4 s)) 6));
      EL 4 s; EL 5 s; EL 6 s]`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[sha256_compress_round] THEN CONV_TAC(DEPTH_CONV let_CONV) THEN
  REWRITE_TAC[SHA256_CH_ALU; SHA256_MAJ_ALU; SHA256_SIGMA0_ALU; SHA256_SIGMA1_ALU] THEN
  REWRITE_TAC[CONS_11] THEN CONV_TAC WORD_RULE);;

(* The six "shift-down" state elements of one compression round: positions      *)
(* 1,2,3,5,6,7 of the output are just positions 0,1,2,4,5,6 of the input        *)
(* (only positions 0 and 4 -- the new a' and e' -- are freshly computed).       *)
(* Used at each cut-point to expose round k's non-written inputs (which the      *)
(* assembly keeps in their original registers) when folding round k+1, so the   *)
(* opaque running state `sha256_compress m k S0` is only ever peeled one round   *)
(* at a time rather than fully expanded.                                         *)
let SHA256_CR_EL_SHIFT = prove
 (`(!m t s:int32 list. EL 1 (sha256_compress_round m t s) = EL 0 s) /\
   (!m t s:int32 list. EL 2 (sha256_compress_round m t s) = EL 1 s) /\
   (!m t s:int32 list. EL 3 (sha256_compress_round m t s) = EL 2 s) /\
   (!m t s:int32 list. EL 5 (sha256_compress_round m t s) = EL 4 s) /\
   (!m t s:int32 list. EL 6 (sha256_compress_round m t s) = EL 5 s) /\
   (!m t s:int32 list. EL 7 (sha256_compress_round m t s) = EL 6 s)`,
  REWRITE_TAC[SHA256_COMPRESS_ROUND_ALU_EL] THEN CONV_TAC(DEPTH_CONV EL_CONV) THEN
  REWRITE_TAC[]);;

(* The first four message words are direct (t < 16, so sha256_W m t = m t).     *)
(* Used by the per-round folds for the prologue rounds 0-3, whose message       *)
(* operand the assembly loads + bswaps straight from the data buffer.           *)
let SHA256_W_LO = prove
 (`(sha256_W m 0 = m 0) /\ (sha256_W m 1 = m 1) /\
   (sha256_W m 2 = m 2) /\ (sha256_W m 3 = m 3)`,
  REPEAT CONJ_TAC THEN GEN_REWRITE_TAC LAND_CONV [sha256_W] THEN
  REWRITE_TAC[ARITH_RULE `0<16`; ARITH_RULE `1<16`;
              ARITH_RULE `2<16`; ARITH_RULE `3<16`]);;

(* ========================================================================= *)
(* Phase 4 (continued): ROUND 1 of the prologue [tmc 0xc2, 0x12b), as an       *)
(* `ensures x86`.  This is the first chained per-round lemma: its precondition  *)
(* is exactly round 0's output, stated over an OPAQUE input working-state list  *)
(* `s` (LENGTH 8), so it composes with round 0 and feeds rounds 2/3.            *)
(*                                                                           *)
(* Two structural facts about the scalar nohw rounds make the chaining work:   *)
(*   1. Register roles RIGHT-ROTATE by one each round.  At round-1 entry the    *)
(*      eight working registers hold EL[0..7] s as                             *)
(*        R11=EL0 RAX=EL1 RBX=EL2 RCX=EL3 RDX=EL4 R8=EL5 R9=EL6 R10=EL7         *)
(*      (round 0 left a' in R11 / e' in RDX; everything else is a shifted copy  *)
(*      of round 0's input register).  Round 1 writes a' into R10 and e' into   *)
(*      RCX, giving the next rotation R10=EL0 R11=EL1 ... RCX=EL4 ...           *)
(*   2. The Maj `b XOR c` term is PIPELINED across rounds in a carry register   *)
(*      that ALTERNATES R15 <-> RDI.  Round 0 leaves `word_xor (EL1 s)(EL2 s)`  *)
(*      in R15 (= the `b XOR c` round 1's Maj consumes via AND); round 1 leaves *)
(*      `word_xor (EL1 (cr 1 s))(EL2 (cr 1 s))` in RDI for round 2.  The lemma  *)
(*      therefore carries the R15-in / RDI-out Maj term explicitly.            *)
(*                                                                           *)
(* The proof is mechanical: step the 32 round instructions, fold the six        *)
(* unchanged outputs with SHA256_CR_EL_SHIFT, then fold a'/e'/carry with the    *)
(* EL-indexed bridge SHA256_COMPRESS_ROUND_ALU_EL (the carry conjunct closes by *)
(* the word_zx round-trip collapse alone).  No K materialisation is needed in   *)
(* the body: round 1's K constant (table offset 4 = 1899447441) is supplied as  *)
(* a precondition, having been established once up front for the whole group.   *)
(* ========================================================================= *)

let SHA256_BLOCK_DATA_ORDER_NOHW_ROUND1 = prove
 (`!(s:int32 list). !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    LENGTH s = 8 /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0xc2) /\
              read RBP s' = word_add (word kbytes) (word 4) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 4))) s' =
                word 1899447441 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 8))) s' =
                word 3049323471 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 12))) s' =
                word 3921009573 /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' =
                       word_bytereverse(m t)) /\
              read R11 s' = word_zx (EL 0 s) /\ read RAX s' = word_zx (EL 1 s) /\
              read RBX s' = word_zx (EL 2 s) /\ read RCX s' = word_zx (EL 3 s) /\
              read RDX s' = word_zx (EL 4 s) /\ read R8 s' = word_zx (EL 5 s) /\
              read R9 s' = word_zx (EL 6 s) /\ read R10 s' = word_zx (EL 7 s) /\
              read R15 s' = word_zx (word_xor (EL 1 s) (EL 2 s)))
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x12b) /\
              read RBP s' = word_add (word kbytes) (word 8) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 4))) s' =
                word 1899447441 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 8))) s' =
                word 3049323471 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 12))) s' =
                word 3921009573 /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' =
                       word_bytereverse(m t)) /\
              read R10 s' = word_zx (EL 0 (sha256_compress_round m 1 s)) /\
              read R11 s' = word_zx (EL 1 (sha256_compress_round m 1 s)) /\
              read RAX s' = word_zx (EL 2 (sha256_compress_round m 1 s)) /\
              read RBX s' = word_zx (EL 3 (sha256_compress_round m 1 s)) /\
              read RCX s' = word_zx (EL 4 (sha256_compress_round m 1 s)) /\
              read RDX s' = word_zx (EL 5 (sha256_compress_round m 1 s)) /\
              read R8 s' = word_zx (EL 6 (sha256_compress_round m 1 s)) /\
              read R9 s' = word_zx (EL 7 (sha256_compress_round m 1 s)) /\
              read RDI s' = word_zx (word_xor (EL 1 (sha256_compress_round m 1 s))
                                              (EL 2 (sha256_compress_round m 1 s))))
         (MAYCHANGE [RIP; RDI; RBP; RCX; R10; R12; R13; R14; R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  (*** Specialise the quantified message read for round 1 (t = 1); FIRST_ASSUM
       keeps the forall for later rounds. ***)
  FIRST_ASSUM(MP_TAC o SPEC `1` o check (is_forall o concl)) THEN
  CONV_TAC(LAND_CONV(ONCE_DEPTH_CONV NUM_REDUCE_CONV)) THEN DISCH_TAC THEN
  (*** Step the 32 round-1 instructions. ***)
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--32) THEN
  ENSURES_FINAL_STATE_TAC THEN
  (*** The trailing `lea rbp,[rbp+4]` advances RBP from kbytes+4 to kbytes+8;
       normalise the nested constant add.  The three K-reads + data-forall are
       readonly and thread through untouched. ***)
  ASM_REWRITE_TAC[WORD_ADD_ASSOC_CONSTS] THEN CONV_TAC NUM_REDUCE_CONV THEN
  (*** Six unchanged registers are shifted copies of the input state. ***)
  REWRITE_TAC[SHA256_CR_EL_SHIFT] THEN
  (*** Fold a' (R10), e' (RCX) and the Maj carry (RDI) onto the spec round. ***)
  REPEAT CONJ_TAC THEN
  REWRITE_TAC[SHA256_COMPRESS_ROUND_ALU_EL] THEN
  SIMP_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH;
           WORD_BYTEREVERSE_BYTEREVERSE; WORD_ZX_TRIVIAL] THEN
  REWRITE_TAC[SHA256_W_LO] THEN
  REWRITE_TAC[sha256_K] THEN CONV_TAC(DEPTH_CONV EL_CONV) THEN
  CONV_TAC WORD_REDUCE_CONV THEN
  TRY(AP_TERM_TAC THEN CONV_TAC WORD_RULE));;

(* ========================================================================= *)
(* Phase 4 (continued): ROUNDS 2 and 3 of the prologue.  Identical mechanical *)
(* shape to ROUND1 -- the only changes are the shifted PC offsets, the K      *)
(* constant (table offsets 8 and 12 = 3049323471 and 3921009573), the         *)
(* one-step register rotation, and the Maj-carry register, which ALTERNATES:   *)
(*   round 1: carry-in R15  -> carry-out RDI                                   *)
(*   round 2: carry-in RDI  -> carry-out R15                                   *)
(*   round 3: carry-in R15  -> carry-out RDI                                   *)
(* After round 3 the eight working registers hold EL[0..7] of                  *)
(* sha256_compress_round m 3 (... m 2 (... m 1 (... m 0 ...))) in the          *)
(* canonical group-final layout R8=EL0 R9=EL1 R10=EL2 R11=EL3 RAX=EL4 RBX=EL5  *)
(* RCX=EL6 RDX=EL7, ready for either the compose step (Phase 4 group) or the   *)
(* next round group's round-4 load (Phase 5).                                  *)
(* ========================================================================= *)

let SHA256_BLOCK_DATA_ORDER_NOHW_ROUND2 = prove
 (`!(s:int32 list). !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    LENGTH s = 8 /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x12b) /\
              read RBP s' = word_add (word kbytes) (word 8) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 4))) s' =
                word 1899447441 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 8))) s' =
                word 3049323471 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 12))) s' =
                word 3921009573 /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' =
                       word_bytereverse(m t)) /\
              read R10 s' = word_zx (EL 0 s) /\ read R11 s' = word_zx (EL 1 s) /\
              read RAX s' = word_zx (EL 2 s) /\ read RBX s' = word_zx (EL 3 s) /\
              read RCX s' = word_zx (EL 4 s) /\ read RDX s' = word_zx (EL 5 s) /\
              read R8 s' = word_zx (EL 6 s) /\ read R9 s' = word_zx (EL 7 s) /\
              read RDI s' = word_zx (word_xor (EL 1 s) (EL 2 s)))
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x196) /\
              read RBP s' = word_add (word kbytes) (word 12) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 4))) s' =
                word 1899447441 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 8))) s' =
                word 3049323471 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 12))) s' =
                word 3921009573 /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' =
                       word_bytereverse(m t)) /\
              read R9 s' = word_zx (EL 0 (sha256_compress_round m 2 s)) /\
              read R10 s' = word_zx (EL 1 (sha256_compress_round m 2 s)) /\
              read R11 s' = word_zx (EL 2 (sha256_compress_round m 2 s)) /\
              read RAX s' = word_zx (EL 3 (sha256_compress_round m 2 s)) /\
              read RBX s' = word_zx (EL 4 (sha256_compress_round m 2 s)) /\
              read RCX s' = word_zx (EL 5 (sha256_compress_round m 2 s)) /\
              read RDX s' = word_zx (EL 6 (sha256_compress_round m 2 s)) /\
              read R8 s' = word_zx (EL 7 (sha256_compress_round m 2 s)) /\
              read R15 s' = word_zx (word_xor (EL 1 (sha256_compress_round m 2 s))
                                              (EL 2 (sha256_compress_round m 2 s))))
         (MAYCHANGE [RIP; RDI; RBP; RBX; R9; R12; R13; R14; R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  FIRST_ASSUM(MP_TAC o SPEC `2` o check (is_forall o concl)) THEN
  CONV_TAC(LAND_CONV(ONCE_DEPTH_CONV NUM_REDUCE_CONV)) THEN DISCH_TAC THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--32) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[WORD_ADD_ASSOC_CONSTS] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[SHA256_CR_EL_SHIFT] THEN
  REPEAT CONJ_TAC THEN
  REWRITE_TAC[SHA256_COMPRESS_ROUND_ALU_EL] THEN
  SIMP_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH;
           WORD_BYTEREVERSE_BYTEREVERSE; WORD_ZX_TRIVIAL] THEN
  REWRITE_TAC[SHA256_W_LO] THEN
  REWRITE_TAC[sha256_K] THEN CONV_TAC(DEPTH_CONV EL_CONV) THEN
  CONV_TAC WORD_REDUCE_CONV THEN
  TRY(AP_TERM_TAC THEN CONV_TAC WORD_RULE));;

let SHA256_BLOCK_DATA_ORDER_NOHW_ROUND3 = prove
 (`!(s:int32 list). !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    LENGTH s = 8 /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x196) /\
              read RBP s' = word_add (word kbytes) (word 12) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 4))) s' =
                word 1899447441 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 8))) s' =
                word 3049323471 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 12))) s' =
                word 3921009573 /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' =
                       word_bytereverse(m t)) /\
              read R9 s' = word_zx (EL 0 s) /\ read R10 s' = word_zx (EL 1 s) /\
              read R11 s' = word_zx (EL 2 s) /\ read RAX s' = word_zx (EL 3 s) /\
              read RBX s' = word_zx (EL 4 s) /\ read RCX s' = word_zx (EL 5 s) /\
              read RDX s' = word_zx (EL 6 s) /\ read R8 s' = word_zx (EL 7 s) /\
              read R15 s' = word_zx (word_xor (EL 1 s) (EL 2 s)))
         (\s'. read RIP s' = word (pc + 0x1fd) /\
              read R8 s' = word_zx (EL 0 (sha256_compress_round m 3 s)) /\
              read R9 s' = word_zx (EL 1 (sha256_compress_round m 3 s)) /\
              read R10 s' = word_zx (EL 2 (sha256_compress_round m 3 s)) /\
              read R11 s' = word_zx (EL 3 (sha256_compress_round m 3 s)) /\
              read RAX s' = word_zx (EL 4 (sha256_compress_round m 3 s)) /\
              read RBX s' = word_zx (EL 5 (sha256_compress_round m 3 s)) /\
              read RCX s' = word_zx (EL 6 (sha256_compress_round m 3 s)) /\
              read RDX s' = word_zx (EL 7 (sha256_compress_round m 3 s)))
         (MAYCHANGE [RIP; RDI; RBP; RAX; R8; R12; R13; R14; R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  FIRST_ASSUM(MP_TAC o SPEC `3` o check (is_forall o concl)) THEN
  CONV_TAC(LAND_CONV(ONCE_DEPTH_CONV NUM_REDUCE_CONV)) THEN DISCH_TAC THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--32) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[SHA256_CR_EL_SHIFT] THEN
  REPEAT CONJ_TAC THEN
  REWRITE_TAC[SHA256_COMPRESS_ROUND_ALU_EL] THEN
  SIMP_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH;
           WORD_BYTEREVERSE_BYTEREVERSE; WORD_ZX_TRIVIAL] THEN
  REWRITE_TAC[SHA256_W_LO] THEN
  REWRITE_TAC[sha256_K] THEN CONV_TAC(DEPTH_CONV EL_CONV) THEN
  CONV_TAC WORD_REDUCE_CONV THEN
  TRY(AP_TERM_TAC THEN CONV_TAC WORD_RULE));;

(* ========================================================================= *)
(* Phase 4 (continued): ROUND0_FULL -- round 0 [tmc 0x4e, 0xc2) with the FULL  *)
(* 8-register + Maj-carry (R15) postcondition over the concrete input         *)
(* [a;..;h], so it can be chained with ROUND1/2/3 to compose the whole         *)
(* 4-round group.  (The earlier SHA256_BLOCK_DATA_ORDER_NOHW_ROUND0 exposes    *)
(* only RDX/R11 and is the validated 1-round template; this is its full-state  *)
(* sibling for composition.)  Proof = ROUND0's setup (loop preamble + the      *)
(* rip-relative LEA fold to RBP = word kbytes, the K-table materialisation     *)
(* of all four prologue round constants up front from the .rodata bytelist)    *)
(* followed by the round-0 fold via the CONCRETE ALU bridge                    *)
(* SHA256_COMPRESS_ROUND_ALU.                                                  *)
(* ========================================================================= *)

(* Materialise the four prologue K constants at s2 (after RBP=word kbytes).    *)
let SHA256_NOHW_K4_AT_S2_TAC =
  SUBGOAL_THEN
   `read (memory :> bytes32 (word kbytes)) s2 = (word 0x428a2f98:int32) /\
    read (memory :> bytes32 (word_add (word kbytes) (word 4))) s2 = (word 0x71374491:int32) /\
    read (memory :> bytes32 (word_add (word kbytes) (word 8))) s2 = (word 0xb5c0fbcf:int32) /\
    read (memory :> bytes32 (word_add (word kbytes) (word 12))) s2 = (word 0xe9b5dba5:int32)`
   STRIP_ASSUME_TAC THENL
   [EXPLODE_BYTELIST_ASSUM_TAC sha256_block_data_order_nohw_constants_data THEN
    REPEAT CONJ_TAC THEN
    (fun (asl,w) -> INTRO_READ_MEMORY_FROM_BYTES8_TAC (lhs w) (asl,w)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC];;

let SHA256_BLOCK_DATA_ORDER_NOHW_ROUND0_FULL = prove
 (`!(a:int32) (b:int32) (c:int32) (d:int32) (e:int32) (f:int32) (g:int32) (h:int32).
   !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    riprel32_within_bounds kbytes (pc + 0x57) /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x4e) /\
              read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
              read RSI s = datap /\ read RSP s = stackpointer /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s =
                       word_bytereverse(m t)) /\
              read RAX s = word_zx a /\ read RBX s = word_zx b /\
              read RCX s = word_zx c /\ read RDX s = word_zx d /\
              read R8 s = word_zx e /\ read R9 s = word_zx f /\
              read R10 s = word_zx g /\ read R11 s = word_zx h)
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0xc2) /\
              read RBP s = word_add (word kbytes) (word 4) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 4))) s =
                word 1899447441 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 8))) s =
                word 3049323471 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 12))) s =
                word 3921009573 /\
              read RSI s = datap /\ read RSP s = stackpointer /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s =
                       word_bytereverse(m t)) /\
              read R11 s = word_zx (EL 0 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
              read RAX s = word_zx (EL 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
              read RBX s = word_zx (EL 2 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
              read RCX s = word_zx (EL 3 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
              read RDX s = word_zx (EL 4 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
              read R8 s = word_zx (EL 5 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
              read R9 s = word_zx (EL 6 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
              read R10 s = word_zx (EL 7 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
              read R15 s = word_zx (word_xor (EL 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))
                                             (EL 2 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))))
         (MAYCHANGE [RIP; RDI; RBP; RDX; R11; R12; R13; R14; R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--2) THEN
  FIRST_X_ASSUM (fun th -> MP_TAC th THEN IMP_REWRITE_TAC[RIP_REL_ADDR_FOLD] THEN
                           DISCH_TAC) THEN
  FIRST_ASSUM(MP_TAC o SPEC `0` o check (is_forall o concl)) THEN
  CONV_TAC(LAND_CONV(ONCE_DEPTH_CONV NUM_REDUCE_CONV)) THEN
  REWRITE_TAC[WORD_ADD_0; MULT_CLAUSES] THEN DISCH_TAC THEN
  SHA256_NOHW_K4_AT_S2_TAC THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (3--35) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[SHA256_CR_EL_SHIFT] THEN
  REWRITE_TAC[SHA256_COMPRESS_ROUND_ALU] THEN
  CONV_TAC(DEPTH_CONV EL_CONV) THEN
  REPEAT CONJ_TAC THEN
  SIMP_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH;
           WORD_BYTEREVERSE_BYTEREVERSE; WORD_ZX_TRIVIAL] THEN
  GEN_REWRITE_TAC (ONCE_DEPTH_CONV) [sha256_W] THEN
  REWRITE_TAC[ARITH_RULE `~(0 < 16) <=> F`; LT_REFL] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[sha256_K] THEN CONV_TAC(DEPTH_CONV EL_CONV) THEN
  CONV_TAC WORD_REDUCE_CONV THEN TRY(AP_TERM_TAC THEN CONV_TAC WORD_RULE));;

(* ========================================================================= *)
(* Phase 4 (final): compose the four per-round `ensures` lemmas into the      *)
(* complete first 4-round group [tmc 0x4e, 0x1fd).  Each round lemma's        *)
(* postcondition now re-establishes the next round's preconditions (the       *)
(* advanced RBP, the readonly K-reads K[1..3], RSI/RSP and the data-forall),  *)
(* so they chain via ENSURES_SEQUENCE_TAC at the three intermediate waypoints  *)
(* pc+0xc2, pc+0x12b, pc+0x196.  The group postcondition reassembles the four  *)
(* nested sha256_compress_round applications into sha256_compress m 4 in the   *)
(* canonical group-final register layout R8=EL0 R9=EL1 R10=EL2 R11=EL3         *)
(* RAX=EL4 RBX=EL5 RCX=EL6 RDX=EL7.                                            *)
(* ========================================================================= *)

(* sha256_compress m 4 unfolded to the four-deep nest of compression rounds.   *)
let SHA256_COMPRESS_4_UNFOLD = prove
 (`!m s:int32 list.
     sha256_compress m 4 s =
     sha256_compress_round m 3 (sha256_compress_round m 2
       (sha256_compress_round m 1 (sha256_compress_round m 0 s)))`,
  REWRITE_TAC[num_CONV `4`; num_CONV `3`; num_CONV `2`; num_CONV `1`] THEN
  REWRITE_TAC[sha256_compress]);;

(* Discharge an `ensures PRE Q WIDE` sequence subgoal with a narrow-frame round *)
(* lemma: subsume the (wide) group frame by the (narrow) round frame, then       *)
(* apply the lemma, re-deriving its ALL/nonoverlapping hypotheses from context.  *)
let APPLY_ROUND_TAC lemma =
  let cframe = rand(rand(concl(SPEC_ALL lemma))) in
  MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN EXISTS_TAC cframe THEN CONJ_TAC THENL
   [REWRITE_TAC[SOME_FLAGS] THEN SUBSUMED_MAYCHANGE_TAC;
    MATCH_MP_TAC lemma THEN
    ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES; SHA256_COMPRESS_ROUND_LENGTH]];;

let SHA256_BLOCK_DATA_ORDER_NOHW_4ROUNDS = prove
 (`!(a:int32) (b:int32) (c:int32) (d:int32) (e:int32) (f:int32) (g:int32) (h:int32).
   !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    riprel32_within_bounds kbytes (pc + 0x57) /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x4e) /\
              read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
              read RSI s = datap /\ read RSP s = stackpointer /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s =
                       word_bytereverse(m t)) /\
              read RAX s = word_zx a /\ read RBX s = word_zx b /\
              read RCX s = word_zx c /\ read RDX s = word_zx d /\
              read R8 s = word_zx e /\ read R9 s = word_zx f /\
              read R10 s = word_zx g /\ read R11 s = word_zx h)
         (\s. read RIP s = word (pc + 0x1fd) /\
              read R8 s  = word_zx (EL 0 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read R9 s  = word_zx (EL 1 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read R10 s = word_zx (EL 2 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read R11 s = word_zx (EL 3 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RAX s = word_zx (EL 4 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RBX s = word_zx (EL 5 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RCX s = word_zx (EL 6 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RDX s = word_zx (EL 7 (sha256_compress m 4 [a;b;c;d;e;f;g;h])))
         (MAYCHANGE [RIP; RDI; RBP; RAX; RBX; RCX; RDX; R8; R9; R10; R11;
                     R12; R13; R14; R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  REWRITE_TAC[SHA256_COMPRESS_4_UNFOLD] THEN
  (* waypoint pc+0xc2 : ROUND0_FULL output (input [a..h]) *)
  ENSURES_SEQUENCE_TAC `pc + 0xc2`
   `\s. read RBP s = word_add (word kbytes) (word 4) /\
        read (memory :> bytes32 (word_add (word kbytes) (word 4))) s = word 1899447441 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 8))) s = word 3049323471 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 12))) s = word 3921009573 /\
        read RSI s = datap /\ read RSP s = stackpointer /\
        (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s = word_bytereverse(m t)) /\
        read R11 s = word_zx (EL 0 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RAX s = word_zx (EL 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RBX s = word_zx (EL 2 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RCX s = word_zx (EL 3 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RDX s = word_zx (EL 4 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R8 s = word_zx (EL 5 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R9 s = word_zx (EL 6 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R10 s = word_zx (EL 7 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R15 s = word_zx (word_xor (EL 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))
                                       (EL 2 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))` THEN
  CONJ_TAC THENL
   [APPLY_ROUND_TAC SHA256_BLOCK_DATA_ORDER_NOHW_ROUND0_FULL; ALL_TAC] THEN
  (* waypoint pc+0x12b : ROUND1 output, input S1 = compress_round m 0 [a..] *)
  ENSURES_SEQUENCE_TAC `pc + 0x12b`
   `\s. read RBP s = word_add (word kbytes) (word 8) /\
        read (memory :> bytes32 (word_add (word kbytes) (word 4))) s = word 1899447441 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 8))) s = word 3049323471 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 12))) s = word 3921009573 /\
        read RSI s = datap /\ read RSP s = stackpointer /\
        (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s = word_bytereverse(m t)) /\
        read R10 s = word_zx (EL 0 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read R11 s = word_zx (EL 1 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RAX s = word_zx (EL 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RBX s = word_zx (EL 3 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RCX s = word_zx (EL 4 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RDX s = word_zx (EL 5 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read R8 s = word_zx (EL 6 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read R9 s = word_zx (EL 7 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RDI s = word_zx (word_xor (EL 1 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))
                                       (EL 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))))` THEN
  CONJ_TAC THENL
   [APPLY_ROUND_TAC (SPEC `sha256_compress_round m 0 [a;b;c;d;e;f;g;h]` SHA256_BLOCK_DATA_ORDER_NOHW_ROUND1); ALL_TAC] THEN
  (* waypoint pc+0x196 : ROUND2 output *)
  ENSURES_SEQUENCE_TAC `pc + 0x196`
   `\s. read RBP s = word_add (word kbytes) (word 12) /\
        read (memory :> bytes32 (word_add (word kbytes) (word 4))) s = word 1899447441 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 8))) s = word 3049323471 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 12))) s = word 3921009573 /\
        read RSI s = datap /\ read RSP s = stackpointer /\
        (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s = word_bytereverse(m t)) /\
        read R9 s = word_zx (EL 0 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read R10 s = word_zx (EL 1 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read R11 s = word_zx (EL 2 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read RAX s = word_zx (EL 3 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read RBX s = word_zx (EL 4 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read RCX s = word_zx (EL 5 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read RDX s = word_zx (EL 6 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read R8 s = word_zx (EL 7 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read R15 s = word_zx (word_xor (EL 1 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))))
                                       (EL 2 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))))` THEN
  CONJ_TAC THENL
   [APPLY_ROUND_TAC (SPEC `sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])` SHA256_BLOCK_DATA_ORDER_NOHW_ROUND2); ALL_TAC] THEN
  (* final segment: ROUND3, output is the group deliverable (RIP + 8 regs) *)
  APPLY_ROUND_TAC (SPEC `sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))` SHA256_BLOCK_DATA_ORDER_NOHW_ROUND3));;

(* ========================================================================= *)
(* PHASE 5 (begin): the same four per-round `ensures` lemmas as Phase 4, but   *)
(* AUGMENTED so that each round additionally captures the message word it       *)
(* stores to the stack scratch area.  Round t executes `movl %r12d, 4*t(%rsp)`  *)
(* (the bswapped data word `m t`), which Phase 4 discarded into the wide stack   *)
(* MAYCHANGE.  Phase 5 needs the loaded message in the stack window for the      *)
(* schedule-extension loop (Phase 6), so each `_W` lemma asserts                 *)
(*   read (memory :> bytes32 (stackpointer + 4*t)) s' = word_zx (m t)            *)
(* in its postcondition, and THREADS the W-prefix already stored by the earlier  *)
(* rounds (slots 0..t-1) through both pre and post: those slots are read-only    *)
(* across round t (which writes only slot t -- distinct concrete offsets inside  *)
(* the 64-byte frame, so the simulator preserves them automatically).            *)
(*                                                                           *)
(* Each `_W` proof is the Phase-4 proof verbatim plus the trailing W closer      *)
(* (the store folds to `m t` by the same WORD_ZX_ZX / WORD_BYTEREVERSE_BYTEREVERSE *)
(* round-trip collapse that the register conjuncts already use).  The wide       *)
(* `bytes(stackpointer,64)` MAYCHANGE is retained so the lemmas chain through     *)
(* ENSURES_SEQUENCE_TAC exactly as the Phase-4 group does.                        *)
(* ========================================================================= *)

(* Round 0, full-state + W[0].  (ROUND0_FULL with the W[0] stack-store conjunct.) *)
let SHA256_BLOCK_DATA_ORDER_NOHW_ROUND0_FULL_W = prove
 (`!(a:int32) (b:int32) (c:int32) (d:int32) (e:int32) (f:int32) (g:int32) (h:int32).
   !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    riprel32_within_bounds kbytes (pc + 0x57) /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x4e) /\
              read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
              read RSI s = datap /\ read RSP s = stackpointer /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s =
                       word_bytereverse(m t)) /\
              read RAX s = word_zx a /\ read RBX s = word_zx b /\
              read RCX s = word_zx c /\ read RDX s = word_zx d /\
              read R8 s = word_zx e /\ read R9 s = word_zx f /\
              read R10 s = word_zx g /\ read R11 s = word_zx h)
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0xc2) /\
              read RBP s = word_add (word kbytes) (word 4) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 4))) s =
                word 1899447441 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 8))) s =
                word 3049323471 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 12))) s =
                word 3921009573 /\
              read RSI s = datap /\ read RSP s = stackpointer /\
              read (memory :> bytes32 stackpointer) s = word_zx (m 0) /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s =
                       word_bytereverse(m t)) /\
