(* ========================================================================= *)
(* PHASE 5 (group 1): rounds 4-7 [tmc 0x1fd, 0x39f), W[4..7] tracked.          *)
(*                                                                           *)
(* These mirror the group-0 per-round `_W` lemmas one period up.  All four    *)
(* are pure INTERIOR rounds (the round-0-only K-materialisation-from-bytelist *)
(* preamble does not recur here): the four group-1 round constants            *)
(*   K[4]=0x3956c25b  K[5]=0x59f111f1  K[6]=0x923f82a4  K[7]=0xab1c5ed5        *)
(* are supplied as DIRECT bytes32 preconditions at kbytes+{32,36,40,44}       *)
(* (the K256 table is DOUBLED, so group g reads K[4g..4g+3] at byte 32g+...;   *)
(* group 1 enters with RBP = kbytes+32).  The Maj-carry b^c pipelines in via   *)
(* RDI at round-4 entry (= group 0's round-3 carry-out), alternating          *)
(* RDI->R15->RDI->R15 across rounds 4..7.  Register roles are the period-8     *)
(* rotation: at round-4 entry R8=EL0(a) R9=EL1 R10=EL2 R11=EL3 RAX=EL4(e)      *)
(* RBX=EL5 RCX=EL6 RDX=EL7 (= group-0 round-3 OUTPUT layout).  The trailing    *)
(* round-7 `lea 0x14(%rbp)` advances RBP by 20 (= +32 across the whole group). *)
(* W[4..7] store to stackpointer+{16,20,24,28}; W[0..3] thread through         *)
(* read-only under the wide bytes(stackpointer,64) MAYCHANGE.                  *)
(*                                                                           *)
(* Each proof is the group-0 round proof verbatim, with the message word fed   *)
(* by SHA256_W_LO16 (sha256_W m t = m t for t<16, covering t=4..7).            *)
(* ========================================================================= *)

(* sha256_W m t = m t for ALL t < 16 (group 0's SHA256_W_LO only had t<4).     *)
let SHA256_W_LO16 = prove
 (`(sha256_W m 0 = m 0) /\ (sha256_W m 1 = m 1) /\ (sha256_W m 2 = m 2) /\
   (sha256_W m 3 = m 3) /\ (sha256_W m 4 = m 4) /\ (sha256_W m 5 = m 5) /\
   (sha256_W m 6 = m 6) /\ (sha256_W m 7 = m 7) /\ (sha256_W m 8 = m 8) /\
   (sha256_W m 9 = m 9) /\ (sha256_W m 10 = m 10) /\ (sha256_W m 11 = m 11) /\
   (sha256_W m 12 = m 12) /\ (sha256_W m 13 = m 13) /\ (sha256_W m 14 = m 14) /\
   (sha256_W m 15 = m 15)`,
  REPEAT CONJ_TAC THEN GEN_REWRITE_TAC LAND_CONV [sha256_W] THEN
  CONV_TAC NUM_REDUCE_CONV);;

(* Round 4 + W[4], threading W[0..3].  Entry tmc 0x1fd -> 0x267. *)
let SHA256_BLOCK_DATA_ORDER_NOHW_ROUND4_W = prove
 (`!(s:int32 list). !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    LENGTH s = 8 /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x1fd) /\
              read RBP s' = word_add (word kbytes) (word 32) /\
