              read (memory :> bytes32 stackpointer) s' = word_zx (m 0) /\
              read (memory :> bytes32 (word_add stackpointer (word 4))) s' = word_zx (m 1) /\
              read (memory :> bytes32 (word_add stackpointer (word 8))) s' = word_zx (m 2) /\
              read (memory :> bytes32 (word_add stackpointer (word 12))) s' = word_zx (m 3) /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' =
                       word_bytereverse(m t)) /\
              read R8 s' = word_zx (EL 0 s) /\ read R9 s' = word_zx (EL 1 s) /\
              read R10 s' = word_zx (EL 2 s) /\ read R11 s' = word_zx (EL 3 s) /\
              read RAX s' = word_zx (EL 4 s) /\ read RBX s' = word_zx (EL 5 s) /\
              read RCX s' = word_zx (EL 6 s) /\ read RDX s' = word_zx (EL 7 s) /\
              read RDI s' = word_zx (word_xor (EL 1 s) (EL 2 s)))
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x267) /\
              read RBP s' = word_add (word kbytes) (word 36) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 32))) s' =
                word 961987163 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 36))) s' =
                word 1508970993 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 40))) s' =
                word 2453635748 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 44))) s' =
                word 2870763221 /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              read (memory :> bytes32 stackpointer) s' = word_zx (m 0) /\
              read (memory :> bytes32 (word_add stackpointer (word 4))) s' = word_zx (m 1) /\
              read (memory :> bytes32 (word_add stackpointer (word 8))) s' = word_zx (m 2) /\
              read (memory :> bytes32 (word_add stackpointer (word 12))) s' = word_zx (m 3) /\
              read (memory :> bytes32 (word_add stackpointer (word 16))) s' = word_zx (m 4) /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' =
                       word_bytereverse(m t)) /\
              read RDX s' = word_zx (EL 0 (sha256_compress_round m 4 s)) /\
              read R8 s' = word_zx (EL 1 (sha256_compress_round m 4 s)) /\
              read R9 s' = word_zx (EL 2 (sha256_compress_round m 4 s)) /\
              read R10 s' = word_zx (EL 3 (sha256_compress_round m 4 s)) /\
              read R11 s' = word_zx (EL 4 (sha256_compress_round m 4 s)) /\
              read RAX s' = word_zx (EL 5 (sha256_compress_round m 4 s)) /\
              read RBX s' = word_zx (EL 6 (sha256_compress_round m 4 s)) /\
              read RCX s' = word_zx (EL 7 (sha256_compress_round m 4 s)) /\
              read R15 s' = word_zx (word_xor (EL 1 (sha256_compress_round m 4 s))
                                              (EL 2 (sha256_compress_round m 4 s))))
         (MAYCHANGE [RIP; RDI; RBP; RDX; R11; R12; R13; R14; R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  FIRST_ASSUM(MP_TAC o SPEC `4` o check (is_forall o concl)) THEN
  CONV_TAC(LAND_CONV(ONCE_DEPTH_CONV NUM_REDUCE_CONV)) THEN DISCH_TAC THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--32) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[WORD_ADD_ASSOC_CONSTS] THEN CONV_TAC NUM_REDUCE_CONV THEN
