let SHA256_COMPRESS_16_UNFOLD = prove
 (`!m s:int32 list.
     sha256_compress m 16 s =
     sha256_compress_round m 15 (sha256_compress_round m 14 (sha256_compress_round m 13 (sha256_compress_round m 12 (sha256_compress_round m 11 (sha256_compress_round m 10 (sha256_compress_round m 9 (sha256_compress_round m 8 (sha256_compress_round m 7 (sha256_compress_round m 6 (sha256_compress_round m 5 (sha256_compress_round m 4 (sha256_compress_round m 3 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 s)))))))))))))))`,
  REWRITE_TAC[num_CONV `16`; num_CONV `15`; num_CONV `14`; num_CONV `13`;
              num_CONV `12`; num_CONV `11`; num_CONV `10`; num_CONV `9`;
              num_CONV `8`; num_CONV `7`; num_CONV `6`; num_CONV `5`;
              num_CONV `4`; num_CONV `3`; num_CONV `2`; num_CONV `1`] THEN
  REWRITE_TAC[sha256_compress]);;

(* ========================================================================= *)
(* Wide group-0 final round + wide GROUP0_W, for the prologue compose.        *)
(* ROUND3_W_WIDE is ROUND3_W with a post that ALSO exposes the group-1 entry  *)
(* facts RBP=kbytes+32, RSI/RSP, the data-forall and the RDI Maj-carry (all    *)
(* established by group 0's execution) -- everything GROUP1_W's precondition    *)
(* needs at tmc 0x1fd EXCEPT the next group's K[4..7] table reads, which group  *)
(* 0 never touches and are instead threaded read-only via ENSURES_FRAME_RO.    *)
(* GROUP0_W_WIDE chains the same four round folds as GROUP0_W but ends on        *)
(* ROUND3_W_WIDE, so its post is the (K[4..7]-free) group-1 entry state.        *)
(* ========================================================================= *)

(* Wide ROUND3: same proof as ROUND3_W but a post exposing RBP=kbytes+32, RSI, RSP,
   data-forall, RDI carry (group-1 entry state at 0x1fd), WITHOUT K[4..7]. *)
let SHA256_BLOCK_DATA_ORDER_NOHW_ROUND3_W_WIDE = prove
 (`!(s:int32 list). !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    LENGTH s = 8 /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x196) /\
              read RBP s' = word_add (word kbytes) (word 12) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 4))) s' =
                word 1899447441 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 8))) s' =
                word 3049323471 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 12))) s' =
                word 3921009573 /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              read (memory :> bytes32 stackpointer) s' = word_zx (m 0) /\
              read (memory :> bytes32 (word_add stackpointer (word 4))) s' = word_zx (m 1) /\
              read (memory :> bytes32 (word_add stackpointer (word 8))) s' = word_zx (m 2) /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' =
                       word_bytereverse(m t)) /\
              read R9 s' = word_zx (EL 0 s) /\ read R10 s' = word_zx (EL 1 s) /\
              read R11 s' = word_zx (EL 2 s) /\ read RAX s' = word_zx (EL 3 s) /\
              read RBX s' = word_zx (EL 4 s) /\ read RCX s' = word_zx (EL 5 s) /\
              read RDX s' = word_zx (EL 6 s) /\ read R8 s' = word_zx (EL 7 s) /\
              read R15 s' = word_zx (word_xor (EL 1 s) (EL 2 s)))
         (\s'. read RIP s' = word (pc + 0x1fd) /\
              read RBP s' = word_add (word kbytes) (word 32) /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              read (memory :> bytes32 (stackpointer)) s' = word_zx (m 0) /\
              read (memory :> bytes32 (word_add stackpointer (word 4))) s' = word_zx (m 1) /\
              read (memory :> bytes32 (word_add stackpointer (word 8))) s' = word_zx (m 2) /\
              read (memory :> bytes32 (word_add stackpointer (word 12))) s' = word_zx (m 3) /\
              (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' = word_bytereverse(m t)) /\
              read R8 s' = word_zx (EL 0 (sha256_compress_round m 3 s)) /\
              read R9 s' = word_zx (EL 1 (sha256_compress_round m 3 s)) /\
              read R10 s' = word_zx (EL 2 (sha256_compress_round m 3 s)) /\
              read R11 s' = word_zx (EL 3 (sha256_compress_round m 3 s)) /\
              read RAX s' = word_zx (EL 4 (sha256_compress_round m 3 s)) /\
              read RBX s' = word_zx (EL 5 (sha256_compress_round m 3 s)) /\
              read RCX s' = word_zx (EL 6 (sha256_compress_round m 3 s)) /\
              read RDX s' = word_zx (EL 7 (sha256_compress_round m 3 s)) /\
              read RDI s' = word_zx (word_xor (EL 1 (sha256_compress_round m 3 s)) (EL 2 (sha256_compress_round m 3 s))))
         (MAYCHANGE [RIP; RDI; RBP; RAX; R8; R12; R13; R14; R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  FIRST_ASSUM(MP_TAC o SPEC `3` o check (is_forall o concl)) THEN
  CONV_TAC(LAND_CONV(ONCE_DEPTH_CONV NUM_REDUCE_CONV)) THEN DISCH_TAC THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--32) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[WORD_ADD_ASSOC_CONSTS] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[SHA256_CR_EL_SHIFT] THEN
  REPEAT CONJ_TAC THEN
  REWRITE_TAC[SHA256_COMPRESS_ROUND_ALU_EL] THEN
  SIMP_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH;
           WORD_BYTEREVERSE_BYTEREVERSE; WORD_ZX_TRIVIAL] THEN
  REWRITE_TAC[SHA256_W_LO] THEN
  REWRITE_TAC[sha256_K] THEN CONV_TAC(DEPTH_CONV EL_CONV) THEN
  CONV_TAC WORD_REDUCE_CONV THEN
  TRY(AP_TERM_TAC THEN CONV_TAC WORD_RULE));;


let SHA256_BLOCK_DATA_ORDER_NOHW_GROUP0_W_WIDE = prove
 (`!(a:int32) (b:int32) (c:int32) (d:int32) (e:int32) (f:int32) (g:int32) (h:int32).
   !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    riprel32_within_bounds kbytes (pc + 0x57) /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x4e) /\
              read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
              read RSI s = datap /\ read RSP s = stackpointer /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s =
                       word_bytereverse(m t)) /\
              read RAX s = word_zx a /\ read RBX s = word_zx b /\
              read RCX s = word_zx c /\ read RDX s = word_zx d /\
              read R8 s = word_zx e /\ read R9 s = word_zx f /\
              read R10 s = word_zx g /\ read R11 s = word_zx h)
         (\s. read RIP s = word (pc + 0x1fd) /\
              read RBP s = word_add (word kbytes) (word 32) /\
              read RSI s = datap /\ read RSP s = stackpointer /\
              read (memory :> bytes32 (stackpointer)) s = word_zx (m 0) /\
              read (memory :> bytes32 (word_add stackpointer (word 4))) s = word_zx (m 1) /\
              read (memory :> bytes32 (word_add stackpointer (word 8))) s = word_zx (m 2) /\
              read (memory :> bytes32 (word_add stackpointer (word 12))) s = word_zx (m 3) /\
              (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s = word_bytereverse(m t)) /\
              read R8 s = word_zx (EL 0 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read R9 s = word_zx (EL 1 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read R10 s = word_zx (EL 2 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read R11 s = word_zx (EL 3 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RAX s = word_zx (EL 4 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RBX s = word_zx (EL 5 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RCX s = word_zx (EL 6 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RDX s = word_zx (EL 7 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RDI s = word_zx (word_xor (EL 1 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) (EL 2 (sha256_compress m 4 [a;b;c;d;e;f;g;h]))))
         (MAYCHANGE [RIP; RDI; RBP; RAX; RBX; RCX; RDX; R8; R9; R10; R11;
                     R12; R13; R14; R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  REWRITE_TAC[SHA256_COMPRESS_4_UNFOLD] THEN
  (* waypoint pc+0xc2 : ROUND0_FULL_W output + W[0] *)
  ENSURES_SEQUENCE_TAC `pc + 0xc2`
   `\s. read RBP s = word_add (word kbytes) (word 4) /\
        read (memory :> bytes32 (word_add (word kbytes) (word 4))) s = word 1899447441 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 8))) s = word 3049323471 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 12))) s = word 3921009573 /\
        read RSI s = datap /\ read RSP s = stackpointer /\
        read (memory :> bytes32 stackpointer) s = word_zx (m 0) /\
        (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s = word_bytereverse(m t)) /\
        read R11 s = word_zx (EL 0 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RAX s = word_zx (EL 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RBX s = word_zx (EL 2 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RCX s = word_zx (EL 3 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RDX s = word_zx (EL 4 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R8 s = word_zx (EL 5 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R9 s = word_zx (EL 6 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R10 s = word_zx (EL 7 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R15 s = word_zx (word_xor (EL 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))
                                       (EL 2 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))` THEN
  CONJ_TAC THENL
   [APPLY_ROUND_TAC SHA256_BLOCK_DATA_ORDER_NOHW_ROUND0_FULL_W; ALL_TAC] THEN
  (* waypoint pc+0x12b : ROUND1_W output + W[0..1] *)
  ENSURES_SEQUENCE_TAC `pc + 0x12b`
   `\s. read RBP s = word_add (word kbytes) (word 8) /\
        read (memory :> bytes32 (word_add (word kbytes) (word 4))) s = word 1899447441 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 8))) s = word 3049323471 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 12))) s = word 3921009573 /\
        read RSI s = datap /\ read RSP s = stackpointer /\
        read (memory :> bytes32 stackpointer) s = word_zx (m 0) /\
        read (memory :> bytes32 (word_add stackpointer (word 4))) s = word_zx (m 1) /\
        (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s = word_bytereverse(m t)) /\
        read R10 s = word_zx (EL 0 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read R11 s = word_zx (EL 1 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RAX s = word_zx (EL 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RBX s = word_zx (EL 3 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RCX s = word_zx (EL 4 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RDX s = word_zx (EL 5 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read R8 s = word_zx (EL 6 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read R9 s = word_zx (EL 7 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RDI s = word_zx (word_xor (EL 1 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))
                                       (EL 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))))` THEN
  CONJ_TAC THENL
   [APPLY_ROUND_TAC (SPEC `sha256_compress_round m 0 [a;b;c;d;e;f;g;h]` SHA256_BLOCK_DATA_ORDER_NOHW_ROUND1_W); ALL_TAC] THEN
  (* waypoint pc+0x196 : ROUND2_W output + W[0..2] *)
  ENSURES_SEQUENCE_TAC `pc + 0x196`
   `\s. read RBP s = word_add (word kbytes) (word 12) /\
        read (memory :> bytes32 (word_add (word kbytes) (word 4))) s = word 1899447441 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 8))) s = word 3049323471 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 12))) s = word 3921009573 /\
        read RSI s = datap /\ read RSP s = stackpointer /\
        read (memory :> bytes32 stackpointer) s = word_zx (m 0) /\
        read (memory :> bytes32 (word_add stackpointer (word 4))) s = word_zx (m 1) /\
        read (memory :> bytes32 (word_add stackpointer (word 8))) s = word_zx (m 2) /\
        (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s = word_bytereverse(m t)) /\
        read R9 s = word_zx (EL 0 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read R10 s = word_zx (EL 1 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read R11 s = word_zx (EL 2 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read RAX s = word_zx (EL 3 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read RBX s = word_zx (EL 4 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read RCX s = word_zx (EL 5 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read RDX s = word_zx (EL 6 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read R8 s = word_zx (EL 7 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))) /\
        read R15 s = word_zx (word_xor (EL 1 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))))
                                       (EL 2 (sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))))` THEN
  CONJ_TAC THENL
   [APPLY_ROUND_TAC (SPEC `sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])` SHA256_BLOCK_DATA_ORDER_NOHW_ROUND2_W); ALL_TAC] THEN
  (* final segment: ROUND3_W -> group deliverable (RIP + W[0..3] + 8 regs) *)
  APPLY_ROUND_TAC (SPEC `sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))` SHA256_BLOCK_DATA_ORDER_NOHW_ROUND3_W_WIDE));;

(* K[4..15] concrete table reads materialized from the readonly K256 bytelist. *)
(* Group 0 consumes the bytelist for K[0..3] internally; this lemma supplies the *)
(* later groups' K-blocks (groups 1,2,3) so they can be threaded read-only       *)
(* across the prologue seams via ENSURES_FRAME_RO.                                *)
let SHA256_NOHW_KVALS_4_15 = prove
 (`!kbytes:num. !x:x86state.
     read (memory :> bytelist (word kbytes, LENGTH K256_data)) x = K256_data
     ==> read (memory :> bytes32 (word_add (word kbytes) (word 32))) x = word 961987163 /\
         read (memory :> bytes32 (word_add (word kbytes) (word 36))) x = word 1508970993 /\
         read (memory :> bytes32 (word_add (word kbytes) (word 40))) x = word 2453635748 /\
         read (memory :> bytes32 (word_add (word kbytes) (word 44))) x = word 2870763221 /\
         read (memory :> bytes32 (word_add (word kbytes) (word 64))) x = word 3624381080 /\
         read (memory :> bytes32 (word_add (word kbytes) (word 68))) x = word 310598401 /\
         read (memory :> bytes32 (word_add (word kbytes) (word 72))) x = word 607225278 /\
         read (memory :> bytes32 (word_add (word kbytes) (word 76))) x = word 1426881987 /\
         read (memory :> bytes32 (word_add (word kbytes) (word 96))) x = word 1925078388 /\
         read (memory :> bytes32 (word_add (word kbytes) (word 100))) x = word 2162078206 /\
         read (memory :> bytes32 (word_add (word kbytes) (word 104))) x = word 2614888103 /\
         read (memory :> bytes32 (word_add (word kbytes) (word 108))) x = word 3248222580`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  EXPLODE_BYTELIST_ASSUM_TAC sha256_block_data_order_nohw_constants_data THEN
  REPEAT CONJ_TAC THEN
  (fun (asl,w) -> INTRO_READ_MEMORY_FROM_BYTES8_TAC (lhs w) (asl,w)) THEN
  ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* Wide group-0 variant whose POST additionally retains `bytes_loaded`        *)
(* (ROUND3_W_WIDE drops it).  The prologue compose chains GROUP0_W_WIDE2 ->    *)
(* GROUP1_W -> GROUP2_W -> GROUP3_W at the 0x1fd/0x39f/0x545 seams; GROUP1_W's *)
(* precondition (like every interior group) opens with `bytes_loaded`, so the  *)
(* group-0 post must supply it.  `bytes_loaded` is a code-region bytelist read *)
(* the simulator preserves automatically, so re-proving ROUND3_W with it in    *)
(* the post is the same proof script (ASM_REWRITE picks it up); framing it     *)
(* across the group via ENSURES_FRAME_RO is NOT viable (the bytelist-component *)
(* orthogonality won't reduce LENGTH on the opaque _tmc).                       *)
let SHA256_BLOCK_DATA_ORDER_NOHW_ROUND3_W_WIDE2 = prove
 (`!(s:int32 list). !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    LENGTH s = 8 /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x196) /\
              read RBP s' = word_add (word kbytes) (word 12) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 4))) s' =
                word 1899447441 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 8))) s' =
                word 3049323471 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 12))) s' =
                word 3921009573 /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              read (memory :> bytes32 stackpointer) s' = word_zx (m 0) /\
              read (memory :> bytes32 (word_add stackpointer (word 4))) s' = word_zx (m 1) /\
              read (memory :> bytes32 (word_add stackpointer (word 8))) s' = word_zx (m 2) /\
              (!t. t < 16
                   ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' =
                       word_bytereverse(m t)) /\
              read R9 s' = word_zx (EL 0 s) /\ read R10 s' = word_zx (EL 1 s) /\
              read R11 s' = word_zx (EL 2 s) /\ read RAX s' = word_zx (EL 3 s) /\
              read RBX s' = word_zx (EL 4 s) /\ read RCX s' = word_zx (EL 5 s) /\
              read RDX s' = word_zx (EL 6 s) /\ read R8 s' = word_zx (EL 7 s) /\
              read R15 s' = word_zx (word_xor (EL 1 s) (EL 2 s)))
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x1fd) /\
              read RBP s' = word_add (word kbytes) (word 32) /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              read (memory :> bytes32 (stackpointer)) s' = word_zx (m 0) /\
              read (memory :> bytes32 (word_add stackpointer (word 4))) s' = word_zx (m 1) /\
              read (memory :> bytes32 (word_add stackpointer (word 8))) s' = word_zx (m 2) /\
              read (memory :> bytes32 (word_add stackpointer (word 12))) s' = word_zx (m 3) /\
              (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' = word_bytereverse(m t)) /\
              read R8 s' = word_zx (EL 0 (sha256_compress_round m 3 s)) /\
              read R9 s' = word_zx (EL 1 (sha256_compress_round m 3 s)) /\
              read R10 s' = word_zx (EL 2 (sha256_compress_round m 3 s)) /\
              read R11 s' = word_zx (EL 3 (sha256_compress_round m 3 s)) /\
              read RAX s' = word_zx (EL 4 (sha256_compress_round m 3 s)) /\
              read RBX s' = word_zx (EL 5 (sha256_compress_round m 3 s)) /\
              read RCX s' = word_zx (EL 6 (sha256_compress_round m 3 s)) /\
              read RDX s' = word_zx (EL 7 (sha256_compress_round m 3 s)) /\
              read RDI s' = word_zx (word_xor (EL 1 (sha256_compress_round m 3 s)) (EL 2 (sha256_compress_round m 3 s))))
         (MAYCHANGE [RIP; RDI; RBP; RAX; R8; R12; R13; R14; R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  FIRST_ASSUM(MP_TAC o SPEC `3` o check (is_forall o concl)) THEN
  CONV_TAC(LAND_CONV(ONCE_DEPTH_CONV NUM_REDUCE_CONV)) THEN DISCH_TAC THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--32) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[WORD_ADD_ASSOC_CONSTS] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[SHA256_CR_EL_SHIFT] THEN
  REPEAT CONJ_TAC THEN
  REWRITE_TAC[SHA256_COMPRESS_ROUND_ALU_EL] THEN
  SIMP_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH;
           WORD_BYTEREVERSE_BYTEREVERSE; WORD_ZX_TRIVIAL] THEN
  REWRITE_TAC[SHA256_W_LO] THEN
  REWRITE_TAC[sha256_K] THEN CONV_TAC(DEPTH_CONV EL_CONV) THEN
  CONV_TAC WORD_REDUCE_CONV THEN
  TRY(AP_TERM_TAC THEN CONV_TAC WORD_RULE));;

(* GROUP0_W_WIDE with bytes_loaded retained in the post (ends on ROUND3_W_WIDE2). *)
let SHA256_BLOCK_DATA_ORDER_NOHW_GROUP0_W_WIDE2 = prove
 (`!(a:int32) (b:int32) (c:int32) (d:int32) (e:int32) (f:int32) (g:int32) (h:int32).
   !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    riprel32_within_bounds kbytes (pc + 0x57) /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x4e) /\
              read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
              read RSI s = datap /\ read RSP s = stackpointer /\
              (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s = word_bytereverse(m t)) /\
              read RAX s = word_zx a /\ read RBX s = word_zx b /\
              read RCX s = word_zx c /\ read RDX s = word_zx d /\
              read R8 s = word_zx e /\ read R9 s = word_zx f /\
              read R10 s = word_zx g /\ read R11 s = word_zx h)
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x1fd) /\
              read RBP s = word_add (word kbytes) (word 32) /\
              read RSI s = datap /\ read RSP s = stackpointer /\
              read (memory :> bytes32 (stackpointer)) s = word_zx (m 0) /\
              read (memory :> bytes32 (word_add stackpointer (word 4))) s = word_zx (m 1) /\
              read (memory :> bytes32 (word_add stackpointer (word 8))) s = word_zx (m 2) /\
              read (memory :> bytes32 (word_add stackpointer (word 12))) s = word_zx (m 3) /\
              (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s = word_bytereverse(m t)) /\
              read R8 s = word_zx (EL 0 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read R9 s = word_zx (EL 1 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read R10 s = word_zx (EL 2 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read R11 s = word_zx (EL 3 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RAX s = word_zx (EL 4 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RBX s = word_zx (EL 5 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RCX s = word_zx (EL 6 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RDX s = word_zx (EL 7 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) /\
              read RDI s = word_zx (word_xor (EL 1 (sha256_compress m 4 [a;b;c;d;e;f;g;h])) (EL 2 (sha256_compress m 4 [a;b;c;d;e;f;g;h]))))
         (MAYCHANGE [RIP; RDI; RBP; RAX; RBX; RCX; RDX; R8; R9; R10; R11;
                     R12; R13; R14; R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  REWRITE_TAC[SHA256_COMPRESS_4_UNFOLD] THEN
  ENSURES_SEQUENCE_TAC `pc + 0xc2`
   `\s. read RBP s = word_add (word kbytes) (word 4) /\
        read (memory :> bytes32 (word_add (word kbytes) (word 4))) s = word 1899447441 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 8))) s = word 3049323471 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 12))) s = word 3921009573 /\
        read RSI s = datap /\ read RSP s = stackpointer /\
        read (memory :> bytes32 stackpointer) s = word_zx (m 0) /\
        (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s = word_bytereverse(m t)) /\
        read R11 s = word_zx (EL 0 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RAX s = word_zx (EL 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RBX s = word_zx (EL 2 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RCX s = word_zx (EL 3 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read RDX s = word_zx (EL 4 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R8 s = word_zx (EL 5 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R9 s = word_zx (EL 6 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R10 s = word_zx (EL 7 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])) /\
        read R15 s = word_zx (word_xor (EL 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))
                                       (EL 2 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))` THEN
  CONJ_TAC THENL
   [APPLY_ROUND_TAC SHA256_BLOCK_DATA_ORDER_NOHW_ROUND0_FULL_W; ALL_TAC] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x12b`
   `\s. read RBP s = word_add (word kbytes) (word 8) /\
        read (memory :> bytes32 (word_add (word kbytes) (word 4))) s = word 1899447441 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 8))) s = word 3049323471 /\
        read (memory :> bytes32 (word_add (word kbytes) (word 12))) s = word 3921009573 /\
        read RSI s = datap /\ read RSP s = stackpointer /\
        read (memory :> bytes32 stackpointer) s = word_zx (m 0) /\
        read (memory :> bytes32 (word_add stackpointer (word 4))) s = word_zx (m 1) /\
        (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s = word_bytereverse(m t)) /\
        read R10 s = word_zx (EL 0 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read R11 s = word_zx (EL 1 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RAX s = word_zx (EL 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RBX s = word_zx (EL 3 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RCX s = word_zx (EL 4 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RDX s = word_zx (EL 5 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read R8 s = word_zx (EL 6 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read R9 s = word_zx (EL 7 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))) /\
        read RDI s = word_zx (word_xor (EL 1 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h])))
