  APPLY_ROUND_TAC (SPEC `sha256_compress_round m 2 (sha256_compress_round m 1 (sha256_compress_round m 0 [a;b;c;d;e;f;g;h]))` SHA256_BLOCK_DATA_ORDER_NOHW_ROUND3_W_WIDE2));;

(* ========================================================================= *)
(* PHASE 5 (prologue): K-threading helpers + framed group theorems.           *)
(*                                                                           *)
(* The four group lemmas G0_WIDE2 / G1 / G2 / G3 each carry only THEIR OWN     *)
(* doubled-K block; the prologue chain G0;G1;G2;G3 needs each group's post to  *)
(* additionally supply the LATER groups' K blocks (group i+1 reads K[4(i+1)..] *)
(* which group i never touches).  Those K reads are readonly (the K table is   *)
(* nonoverlapping with the writable stack window), so ENSURES_FRAME_RO conjoins *)
(* the future-K block to a group's pre+post; the side-condition is the         *)
(* MAYCHANGE read-over-write orthogonality discharged by KFRAME_PRESERVE_TAC.   *)
(*                                                                           *)
(* G0_FRAMED threads K[4..15] (group 0 reads none of them); G1_FRAMED threads  *)
(* K[8..15]; G2_FRAMED threads K[12..15]; group 3 is the last so it needs no   *)
(* frame.  The framed posts then ACI-imply the next group's pre (the inline    *)
(* K[4(i+1)..4(i+1)+3] block + remaining future-K suffix), bridged at each      *)
(* ENSURES_SEQUENCE seam in the PROLOGUE compose.                              *)
(* ========================================================================= *)

(* Discharge an ENSURES_FRAME_RO preservation side-goal `!s s2. R s /\ C s s2  *)
(* ==> R s2` where R is a conjunction of readonly K bytes32 reads and C is the  *)
(* group MAYCHANGE frame, with the group's ALL/nonoverlapping hyps in context.  *)
let KFRAME_PRESERVE_TAC =
  RULE_ASSUM_TAC(REWRITE_RULE[ALL;NONOVERLAPPING_CLAUSES]) THEN REPEAT GEN_TAC THEN
  CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (ASSUME_TAC o CONV_RULE(TOP_DEPTH_CONV BETA_CONV)) MP_TAC) THEN
  REWRITE_TAC[MAYCHANGE; SEQ_ID; SOME_FLAGS] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
  PURE_REWRITE_TAC[ASSIGNS_SEQ] THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  REWRITE_TAC[ASSIGNS_THM] THEN REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REPEAT(FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC o check(is_conj o concl))) THEN
  REPEAT CONJ_TAC THEN
  FIRST_X_ASSUM(SUBST1_TAC o SYM o check (fun th -> is_eq(concl th) && is_var(rand(concl th)))) THEN
  FIRST_X_ASSUM(fun th -> GEN_REWRITE_TAC RAND_CONV [SYM th]) THEN
  READ_OVER_WRITE_ORTHOGONAL_TAC;;

(* Build `ensures x86 (\s. P s /\ R s) (\s. Q s /\ R s) C` from an `ensures      *)
(* PRE/POST/C` group lemma `lem` and a readonly predicate-term `rtm`, by         *)
(* MATCH_MP_TAC ENSURES_FRAME_RO + KFRAME_PRESERVE_TAC + the lemma.  `hyptm` is   *)
(* the lemma's hypothesis-conjunction (proved from context by ASM_REWRITE).      *)
let prove_framed_group lem rtm hyptm =
  let ens_of th = let c = concl(SPEC_ALL th) in if is_imp c then snd(dest_imp c) else c in
  let ens_pre th = let e = ens_of th in rand(rator(rator e)) in
  let ens_post th = let e = ens_of th in rand(rator e) in
  let ens_frame th = let e = ens_of th in rand e in
  let v = `s:x86state` in
  let conj_pred p = mk_abs(v, mk_conj(mk_comb(p,v), mk_comb(rtm,v))) in
  prove
   (mk_imp(hyptm,
      list_mk_comb(`ensures x86`,
        [conj_pred (ens_pre lem); conj_pred (ens_post lem); ens_frame lem])),
    STRIP_TAC THEN MATCH_MP_TAC ENSURES_FRAME_RO THEN CONJ_TAC THENL
     [KFRAME_PRESERVE_TAC;
      MATCH_MP_TAC lem THEN ASM_REWRITE_TAC[ALL;NONOVERLAPPING_CLAUSES]]);;

