let SHA256_NOHW_GROUP_HYPS = `LENGTH (s:int32 list) = 8 /\
    ALL (nonoverlapping (stackpointer:int64, 64))
        [(word pc:int64, 4465); (word kbytes:int64, 677); (datap:int64, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)`;;

let SHA256_NOHW_GROUP0_HYPS = `riprel32_within_bounds kbytes (pc + 0x57) /\
