let SHA256_BLOCK_DATA_ORDER_NOHW_G0_FRAMED =
  prove_framed_group SHA256_BLOCK_DATA_ORDER_NOHW_GROUP0_W_WIDE2 K4_15_PRED
    SHA256_NOHW_GROUP0_HYPS;;

let SHA256_BLOCK_DATA_ORDER_NOHW_G1_FRAMED =
  prove_framed_group SHA256_BLOCK_DATA_ORDER_NOHW_GROUP1_W K8_15_PRED
