(* ========================================================================= *)
(* PHASE 5 (prologue): SEAL the rounds-0-15 prologue `ensures` (tmc 0x4e ->    *)
(* 0x6e6) by chaining the four framed group lemmas at the 0x1fd/0x39f/0x545     *)
(* seams.  Built incrementally as four committed sub-lemmas so an infra death   *)
(* costs at most one seam:                                                      *)
(*   COMPOSE_01  : G0_FRAMED ; G1_FRAMED[compress m 4]            (0x4e -> 0x39f) *)
(*   COMPOSE_012 : COMPOSE_01 ; G2_FRAMED[compress..8]           (0x4e -> 0x545) *)
(*   PROLOGUE_K  : COMPOSE_012 ; GROUP3_W[compress..12]          (0x4e -> 0x6e6) *)
(*   PROLOGUE    : PROLOGUE_K with the bytelist-only precondition (K[4..15]      *)
(*                 recovered from the readonly K256 table by KVALS_4_15).        *)
(*                                                                           *)
(* Each seam is a pure conjunct-reorder (verified once as SEAM_RESHUFFLE in     *)
(* session-018): every atom of the next group's precondition is present in the  *)
(* previous group's framed postcondition, so the seam bridges via               *)
(* ENSURES_PREPOSTCONDITION_THM + a cheap BETA/STRIP/ASM_REWRITE (no MESON).     *)
(* SOME_FLAGS is expanded CONSISTENTLY (goal + both applied group lemmas) so     *)
(* MAYCHANGE_IDEMPOT_TAC inside ENSURES_SEQUENCE_TAC sees the expanded frame.    *)
(* ========================================================================= *)

(* -- small term plumbing: dest an `ensures x86 P Q C` into (P,Q,C) -- *)
let dest_ens_x86 tm =
  let c = rand tm in
  let qp = rator tm in
  (rand(rator qp), rand qp, c);;
let ens_concl th =
  let c = concl th in
  if is_imp c then snd(dest_imp c) else c;;
let sx_state = `s:x86state`;;
let fullbeta_tm t = rhs(concl(TOP_DEPTH_CONV BETA_CONV t));;

(* canon_pred PRED : flatten a (possibly K-conjoined, beta-redex) predicate into
   `\s. bytes_loaded.. /\ read RIP s = word.. /\ <rest>`, with bytes_loaded first
   and `read RIP` second -- the canonical pre/post shape ENSURES_SEQUENCE_TAC
   expects.  canon_rest PRED drops those two leading atoms (the waypoint Q form). *)
let canon_split pred =
  let cs = conjuncts (fullbeta_tm (mk_comb(pred, sx_state))) in
  let is_bl t =
    can (find_term (fun u -> is_const u && fst(dest_const u) = "bytes_loaded")) t in
  let is_rip t =
    is_eq t &&
    can (find_term (fun u -> is_const u && fst(dest_const u) = "RIP")) (lhs t) in
  let bl = find is_bl cs and rip = find is_rip cs in
  let rest = filter (fun t -> not(t == bl) && not(t == rip)) cs in
  (bl, rip, rest);;
let canon_pred pred =
  let (bl,rip,rest) = canon_split pred in
  mk_abs(sx_state, list_mk_conj (bl :: rip :: rest));;
let canon_rest pred =
  let (_,_,rest) = canon_split pred in mk_abs(sx_state, list_mk_conj rest);;

(* seam bridge: the previous-group framed post implies the next-group pre by a
   pure conjunct reorder (beta-reduce, strip the hyp conjunction, re-assemble). *)
let SHA256_NOHW_SEAM_BRIDGE_TAC =
  GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[];;

(* discharge a group lemma's hyp `LENGTH cr = 8 /\ ALL.. /\ nonoverlapping..`
   from context.  The LENGTH conjunct's head is either sha256_compress_round
   (unconditional length) or sha256_compress (needs the inner LENGTH=8). *)
let SHA256_NOHW_GHYP_TAC =
  CONJ_TAC THENL
   [REWRITE_TAC[SHA256_COMPRESS_ROUND_LENGTH] THEN
    TRY(MATCH_MP_TAC SHA256_COMPRESS_LENGTH THEN
        REWRITE_TAC[LENGTH] THEN ARITH_TAC);
    ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES]];;

(* COMPOSE_NOHW_SEAM goal_pre goal_post frame seam_pc segA_thm grp_lem grp_inst :
   prove `hyp ==> ensures x86 goal_pre goal_post frame` by splitting at seam_pc,
   discharging the first segment with segA_thm and the second with grp_lem
   instantiated at the compressed state grp_inst.  Both segA_thm and grp_lem are
   already SOME_FLAGS-expanded `hyp ==> ensures` theorems whose pre/post the goal
   was built from, so the seam implications are pure reorders. *)

(* ---- COMPOSE_01 : 0x4e -> 0x39f ---- *)
let SHA256_BLOCK_DATA_ORDER_NOHW_COMPOSE_01 =
  let g0e = REWRITE_RULE[SOME_FLAGS] (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_G0_FRAMED) in
  let g1e = REWRITE_RULE[SOME_FLAGS] (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_G1_FRAMED) in
  let (p0,q0,c0) = dest_ens_x86 (ens_concl g0e) in
  let (p1,q1,_)  = dest_ens_x86 (ens_concl g1e) in
  let cr4 = `sha256_compress m 4 [a;b;c;d;e;f;g;h]` in
  let p1i = vsubst [cr4,`s:int32 list`] p1
  and q1i = vsubst [cr4,`s:int32 list`] q1 in
  let goal = mk_imp(fst(dest_imp(concl g0e)),
               list_mk_comb(`ensures x86`, [canon_pred p0; canon_pred q1i; c0])) in
  prove
   (goal,
    DISCH_THEN(fun th -> ASSUME_TAC th THEN MP_TAC th) THEN
    REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    ENSURES_SEQUENCE_TAC `pc + 0x1fd` (canon_rest p1i) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
      MAP_EVERY EXISTS_TAC [p0; q0] THEN
      REPEAT CONJ_TAC THENL
       [SHA256_NOHW_SEAM_BRIDGE_TAC; SHA256_NOHW_SEAM_BRIDGE_TAC;
        MATCH_MP_TAC g0e THEN ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES]];
      MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
      MAP_EVERY EXISTS_TAC [p1i; q1i] THEN
      REPEAT CONJ_TAC THENL
       [SHA256_NOHW_SEAM_BRIDGE_TAC; SHA256_NOHW_SEAM_BRIDGE_TAC;
        MATCH_MP_TAC g1e THEN SHA256_NOHW_GHYP_TAC]]);;

(* ---- COMPOSE_012 : 0x4e -> 0x545 ---- *)
let SHA256_BLOCK_DATA_ORDER_NOHW_COMPOSE_012 =
  let c01 = SHA256_BLOCK_DATA_ORDER_NOHW_COMPOSE_01 in
  let g2e = REWRITE_RULE[SOME_FLAGS] (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_G2_FRAMED) in
  let (pc01,qc01,cc01) = dest_ens_x86 (ens_concl (SPEC_ALL c01)) in
  let (p2,q2,_) = dest_ens_x86 (ens_concl g2e) in
  let cr8 = `sha256_compress_round m 7 (sha256_compress_round m 6 (sha256_compress_round m 5 (sha256_compress_round m 4 (sha256_compress m 4 [a;b;c;d;e;f;g;h]))))` in
  let p2i = vsubst [cr8,`s:int32 list`] p2
  and q2i = vsubst [cr8,`s:int32 list`] q2 in
  let goal = mk_imp(fst(dest_imp(concl (SPEC_ALL c01))),
               list_mk_comb(`ensures x86`, [pc01; canon_pred q2i; cc01])) in
  prove
   (goal,
    DISCH_THEN(fun th -> ASSUME_TAC th THEN MP_TAC th) THEN
    REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    ENSURES_SEQUENCE_TAC `pc + 0x39f` (canon_rest p2i) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
      MAP_EVERY EXISTS_TAC [pc01; qc01] THEN
      REPEAT CONJ_TAC THENL
       [SHA256_NOHW_SEAM_BRIDGE_TAC; SHA256_NOHW_SEAM_BRIDGE_TAC;
        MATCH_MP_TAC c01 THEN ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES]];
      MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
      MAP_EVERY EXISTS_TAC [p2i; q2i] THEN
      REPEAT CONJ_TAC THENL
       [SHA256_NOHW_SEAM_BRIDGE_TAC; SHA256_NOHW_SEAM_BRIDGE_TAC;
        MATCH_MP_TAC g2e THEN SHA256_NOHW_GHYP_TAC]]);;

(* ---- PROLOGUE_K : 0x4e -> 0x6e6, pre carries explicit K[4..15] ---- *)
(* GROUP3_W is the last group (no FRAME_RO); its post is the deferred-add        *)
(* partial-a / R14-exposed form, which becomes the prologue postcondition.       *)
let SHA256_BLOCK_DATA_ORDER_NOHW_PROLOGUE_K =
  let c012 = SHA256_BLOCK_DATA_ORDER_NOHW_COMPOSE_012 in
  let g3e = REWRITE_RULE[SOME_FLAGS] (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_GROUP3_W) in
  let (pc012,qc012,cc012) = dest_ens_x86 (ens_concl (SPEC_ALL c012)) in
  let (p3,q3,_) = dest_ens_x86 (ens_concl g3e) in
  let cr12 = `sha256_compress_round m 11 (sha256_compress_round m 10 (sha256_compress_round m 9 (sha256_compress_round m 8 (sha256_compress_round m 7 (sha256_compress_round m 6 (sha256_compress_round m 5 (sha256_compress_round m 4 (sha256_compress m 4 [a;b;c;d;e;f;g;h]))))))))` in
  let p3i = vsubst [cr12,`s:int32 list`] p3
  and q3i = vsubst [cr12,`s:int32 list`] q3 in
  let goal = mk_imp(fst(dest_imp(concl (SPEC_ALL c012))),
               list_mk_comb(`ensures x86`, [pc012; canon_pred q3i; cc012])) in
  prove
   (goal,
    DISCH_THEN(fun th -> ASSUME_TAC th THEN MP_TAC th) THEN
    REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    ENSURES_SEQUENCE_TAC `pc + 0x545` (canon_rest p3i) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
      MAP_EVERY EXISTS_TAC [pc012; qc012] THEN
      REPEAT CONJ_TAC THENL
       [SHA256_NOHW_SEAM_BRIDGE_TAC; SHA256_NOHW_SEAM_BRIDGE_TAC;
        MATCH_MP_TAC c012 THEN ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES]];
      MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
      MAP_EVERY EXISTS_TAC [p3i; q3i] THEN
      REPEAT CONJ_TAC THENL
       [SHA256_NOHW_SEAM_BRIDGE_TAC; SHA256_NOHW_SEAM_BRIDGE_TAC;
        MATCH_MP_TAC g3e THEN SHA256_NOHW_GHYP_TAC]]);;

(* ---- PROLOGUE : public form with bytelist-only precondition ---- *)
(* Drop the 12 explicit K[4..15] bytes32 reads from PROLOGUE_K's precondition;   *)
(* they are recovered from the readonly K256_data bytelist by KVALS_4_15.        *)
let SHA256_BLOCK_DATA_ORDER_NOHW_PROLOGUE =
  let pk = SHA256_BLOCK_DATA_ORDER_NOHW_PROLOGUE_K in
  let (pk_p,pk_q,pk_c) = dest_ens_x86 (ens_concl (SPEC_ALL pk)) in
  let is_kread t =
    is_eq t &&
    can (term_match [] `read (memory :> bytes32 (word_add (word kbytes) (word n))) ss`)
        (lhs t) &&
    (is_comb(rhs t) && (try fst(dest_const(rator(rhs t)))="word" with _ -> false)) in
  let pub_pre =
    mk_abs(sx_state,
      list_mk_conj (filter (fun t -> not(is_kread t))
                      (conjuncts (fullbeta_tm (mk_comb(pk_p, sx_state)))))) in
  let goal = mk_imp(fst(dest_imp(concl (SPEC_ALL pk))),
               list_mk_comb(`ensures x86`, [pub_pre; pk_q; pk_c])) in
  prove
   (goal,
    STRIP_TAC THEN MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
    EXISTS_TAC pk_p THEN CONJ_TAC THENL
     [GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[] THEN
      FIRST_ASSUM(fun th ->
        MP_TAC(MATCH_MP (SPEC_ALL SHA256_NOHW_KVALS_4_15) th)) THEN
      REWRITE_TAC[];
      MATCH_MP_TAC pk THEN ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* PHASE 6: ONE iteration of the rounds_16_xx schedule-extension body          *)
(* (16 schedule rounds, tmc 0x6e6 -> end-of-iteration).  Each round now        *)
(* COMPUTES its message word W[t] = sigma1(W[t-2]) + W[t-7] + sigma0(W[t-15])  *)
(* + W[t-16] from four stack slots (ring buffer) and stores it back, rather    *)
(* than bswap-loading it from the data buffer.  The compression half is        *)
(* identical to the prologue rounds.                                           *)
(*                                                                           *)
(* DEFERRED-ADD shape (carried over from the prologue boundary, now INTERNAL   *)
(* to every schedule round): the predecessor round's `a` completion (its final *)
(* `+ Sigma0`) is scheduled as the FIRST compute instruction of THIS round     *)
(* (`add %r14d,%eax`).  So each ROUNDt_W is stated over an OPAQUE completed     *)
(* predecessor state `s` (LENGTH 8) plus two partial-a vars (pa, s0) with the   *)
(* completing hypothesis `word_add pa s0 = EL 0 s`; the first instruction       *)
(* consumes that add, and the round's own output is again left partial         *)
(* (R11/RDX = partial a', R14 = Sigma0) for round t+1 to complete.             *)
(* ========================================================================= *)

(* W[16] in the exact flat shape the rounds_16_xx body accumulates it:         *)
(*   r12 = sigma0(slot1=m1); += slot9=m9; += slot0=m0; += sigma1(slot14=m14).  *)
(* Folds to sha256_W m 16 via the W recurrence (t=16: t-15=1,t-7=9,t-16=0,     *)
(* t-2=14) and SHA256_W_LO16 (all four predecessors are direct message words). *)
let SHA256_W16_VAL = prove
 (`word_add (word_add (word_add (sha256_sigma0 (m 1)) (m 9)) (m 0))
            (sha256_sigma1 (m 14)) = sha256_W m 16`,
  MP_TAC(SPECL [`m:num->int32`; `16`] SHA256_W_RECUR) THEN
  REWRITE_TAC[ARITH] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[SHA256_W_LO16]);;

(* Round 16 (schedule) + W[16] store to slot 0.  Entry tmc 0x6e6 -> 0x789. *)
(* DEFERRED-ADD: entry RAX=word_zx pa, R14=word_zx s0, hyp word_add pa s0 = EL 0 s. *)
let SHA256_BLOCK_DATA_ORDER_NOHW_ROUND16_W = prove
 (`!(s:int32 list) (pa:int32) (s0:int32). !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    LENGTH s = 8 /\ word_add pa s0 = EL 0 s /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x6e6) /\
              read RBP s' = word_add (word kbytes) (word 128) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 128))) s' = word 3835390401 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 132))) s' = word 4022224774 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 136))) s' = word 264347078 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 140))) s' = word 604807628 /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              read (memory :> bytes32 (stackpointer)) s' = word_zx (m 0) /\
              read (memory :> bytes32 (word_add stackpointer (word 4))) s' = word_zx (m 1) /\
              read (memory :> bytes32 (word_add stackpointer (word 8))) s' = word_zx (m 2) /\
              read (memory :> bytes32 (word_add stackpointer (word 12))) s' = word_zx (m 3) /\
              read (memory :> bytes32 (word_add stackpointer (word 16))) s' = word_zx (m 4) /\
              read (memory :> bytes32 (word_add stackpointer (word 20))) s' = word_zx (m 5) /\
              read (memory :> bytes32 (word_add stackpointer (word 24))) s' = word_zx (m 6) /\
              read (memory :> bytes32 (word_add stackpointer (word 28))) s' = word_zx (m 7) /\
              read (memory :> bytes32 (word_add stackpointer (word 32))) s' = word_zx (m 8) /\
              read (memory :> bytes32 (word_add stackpointer (word 36))) s' = word_zx (m 9) /\
              read (memory :> bytes32 (word_add stackpointer (word 40))) s' = word_zx (m 10) /\
              read (memory :> bytes32 (word_add stackpointer (word 44))) s' = word_zx (m 11) /\
              read (memory :> bytes32 (word_add stackpointer (word 48))) s' = word_zx (m 12) /\
              read (memory :> bytes32 (word_add stackpointer (word 52))) s' = word_zx (m 13) /\
              read (memory :> bytes32 (word_add stackpointer (word 56))) s' = word_zx (m 14) /\
              read (memory :> bytes32 (word_add stackpointer (word 60))) s' = word_zx (m 15) /\
              (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' = word_bytereverse(m t)) /\
              read RAX s' = word_zx pa /\ read R14 s' = word_zx s0 /\
              read RBX s' = word_zx (EL 1 s) /\
              read RCX s' = word_zx (EL 2 s) /\
              read RDX s' = word_zx (EL 3 s) /\
              read R8 s' = word_zx (EL 4 s) /\
              read R9 s' = word_zx (EL 5 s) /\
              read R10 s' = word_zx (EL 6 s) /\
              read R11 s' = word_zx (EL 7 s) /\
              read RDI s' = word_zx (word_xor (EL 1 s) (EL 2 s)))
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x789) /\
              read RBP s' = word_add (word kbytes) (word 132) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 128))) s' = word 3835390401 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 132))) s' = word 4022224774 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 136))) s' = word 264347078 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 140))) s' = word 604807628 /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              read (memory :> bytes32 (stackpointer)) s' = word_zx (sha256_W m 16) /\
              read (memory :> bytes32 (word_add stackpointer (word 4))) s' = word_zx (m 1) /\
              read (memory :> bytes32 (word_add stackpointer (word 8))) s' = word_zx (m 2) /\
              read (memory :> bytes32 (word_add stackpointer (word 12))) s' = word_zx (m 3) /\
              read (memory :> bytes32 (word_add stackpointer (word 16))) s' = word_zx (m 4) /\
              read (memory :> bytes32 (word_add stackpointer (word 20))) s' = word_zx (m 5) /\
              read (memory :> bytes32 (word_add stackpointer (word 24))) s' = word_zx (m 6) /\
              read (memory :> bytes32 (word_add stackpointer (word 28))) s' = word_zx (m 7) /\
              read (memory :> bytes32 (word_add stackpointer (word 32))) s' = word_zx (m 8) /\
              read (memory :> bytes32 (word_add stackpointer (word 36))) s' = word_zx (m 9) /\
              read (memory :> bytes32 (word_add stackpointer (word 40))) s' = word_zx (m 10) /\
              read (memory :> bytes32 (word_add stackpointer (word 44))) s' = word_zx (m 11) /\
              read (memory :> bytes32 (word_add stackpointer (word 48))) s' = word_zx (m 12) /\
              read (memory :> bytes32 (word_add stackpointer (word 52))) s' = word_zx (m 13) /\
              read (memory :> bytes32 (word_add stackpointer (word 56))) s' = word_zx (m 14) /\
              read (memory :> bytes32 (word_add stackpointer (word 60))) s' = word_zx (m 15) /\
              (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' = word_bytereverse(m t)) /\
              read R11 s' = word_zx (word_add (word_xor (EL 1 s) (word_and (word_xor (EL 1 s) (EL 2 s)) (word_xor (EL 0 s) (EL 1 s)))) (word_add (word_add (word_add (word_add (sha256_W m 16) (EL 7 s)) (word_xor (word_and (word_xor (EL 5 s) (EL 6 s)) (EL 4 s)) (EL 6 s))) (EL 16 sha256_K)) (word_ror (word_xor (word_ror (word_xor (word_ror (EL 4 s) 14) (EL 4 s)) 5) (EL 4 s)) 6))) /\
              read R14 s' = word_zx (word_ror (word_xor (word_ror (word_xor (word_ror (EL 0 s) 9) (EL 0 s)) 11) (EL 0 s)) 2) /\
              read RAX s' = word_zx (EL 1 (sha256_compress_round m 16 s)) /\
              read RBX s' = word_zx (EL 2 (sha256_compress_round m 16 s)) /\
              read RCX s' = word_zx (EL 3 (sha256_compress_round m 16 s)) /\
              read RDX s' = word_zx (EL 4 (sha256_compress_round m 16 s)) /\
              read R8 s' = word_zx (EL 5 (sha256_compress_round m 16 s)) /\
              read R9 s' = word_zx (EL 6 (sha256_compress_round m 16 s)) /\
              read R10 s' = word_zx (EL 7 (sha256_compress_round m 16 s)) /\
              read R15 s' = word_zx (word_xor (EL 1 (sha256_compress_round m 16 s))
                                              (EL 2 (sha256_compress_round m 16 s))))
         (MAYCHANGE [RIP;RDI;RBP;RAX;R11;RDX;R12;R13;R14;R15] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--47) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[WORD_ADD_ASSOC_CONSTS] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[SHA256_CR_EL_SHIFT] THEN
  REPEAT CONJ_TAC THEN
  REWRITE_TAC[SHA256_COMPRESS_ROUND_ALU_EL] THEN
  SIMP_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH;
           WORD_BYTEREVERSE_BYTEREVERSE; WORD_ZX_TRIVIAL] THEN
  REWRITE_TAC[SHA256_LSIGMA0_ALU; SHA256_LSIGMA1_ALU; SHA256_W16_VAL] THEN
  REWRITE_TAC[sha256_K] THEN CONV_TAC(DEPTH_CONV EL_CONV) THEN
  CONV_TAC WORD_REDUCE_CONV THEN
  TRY(FIRST_X_ASSUM(fun th -> let _ = term_match [] `word_add pa s0 = EL 0 s` (concl th) in REWRITE_TAC[th])) THEN
  TRY(AP_TERM_TAC THEN CONV_TAC WORD_RULE));;

let SHA256_W17_VAL = prove
 (`word_add (word_add (word_add (sha256_sigma0 (m 2)) (m 10)) (m 1)) (sha256_sigma1 (m 15)) = sha256_W m 17`,
  MP_TAC(SPECL [`m:num->int32`; `17`] SHA256_W_RECUR) THEN
  REWRITE_TAC[ARITH] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[SHA256_W_LO16]);;

(* Round 17 (schedule) + W[17] -> slot 1.  Entry tmc 0x789 -> 0x829, 47 instr. *)
(* DEFERRED-ADD: entry R11=word_zx pa, R14=word_zx s0, hyp word_add pa s0 = EL 0 s. *)
let SHA256_BLOCK_DATA_ORDER_NOHW_ROUND17_W = prove
 (`!(s:int32 list) (pa:int32) (s0:int32). !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap:int64.
    LENGTH s = 8 /\ word_add pa s0 = EL 0 s /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s' = word (pc + 0x789) /\
              read RBP s' = word_add (word kbytes) (word 132) /\
              read (memory :> bytes32 (word_add (word kbytes) (word 128))) s' = word 3835390401 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 132))) s' = word 4022224774 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 136))) s' = word 264347078 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 140))) s' = word 604807628 /\
              read RSI s' = datap /\ read RSP s' = stackpointer /\
              read (memory :> bytes32 (stackpointer)) s' = word_zx (sha256_W m 16) /\
              read (memory :> bytes32 (word_add stackpointer (word 4))) s' = word_zx (m 1) /\
              read (memory :> bytes32 (word_add stackpointer (word 8))) s' = word_zx (m 2) /\
              read (memory :> bytes32 (word_add stackpointer (word 12))) s' = word_zx (m 3) /\
              read (memory :> bytes32 (word_add stackpointer (word 16))) s' = word_zx (m 4) /\
              read (memory :> bytes32 (word_add stackpointer (word 20))) s' = word_zx (m 5) /\
              read (memory :> bytes32 (word_add stackpointer (word 24))) s' = word_zx (m 6) /\
              read (memory :> bytes32 (word_add stackpointer (word 28))) s' = word_zx (m 7) /\
              read (memory :> bytes32 (word_add stackpointer (word 32))) s' = word_zx (m 8) /\
              read (memory :> bytes32 (word_add stackpointer (word 36))) s' = word_zx (m 9) /\
              read (memory :> bytes32 (word_add stackpointer (word 40))) s' = word_zx (m 10) /\
              read (memory :> bytes32 (word_add stackpointer (word 44))) s' = word_zx (m 11) /\
              read (memory :> bytes32 (word_add stackpointer (word 48))) s' = word_zx (m 12) /\
              read (memory :> bytes32 (word_add stackpointer (word 52))) s' = word_zx (m 13) /\
              read (memory :> bytes32 (word_add stackpointer (word 56))) s' = word_zx (m 14) /\
              read (memory :> bytes32 (word_add stackpointer (word 60))) s' = word_zx (m 15) /\
              (!t. t < 16 ==> read (memory :> bytes32 (word_add datap (word (4 * t)))) s' = word_bytereverse(m t)) /\
              read R11 s' = word_zx pa /\ read R14 s' = word_zx s0 /\
              read RAX s' = word_zx (EL 1 s) /\
              read RBX s' = word_zx (EL 2 s) /\
              read RCX s' = word_zx (EL 3 s) /\
              read RDX s' = word_zx (EL 4 s) /\
              read R8 s' = word_zx (EL 5 s) /\
              read R9 s' = word_zx (EL 6 s) /\
              read R10 s' = word_zx (EL 7 s) /\
              read R15 s' = word_zx (word_xor (EL 1 s) (EL 2 s)))
         (\s'. bytes_loaded s' (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
