(* ------------------------------------------------------------------------- *)
(* a-completion seam identity (Phase 6 compose).  Each schedule round leaves    *)
(* its `a`-output PARTIAL: the a'-register holds Maj+T1 (= partial_a) and R14    *)
(* holds Sigma0(EL0 s); the NEXT round's leading `add %r14d,%eax` completes it.  *)
(* So a ROUNDt_W -> ROUND(t+1)_W seam instantiates the successor's (pa,s0) to    *)
(* (partial_a, Sigma0) over s' = sha256_compress_round m t s, and must discharge *)
(* its `word_add pa s0 = EL 0 s'` precondition.  This is exactly that fact:      *)
(* word_add partial_a (Sigma0(EL0 s)) = EL 0 (sha256_compress_round m t s).      *)
let SHA256_ACOMPLETE = prove
 (`!m t s:int32 list.
     word_add
       (word_add (word_xor (EL 1 s) (word_and (word_xor (EL 1 s) (EL 2 s)) (word_xor (EL 0 s) (EL 1 s))))
                 (word_add (word_add (word_add (word_add (sha256_W m t) (EL 7 s))
                              (word_xor (word_and (word_xor (EL 5 s) (EL 6 s)) (EL 4 s)) (EL 6 s)))
                            (EL t sha256_K))
                  (word_ror (word_xor (word_ror (word_xor (word_ror (EL 4 s) 14) (EL 4 s)) 5) (EL 4 s)) 6)))
       (word_ror (word_xor (word_ror (word_xor (word_ror (EL 0 s) 9) (EL 0 s)) 11) (EL 0 s)) 2)
     = EL 0 (sha256_compress_round m t s)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[SHA256_COMPRESS_ROUND_ALU_EL] THEN
  CONV_TAC(DEPTH_CONV EL_CONV) THEN REWRITE_TAC[]);;

(* ========================================================================= *)
(* PHASE 6 (compose): the four schedule GROUP lemmas GROUP4_W..GROUP7_W, then  *)
(* the one-iteration rounds_16_xx ensures (tmc 0x6e6 -> 0x10f9).               *)
(*                                                                           *)
(* Mirrors the Phase-5 prologue GROUP/COMPOSE structure (GROUP3_W + COMPOSE)   *)
(* but every round->round seam now threads the DEFERRED-ADD partial-a: the     *)
(* successor round's `word_add pa s0 = EL 0 s'` precondition is exactly         *)
(* SHA256_ACOMPLETE at the seam state, so APPLY_SCHED_ROUND_TAC adds it to the  *)
(* round-application rewrite set.  Group entry/exit are partial-a (a'-reg =     *)
(* Maj+T1, R14 = Sigma0) for the next round/iteration to complete.             *)
(* ========================================================================= *)

(* APPLY_ROUND_TAC variant for schedule rounds: also discharges the deferred-add
   hyp `word_add pa s0 = EL 0 s'` at each seam via SHA256_ACOMPLETE. *)
let APPLY_SCHED_ROUND_TAC lemma =
  let cframe = rand(rand(concl(SPEC_ALL lemma))) in
  MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN EXISTS_TAC cframe THEN CONJ_TAC THENL
   [REWRITE_TAC[SOME_FLAGS] THEN SUBSUMED_MAYCHANGE_TAC;
    MATCH_MP_TAC lemma THEN
    ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES; SHA256_COMPRESS_ROUND_LENGTH;
                    SHA256_ACOMPLETE]];;

