(* ========================================================================= *)
(* PHASE 7: the rounds_16_xx LOOP back-edge `cmpb $0,3(%rbp); jnz` (tmc       *)
(* 0x10f9 -> 0x10fd).  This is a SENTINEL test on the doubled-K256 tail, NOT a *)
(* counter: after iteration i (i in {0,1,2}) RBP = kbytes + 256 + 128*i, and  *)
(* `cmpb $0,3(%rbp)` reads the byte at kbytes + 259 + 128*i.  The doubled K    *)
(* table is 512 bytes; offsets 512.. hold the pshufb-mask row 0x00010203...    *)
(* The sentinel bytes (verified from K256_data, the relocs constant):          *)
(*   i=0: byte[259] = K[32]'s MSB = 0x27 = 39  (nonzero -> jnz TAKEN, loop)     *)
(*   i=1: byte[387] = K[48]'s MSB = 0x19 = 25  (nonzero -> jnz TAKEN, loop)     *)
(*   i=2: byte[515] = (0x00010203 LE)'s MSB    = 0    (zero -> jnz FALLS, exit) *)
(* This 0x00 at K256+515 is exactly the upstream-restored tail (memory          *)
(* sha256-nohw-k256-truncation-bug); it is what TERMINATES the loop and is      *)
(* WIRED into the exit reasoning here (not assumed): BE2's precondition byte=0  *)
(* discharges ZF, so jnz falls through.                                         *)
(*                                                                           *)
(* The byte `cmpb` is an 8-bit `x86_CMP` on a `(8)word` operand.  X86_STEPS_TAC *)
(* CANNOT reduce it: `X86_OPERATION_CLAUSES` carries `x86_CMP_ALT` PREPROCESSED *)
(* (via CARRY64_SUB / WORD_ZX_TRIVIAL) to a LHS fixed at `(64)word`, so X86_CONV *)
(* only matches 64-bit CMPs and leaves the byte cmpb as an opaque `x86_CMP`,    *)
(* whereupon X86_BASIC_STEP_TAC fails at EXISTS_NONTRIVIAL_CONV.  The fix is a   *)
(* local step tactic that post-processes the X86_CONV output with the RAW       *)
(* polymorphic `x86_CMP` definition (which DOES match the byte width) and       *)
(* replays the assignment->write tail convs so the step closes normally.        *)
(* ========================================================================= *)

(* tail conv: turn an opaque byte `x86_CMP` (left by X86_CONV) into a write-form
   by unfolding the raw def + replaying the standard X86_CONV assignment tail. *)
let X86_BYTECMP_TAIL_CONV =
  REWRITE_CONV[x86_CMP] THENC
  TOP_DEPTH_CONV let_CONV THENC
  REWRITE_CONV[READ_RVALUE] THENC
  TRY_CONV(GEN_REWRITE_CONV TOP_DEPTH_CONV
   [ASSIGNS_PULL_ZEROTOP_THM; ASSIGNS_PULL_THM]) THENC
  TRY_CONV(REWRITE_CONV[ASSIGNS_THM]) THENC
  TRY_CONV(GEN_REWRITE_CONV TOP_DEPTH_CONV [SEQ_PULL_THM; BETA_THM]) THENC
  TRY_CONV(GEN_REWRITE_CONV TOP_DEPTH_CONV[assign; seq; UNWIND_THM1; BETA_THM]) THENC
  TRY_CONV(TOP_DEPTH_CONV COMPONENT_READ_OVER_WRITE_CONV) THENC
  TRY_CONV(TOP_DEPTH_CONV COMPONENT_WRITE_OVER_WRITE_CONV) THENC
  TRY_CONV(DEPTH_CONV WORD_NUM_RED_CONV);;

(* mirrors X86_BASIC_STEP_TAC (x86.ml) but injects X86_BYTECMP_TAIL_CONV into eth *)
let X86_BYTECMP_BASIC_STEP_TAC =
  let x86_tm = `x86` and x86_ty = `:x86state` in
  fun (decode_ths: thm option array) sname (asl,w) ->
    let sv = rand w and sv' = mk_var(sname,x86_ty) in
    let atm = mk_comb(mk_comb(x86_tm,sv),sv') in
    let eth0 = X86_CONV decode_ths (map snd asl) atm in
    let eth = CONV_RULE (RAND_CONV X86_BYTECMP_TAIL_CONV) eth0 in
    (GEN_REWRITE_TAC I [eventually_CASES] THEN DISJ2_TAC THEN CONJ_TAC THENL
     [GEN_REWRITE_TAC BINDER_CONV [eth] THEN CONV_TAC EXISTS_NONTRIVIAL_CONV;
      X_GEN_TAC sv' THEN GEN_REWRITE_TAC LAND_CONV [eth] THEN
      REPEAT X86_UNDEFINED_CHOOSE_TAC]) (asl,w);;

(* full step = basic byte-cmp step + the standard X86_STEP_TAC state-update tail *)
let X86_BYTECMP_STEP_TAC (mc_length_th,decode_ths) sname =
  X86_BYTECMP_BASIC_STEP_TAC decode_ths sname THEN
  NONSELFMODIFYING_STATE_UPDATE_TAC
    (MATCH_MP bytes_loaded_update mc_length_th) THEN
  ASSUMPTION_STATE_UPDATE_TAC THEN
  MAYCHANGE_STATE_UPDATE_TAC THEN
  DISCH_THEN(fun th ->
    let thl = STATE_UPDATE_NEW_RULE th in
    if thl = [] then ALL_TAC else
    MP_TAC(end_itlist CONJ thl) THEN
    ASSEMBLER_SIMPLIFY_TAC THEN
    STRIP_TAC);;

(* ---- BACK-EDGE (taken): iterations 0,1.  Sentinel byte nonzero -> loop top. *)
(* The sentinel byte is supplied as an explicit precondition (read in the       *)
(* exact RBP-relative form the stepper builds); the composition with each        *)
(* iteration lemma supplies it from the readonly K256 table.                     *)
let SHA256_BLOCK_DATA_ORDER_NOHW_BACKEDGE_TAKEN = prove
 (`!sentinel:byte. !kbytes:num. !rbpoff:num. !pc stackpointer:int64. !datap:int64.
    ~(sentinel = word 0) /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x10f9) /\
              read RBP s = word_add (word kbytes) (word rbpoff) /\
              read (memory :> bytes8 (word_add (word_add (word kbytes) (word rbpoff)) (word 3))) s = sentinel)
         (\s. read RIP s = word (pc + 0x6e6))
         (MAYCHANGE [RIP] ,, MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  X86_BYTECMP_STEP_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC "s1" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (2--2) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  (* discharge the jnz branch: sentinel <> 0 ==> word_sub sentinel 0 <> 0 ==> ~ZF *)
  REWRITE_TAC[WORD_SUB_0] THEN ASM_REWRITE_TAC[VAL_EQ_0]);;

(* ---- BACK-EDGE (fall-through): iteration 2.  Sentinel byte = 0 -> exit. *)
let SHA256_BLOCK_DATA_ORDER_NOHW_BACKEDGE_EXIT = prove
 (`!kbytes:num. !rbpoff:num. !pc stackpointer:int64. !datap:int64.
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x10f9) /\
              read RBP s = word_add (word kbytes) (word rbpoff) /\
              read (memory :> bytes8 (word_add (word_add (word kbytes) (word rbpoff)) (word 3))) s = word 0)
         (\s. read RIP s = word (pc + 0x1103))
         (MAYCHANGE [RIP] ,, MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  X86_BYTECMP_STEP_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC "s1" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (2--2) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[]);;


(* ========================================================================= *)
(* PHASE 7: ITERATION1 (rounds 32-47).  The rounds_16_xx loop re-executes the *)
(* SAME machine code each iteration (periodic PCs 0x6e6 -> 0x10f9); only the  *)
(* spec round index t, K[t], sha256_W m t, and RBP K-table offset advance.    *)
(* Groups 8-11 nest from the iteration-entry opaque state `s` (= compress^32  *)
(* of the block's working vars at the ITERATION1 entry seam).                 *)
