(* PHASE 7: ITERATION2 per-round lemmas (rounds 48-63) + W{48..63}_VAL.        *)
(* Same uniform schedule-round shape as rounds 16-47 (periodic PCs, ring       *)
(* buffer W-slots, deferred-add partial-a in/out); only the spec round index   *)
(* t, K[t], sha256_W m t and the RBP K-table offset (kbytes+384..kbytes+512)   *)
(* advance.  W{t}_VAL folds the asm W-sum to sha256_W m t (all predecessors    *)
(* >= 16, so all sha256_W m k).                                                *)
(* ========================================================================= *)
let SHA256_W48_VAL = prove
 (`word_add (word_add (word_add (sha256_sigma0 (sha256_W m 33)) (sha256_W m 41)) (sha256_W m 32)) (sha256_sigma1 (sha256_W m 46)) = sha256_W m 48`,
  MP_TAC(SPECL [`m:num->int32`; `48`] SHA256_W_RECUR) THEN
  REWRITE_TAC[ARITH] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[SHA256_W_LO16]);;

(* Round 48 (schedule) + W[48] -> slot 0.  Entry tmc 0x6e6 -> 0x789, 47 instr. *)
