              read (memory :> bytes32 (word_add (word kbytes) (word 388))) s' = word 506948616 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 392))) s' = word 659060556 /\
              read (memory :> bytes32 (word_add (word kbytes) (word 396))) s' = word 883997877 /\
