        MATCH_MP_TAC cprev THEN ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES]];
      MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
      MAP_EVERY EXISTS_TAC [pdi; qdi] THEN
      REPEAT CONJ_TAC THENL
       [SHA256_NOHW_SEAM_BRIDGE_TAC; SHA256_NOHW_SEAM_BRIDGE_TAC;
        MATCH_MP_TAC gd THEN SHA256_NOHW_SCHED_GHYP_TAC]]);;

(* ========================================================================= *)
(* PHASE 7: SENTINEL_BYTES.  The loop back-edge `cmpb $0,3(%rbp)` reads the    *)
(* byte at kbytes + rbpoff + 3, with rbpoff = 256/384/512 at the three         *)
(* iteration exits.  These bytes (offsets 259/387/515 of the doubled K256      *)
(* table) are 39/25/0 -- derived here from the readonly K256_data bytelist,    *)
(* so the loop-termination sentinel is WIRED (not assumed).  Mirrors           *)
(* SHA256_NOHW_KVALS_4_15 (EXPLODE_BYTELIST_ASSUM_TAC +                          *)
(* INTRO_READ_MEMORY_FROM_BYTES8_TAC).                                          *)
(* ========================================================================= *)
let SHA256_NOHW_SENTINEL_BYTES = prove
 (`!kbytes:num. !x:x86state.
     read (memory :> bytelist (word kbytes, LENGTH K256_data)) x = K256_data
     ==> read (memory :> bytes8 (word_add (word kbytes) (word 259))) x = word 39 /\
         read (memory :> bytes8 (word_add (word kbytes) (word 387))) x = word 25 /\
         read (memory :> bytes8 (word_add (word kbytes) (word 515))) x = word 0`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  EXPLODE_BYTELIST_ASSUM_TAC sha256_block_data_order_nohw_constants_data THEN
  REPEAT CONJ_TAC THEN
  (fun (asl,w) -> INTRO_READ_MEMORY_FROM_BYTES8_TAC (lhs w) (asl,w)) THEN
  ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* PHASE 7: WIDE back-edge lemmas BE0_WIDE/BE1_WIDE/BE2_WIDE.                  *)
(* The committed BACKEDGE_TAKEN/EXIT have NARROW MAYCHANGE [RIP],,SOME_FLAGS,, *)
(* [events] and a post stating only RIP; to slot them between the wide-frame   *)
(* iterations in the 3-iteration unroll, we restate each back-edge over the    *)
(* iteration-i EXIT predicate (the cmpb/jne preserves the entire working/W/K/  *)
(* data state), under the WIDE iteration MAYCHANGE frame.  Built programmatic-  *)
(* ally from the committed ITERATION{,1,2} posts via prove_be_wide:            *)
(*   pre  = ITER_i.post @ RIP 0x10f9 + the sentinel byte read                  *)
(*   post = ITER_i.post @ RIP 0x6e6 (TAKEN, i<2) or 0x1103 (EXIT, i=2)         *)
(* The sentinel byte (kbytes+259/387/515 = 39/25/0) is left as an explicit pre- *)
(* condition here; it is discharged from K256_data at the final loop compose    *)
(* via SHA256_NOHW_SENTINEL_BYTES (so termination is wired, not assumed).       *)
(* ========================================================================= *)

(* The wide iteration frame, SOME_FLAGS-expanded (matches the iteration lemmas). *)
let nohw_iter_frame_exp =
  let (_,_,c) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION)) in
  rhs(concl(REWRITE_CONV[SOME_FLAGS] c));;

(* set the RIP-conjunct's offset in a beta-reduced predicate to `word(pc+newoff)` *)
let set_rip_pred newoff pred =
  let cs = conjuncts (fullbeta_tm (mk_comb(pred, sx_state))) in
  let is_rip t = is_eq t &&
    can (find_term (fun u -> is_const u && fst(dest_const u) = "RIP")) (lhs t) in
  let newrip = mk_eq(`read RIP s`, mk_comb(`word:num->int64`,
                 mk_binop `(+):num->num->num` `pc:num` (mk_small_numeral newoff))) in
  mk_abs(sx_state, list_mk_conj (map (fun t -> if is_rip t then newrip else t) cs));;

(* append the sentinel byte read (kbytes+sentoff = word sentval : byte) to a pred *)
let add_sentinel sentoff sentval pred =
  let cs = conjuncts (fullbeta_tm (mk_comb(pred, sx_state))) in
  let stm = mk_eq(
    mk_comb(mk_comb(`read:(x86state,byte)component->x86state->byte`,
      `memory :> bytes8 (word_add (word kbytes) (word OFF))`),sx_state),
    `word SVAL : byte`) in
  let stm = subst[mk_small_numeral sentoff,`OFF:num`; mk_small_numeral sentval,`SVAL:num`] stm in
  mk_abs(sx_state, list_mk_conj (cs @ [stm]));;

(* build BE_i_WIDE : restate iteration-i EXIT predicate qi at RIP 0x10f9 (+sentinel)
   -> qi at RIP 0x6e6 (TAKEN) or 0x1103 (EXIT), under the WIDE iter frame.        *)
let prove_be_wide qi sentoff sentval taken =
  let exitoff = if taken then 0x6e6 else 0x1103 in
  let pre  = canon_pred (add_sentinel sentoff sentval (set_rip_pred 0x10f9 qi)) in
  let post = canon_pred (set_rip_pred exitoff qi) in
  let hyptm = `ALL (nonoverlapping (stackpointer:int64, 64))
        [(word pc:int64, 4465); (word kbytes:int64, 677); (datap:int64, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)` in
  let branch_tac = if taken then (REWRITE_TAC[WORD_SUB_0] THEN ASM_REWRITE_TAC[VAL_EQ_0])
                   else ALL_TAC in
  prove
   (mk_imp(hyptm, list_mk_comb(`ensures x86`, [pre; post; nohw_iter_frame_exp])),
    REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
    ENSURES_INIT_TAC "s0" THEN
    X86_BYTECMP_STEP_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC "s1" THEN
    X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (2--2) THEN
    ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    branch_tac THEN
    SIMP_TAC[WORD_ZX_ZX; WORD_ZX_TRIVIAL; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH]);;

let SHA256_BLOCK_DATA_ORDER_NOHW_BE0_WIDE =
  let (_,q0,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION)) in
  prove_be_wide q0 259 39 true;;
let SHA256_BLOCK_DATA_ORDER_NOHW_BE1_WIDE =
  let (_,q1,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION1)) in
  prove_be_wide q1 387 25 true;;
let SHA256_BLOCK_DATA_ORDER_NOHW_BE2_WIDE =
  let (_,q2,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION2)) in
  prove_be_wide q2 515 0 false;;

(* ========================================================================= *)
(* PHASE 7: the rounds_16_xx LOOP, 3-iteration UNROLL (tmc 0x6e6 -> 0x1103).    *)
(* Composes ITERATION0 ; BE0 ; ITERATION1 ; BE1 ; ITERATION2 ; BE2(exit) into   *)
(* a single `ensures` for the whole loop.  The inner loop count is a FIXED 3    *)
(* (the back-edge is a data-dependent sentinel test on the doubled-K256 tail,   *)
(* NOT a counter), so we UNROLL rather than use ENSURES_WHILE_UP2_TAC (blessed  *)
(* 2026-06-06; a generic forall-i<3 body would case-split i anyway).            *)
(*                                                                           *)
(* Each of the 6 segments is framed (ENSURES_FRAME_RO, via prove_framed_group)  *)
(* with a uniform read-only predicate R_ALL = the future K-table reads that     *)
(* later iterations need (groups 8..15, kbytes+256..492 -- ITERATION_i.post     *)
(* only exposes its own last group's K) PLUS the three loop-termination         *)
(* sentinel bytes (kbytes+259/387/515 = 39/25/0).  R_ALL is preserved across    *)
(* every segment's MAYCHANGE (orthogonal reads -- KFRAME_PRESERVE_TAC), so      *)
(* every seam is a pure conjunct reorder and each back-edge's sentinel + each    *)
(* iteration's K-reads are always in scope.  The sentinels in R_ALL are still   *)
(* explicit preconditions here; the public loop form (next) recovers them, and  *)
(* the future-K reads, from the readonly K256_data bytelist.                    *)
(*                                                                           *)
(* The iteration->iteration seams instantiate the next iteration's opaque entry *)
(* state s := the previous iteration's exit working-var nest, with the          *)
(* deferred-add (pa,s0) read off the exit RAX/R14; the completing hyp           *)
(* word_add pa s0 = EL 0 s discharges via SHA256_ACOMPLETE (SCHED_GHYP_TAC).    *)
(* The back-edge seams carry only the working-var nest s (no pa/s0).  The PCs   *)
(* 0x6e6/0x10f9 each repeat 3x; ENSURES_SEQUENCE disambiguates by waypoint       *)
(* STATE, not PC.                                                               *)
(* ========================================================================= *)

(* R_ALL: the future K-table reads (ITERATION1.pre's + ITERATION2.pre's, which  *)
(* ITERATION0/1 do not expose) + the 3 sentinel bytes, as one readonly pred.    *)
let SHA256_NOHW_LOOP_RALL =
  let (_,_,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION)) in
  let (p1_,_,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION1)) in
  let (p2_,_,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION2)) in
  let is_kread_loop t =
    is_eq t &&
    can (term_match [] `read (memory :> bytes32 (word_add (word kbytes) (word n))) ss`)
        (lhs t) &&
    (is_comb(rhs t) && (try fst(dest_const(rator(rhs t)))="word" with _ -> false)) in
  let kreads_loop pred = filter is_kread_loop (conjuncts(fullbeta_tm(mk_comb(pred,sx_state)))) in
  let sent_conjs = conjuncts(fullbeta_tm(mk_comb(
    `\s:x86state.
       read (memory :> bytes8 (word_add (word kbytes) (word 259))) s = word 39 /\
       read (memory :> bytes8 (word_add (word kbytes) (word 387))) s = word 25 /\
       read (memory :> bytes8 (word_add (word kbytes) (word 515))) s = word 0`, sx_state))) in
  mk_abs(sx_state, list_mk_conj (kreads_loop p1_ @ kreads_loop p2_ @ sent_conjs));;

let SHA256_NOHW_LOOP_IT_HYPS =
  `LENGTH (s:int32 list) = 8 /\ word_add (pa:int32) (s0:int32) = EL 0 s /\
    ALL (nonoverlapping (stackpointer:int64, 64))
        [(word pc:int64, 4465); (word kbytes:int64, 677); (datap:int64, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)`;;
let SHA256_NOHW_LOOP_BE_HYPS =
  `ALL (nonoverlapping (stackpointer:int64, 64))
        [(word pc:int64, 4465); (word kbytes:int64, 677); (datap:int64, 64)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677)`;;

(* frame all six segments with R_ALL *)
let SHA256_NOHW_ITER0_RO =
  prove_framed_group SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION  SHA256_NOHW_LOOP_RALL SHA256_NOHW_LOOP_IT_HYPS;;
let SHA256_NOHW_ITER1_RO =
  prove_framed_group SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION1 SHA256_NOHW_LOOP_RALL SHA256_NOHW_LOOP_IT_HYPS;;
let SHA256_NOHW_ITER2_RO =
  prove_framed_group SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION2 SHA256_NOHW_LOOP_RALL SHA256_NOHW_LOOP_IT_HYPS;;
let SHA256_NOHW_BE0_RO =
  prove_framed_group SHA256_BLOCK_DATA_ORDER_NOHW_BE0_WIDE   SHA256_NOHW_LOOP_RALL SHA256_NOHW_LOOP_BE_HYPS;;
let SHA256_NOHW_BE1_RO =
  prove_framed_group SHA256_BLOCK_DATA_ORDER_NOHW_BE1_WIDE   SHA256_NOHW_LOOP_RALL SHA256_NOHW_LOOP_BE_HYPS;;
let SHA256_NOHW_BE2_RO =
  prove_framed_group SHA256_BLOCK_DATA_ORDER_NOHW_BE2_WIDE   SHA256_NOHW_LOOP_RALL SHA256_NOHW_LOOP_BE_HYPS;;

(* seam-instantiation extractors: from a post predicate q (over its own opaque  *)
(* s), get (exit-nest N, partial-a pa, Sigma0 s0) = (R9-arg, RAX, R14) values.  *)
let sha256_nohw_seam_of q =
  let strip_zx t = match t with Comb(Const("word_zx",_),u)->u | _ -> t in
  let reg_rhs cs rn = rhs(find (fun t -> is_eq t &&
     (match lhs t with Comb(Comb(Const("read",_),Const(r,_)),_)->r=rn|_->false)) cs) in
  let cs = conjuncts(fullbeta_tm(mk_comb(q,sx_state))) in
  (rand (strip_zx (reg_rhs cs "R9")), strip_zx (reg_rhs cs "RAX"), strip_zx (reg_rhs cs "R14"));;

(* generic two-segment seam compose (mirrors COMPOSE_456): chain thm segA with   *)
(* lemma segB at seam_pc, instantiating segB's opaque vars via `inst`, segB's    *)
(* hyp via ghyp_tac. Returns `hyp(segA) ==> ensures x86 segA.pre segB.post[inst]  *)
(* segA.frame`.  All preds canonicalised so ENSURES_SEQUENCE_TAC sees the         *)
(* bytes_loaded/RIP-first shape.                                                  *)
let sha256_nohw_compose_seam segA segB seam_pc inst ghyp_tac =
  let ae = REWRITE_RULE[SOME_FLAGS] (SPEC_ALL segA) in
  let be = REWRITE_RULE[SOME_FLAGS] (SPEC_ALL segB) in
  let (pa_,qa_,ca_) = dest_ens_x86 (ens_concl ae) in
  let (pb_,qb_,_) = dest_ens_x86 (ens_concl be) in
  let pbi = inst pb_ and qbi = inst qb_ in
  prove
   (mk_imp(fst(dest_imp(concl ae)),
       list_mk_comb(`ensures x86`, [canon_pred pa_; canon_pred qbi; ca_])),
    DISCH_THEN(fun th -> ASSUME_TAC th THEN MP_TAC th) THEN
    REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    ENSURES_SEQUENCE_TAC seam_pc (canon_rest qa_) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
      MAP_EVERY EXISTS_TAC [pa_; qa_] THEN
      REPEAT CONJ_TAC THENL
       [SHA256_NOHW_SEAM_BRIDGE_TAC; SHA256_NOHW_SEAM_BRIDGE_TAC;
        MATCH_MP_TAC ae THEN ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES]];
      MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
      MAP_EVERY EXISTS_TAC [pbi; qbi] THEN
      REPEAT CONJ_TAC THENL
       [SHA256_NOHW_SEAM_BRIDGE_TAC; SHA256_NOHW_SEAM_BRIDGE_TAC;
        MATCH_MP_TAC be THEN ghyp_tac]]);;

(* seam values: N0/pa0/s00 from ITERATION0 post; N1/pa1/s01 from ITERATION1 post *)
(* (the latter generic over its own s, then instantiated at s:=N0).              *)
let (sha256_nohw_n0, sha256_nohw_pa0, sha256_nohw_s00) =
  let (_,q0_,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION)) in
  sha256_nohw_seam_of q0_;;
let (sha256_nohw_n1, sha256_nohw_pa1, sha256_nohw_s01) =
  let (_,q1_,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_ITERATION1)) in
  let (n1g,pa1g,s01g) = sha256_nohw_seam_of q1_ in
  (vsubst [sha256_nohw_n0,`s:int32 list`] n1g,
   vsubst [sha256_nohw_n0,`s:int32 list`] pa1g,
   vsubst [sha256_nohw_n0,`s:int32 list`] s01g);;

let sha256_nohw_id_inst t = t;;
let sha256_nohw_inst1 t =
  vsubst [sha256_nohw_n0,`s:int32 list`; sha256_nohw_pa0,`pa:int32`; sha256_nohw_s00,`s0:int32`] t;;
let sha256_nohw_inst2 t =
  vsubst [sha256_nohw_n1,`s:int32 list`; sha256_nohw_pa1,`pa:int32`; sha256_nohw_s01,`s0:int32`] t;;
let sha256_nohw_sinst1 t = vsubst [sha256_nohw_n0,`s:int32 list`] t;;
let sha256_nohw_sinst2 t = vsubst [sha256_nohw_n1,`s:int32 list`] t;;
let SHA256_NOHW_ASM_GHYP = ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES];;

(* the 5 chained compose steps; final = the full loop ensures (0x6e6 -> 0x1103). *)
let SHA256_NOHW_LOOP_A =
  sha256_nohw_compose_seam SHA256_NOHW_ITER0_RO SHA256_NOHW_BE0_RO
    `pc + 0x10f9` sha256_nohw_id_inst SHA256_NOHW_ASM_GHYP;;
let SHA256_NOHW_LOOP_B =
  sha256_nohw_compose_seam SHA256_NOHW_LOOP_A SHA256_NOHW_ITER1_RO
    `pc + 0x6e6` sha256_nohw_inst1 SHA256_NOHW_SCHED_GHYP_TAC;;
let SHA256_NOHW_LOOP_C =
  sha256_nohw_compose_seam SHA256_NOHW_LOOP_B SHA256_NOHW_BE1_RO
    `pc + 0x10f9` sha256_nohw_sinst1 SHA256_NOHW_ASM_GHYP;;
let SHA256_NOHW_LOOP_D =
  sha256_nohw_compose_seam SHA256_NOHW_LOOP_C SHA256_NOHW_ITER2_RO
    `pc + 0x6e6` sha256_nohw_inst2 SHA256_NOHW_SCHED_GHYP_TAC;;
let SHA256_BLOCK_DATA_ORDER_NOHW_ROUNDS_16_XX_LOOP =
  sha256_nohw_compose_seam SHA256_NOHW_LOOP_D SHA256_NOHW_BE2_RO
    `pc + 0x10f9` sha256_nohw_sinst2 SHA256_NOHW_ASM_GHYP;;

(* ========================================================================= *)
(* PHASE 8: promote the loop ensures to a PUBLIC bytelist-only precondition.   *)
(* The composed ROUNDS_16_XX_LOOP carries R_ALL = 48 concrete doubled-K        *)
(* bytes32 reads (offsets 128..492 = spec K[16..63]) + 3 sentinel bytes8       *)
(* (kbytes+259/387/515) in its precondition -- these were threaded through the  *)
(* 6 unroll segments by ENSURES_FRAME_RO and must NOT leak into the public      *)
(* subroutine spec.  They are all TRUE readonly K256_data reads, recoverable    *)
(* from the single readonly K256_data bytelist read, exactly as the PROLOGUE    *)
(* public form recovers K[4..15] via KVALS_4_15.  Here we additionally recover  *)
(* the loop-termination sentinels via SHA256_NOHW_SENTINEL_BYTES.               *)
(* ========================================================================= *)

(* recover all 48 doubled-K bytes32 reads (K[16..63]) from the bytelist; the    *)
(* conjunct list is extracted from the committed loop pre (correct-by-construc-  *)
(* tion), proof mirrors KVALS_4_15.                                             *)
let SHA256_NOHW_KVALS_16_63 =
  let (pp,_,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_ROUNDS_16_XX_LOOP)) in
  let is_kread t =
    is_eq t &&
    can (term_match [] `read (memory :> bytes32 (word_add (word kbytes) (word n))) ss`)
        (lhs t) &&
    (is_comb(rhs t) && (try fst(dest_const(rator(rhs t)))="word" with _ -> false)) in
  let xv = `x:x86state` in
  let kreads_x = map (vsubst [xv,sx_state])
                     (filter is_kread (conjuncts(fullbeta_tm(mk_comb(pp,sx_state))))) in
  let blread = mk_eq(
    mk_comb(mk_comb(`read:(x86state,byte list)component->x86state->byte list`,
      `memory :> bytelist (word kbytes, LENGTH K256_data)`), xv),
    `K256_data`) in
  prove
   (mk_forall(`kbytes:num`, mk_forall(xv, mk_imp(blread, list_mk_conj kreads_x))),
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    EXPLODE_BYTELIST_ASSUM_TAC sha256_block_data_order_nohw_constants_data THEN
    REPEAT CONJ_TAC THEN
    (fun (asl,w) -> INTRO_READ_MEMORY_FROM_BYTES8_TAC (lhs w) (asl,w)) THEN
    ASM_REWRITE_TAC[]);;

(* public loop form: drop the 48 K-reads + 3 sentinels from the precondition,   *)
(* add the single readonly K256_data bytelist read; recover the dropped facts    *)
(* via KVALS_16_63 + SENTINEL_BYTES (ENSURES_PRECONDITION_THM, mirrors PROLOGUE).*)
let SHA256_BLOCK_DATA_ORDER_NOHW_ROUNDS_16_XX_LOOP_PUB =
  let lp = SHA256_BLOCK_DATA_ORDER_NOHW_ROUNDS_16_XX_LOOP in
  let (lp_p,lp_q,lp_c) = dest_ens_x86 (ens_concl (SPEC_ALL lp)) in
  let is_kread t =
    is_eq t &&
    can (term_match [] `read (memory :> bytes32 (word_add (word kbytes) (word n))) ss`)
        (lhs t) &&
    (is_comb(rhs t) && (try fst(dest_const(rator(rhs t)))="word" with _ -> false)) in
  let is_sent t =
    is_eq t &&
    can (term_match [] `read (memory :> bytes8 (word_add (word kbytes) (word n))) ss`)
        (lhs t) in
  let blread = mk_eq(
    mk_comb(mk_comb(`read:(x86state,byte list)component->x86state->byte list`,
      `memory :> bytelist (word kbytes, LENGTH K256_data)`), sx_state),
    `K256_data`) in
  let kept = filter (fun t -> not(is_kread t || is_sent t))
                    (conjuncts (fullbeta_tm (mk_comb(lp_p, sx_state)))) in
  let pub_pre = mk_abs(sx_state, list_mk_conj (kept @ [blread])) in
  let goal = mk_imp(fst(dest_imp(concl (SPEC_ALL lp))),
               list_mk_comb(`ensures x86`, [pub_pre; lp_q; lp_c])) in
  prove
   (goal,
    STRIP_TAC THEN MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
    EXISTS_TAC lp_p THEN CONJ_TAC THENL
     [GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
      FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP (SPEC_ALL SHA256_NOHW_KVALS_16_63)) THEN
      FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP (SPEC_ALL SHA256_NOHW_SENTINEL_BYTES)) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC lp THEN ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* PHASE 8: the add-back TAIL (tmc 0x1103 -> 0x114a, 20 instrs).               *)
(*   0x1103 mov 0x40(%rsp),%rdi    reload statep (= [stackpointer+64])         *)
(*   0x1108 add %r14d,%eax         deferred add: completes EL0/a (= pa + s0)   *)
(*   0x110b lea 0x40(%rsi),%rsi    advance data ptr (dead for one block)       *)
(*   0x110f..0x1126  8x add k(%rdi),reg   reg += state[k/4]  (add-back)         *)
(*   0x112a cmp 0x50(%rsp),%rsi    flags only                                  *)
(*   0x112f..0x1146  8x mov reg,k(%rdi)   state'[k/4] = reg                     *)
(* Stated over an OPAQUE completed 64-round state N (LENGTH 8) with the         *)
(* deferred-add pair (pa,s0), hyp word_add pa s0 = EL 0 N, matching the loop    *)
(* exit shape (RAX=partial-a, R14=Sigma0, RBX..R11 = EL1..7 N).  The input      *)
(* hash h (LENGTH 8) is read-only in [statep+4i]; the post writes back          *)
(* word_add (EL i h) (EL i N), i.e. EL i (sha256_addback h N).                  *)
(* ========================================================================= *)
let SHA256_BLOCK_DATA_ORDER_NOHW_TAIL = prove
 (`!(N:int32 list) (pa:int32) (s0:int32) (h:int32 list).
   !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap statep:int64.
    LENGTH N = 8 /\ LENGTH h = 8 /\ word_add pa s0 = EL 0 N /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64); (statep, 32)] /\
    nonoverlapping (statep, 32) (word pc:int64, 4465)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x1103) /\
              read RSP s = stackpointer /\
              read (memory :> bytes64 (word_add stackpointer (word 64))) s = statep /\
              read (memory :> bytes32 statep) s = word_zx (EL 0 h) /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx (EL 1 h) /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx (EL 2 h) /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx (EL 3 h) /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx (EL 4 h) /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx (EL 5 h) /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx (EL 6 h) /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx (EL 7 h) /\
              read RAX s = word_zx pa /\ read R14 s = word_zx s0 /\
              read RBX s = word_zx (EL 1 N) /\
              read RCX s = word_zx (EL 2 N) /\
              read RDX s = word_zx (EL 3 N) /\
              read R8 s = word_zx (EL 4 N) /\
              read R9 s = word_zx (EL 5 N) /\
              read R10 s = word_zx (EL 6 N) /\
              read R11 s = word_zx (EL 7 N))
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x114a) /\
              read (memory :> bytes32 statep) s = word_zx (word_add (EL 0 h) (EL 0 N)) /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx (word_add (EL 1 h) (EL 1 N)) /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx (word_add (EL 2 h) (EL 2 N)) /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx (word_add (EL 3 h) (EL 3 N)) /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx (word_add (EL 4 h) (EL 4 N)) /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx (word_add (EL 5 h) (EL 5 N)) /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx (word_add (EL 6 h) (EL 6 N)) /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx (word_add (EL 7 h) (EL 7 N)))
         (MAYCHANGE [RIP; RDI; RSI; RAX; RBX; RCX; RDX; R8; R9; R10; R11] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(statep, 32)])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--20) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  SIMP_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH; WORD_ZX_TRIVIAL] THEN
  REPEAT CONJ_TAC THEN
  TRY(FIRST_X_ASSUM(fun th -> let _ = term_match [] `word_add pa s0 = EL 0 N` (concl th) in
                             REWRITE_TAC[SYM th])) THEN
  CONV_TAC WORD_RULE);;

(* ========================================================================= *)
(* PHASE 8: thread the state buffer (statep + the input hash) through the     *)
(* compression as a readonly predicate R_STATE, so the add-back TAIL has its   *)
(* preconditions (statep saved at [stackpointer+64]; input hash a..h held in   *)
(* [statep+4i]) in scope at tmc 0x1103.  The PROLOGUE/LOOP frames write only    *)
(* registers, flags, events and bytes(stackpointer,64); R_STATE reads at        *)
(* statep / stackpointer+64 are all orthogonal to those, so R_STATE survives    *)
(* both segments (ENSURES_FRAME_RO).                                            *)
(*                                                                           *)
(* KFRAME_PRESERVE_TAC cannot be reused verbatim: it closes each preserved-read *)
(* conjunct by SYM-rewriting the goal's RHS with the FIRST assumption matching  *)
(* that RHS, but the input-hash reads have RHS `word_zx a` which coincides with *)
(* the register-read assumptions `read RAX s = word_zx a` in the pre -- so it    *)
(* picks the wrong (register) read and READ_OVER_WRITE_ORTHOGONAL_TAC then       *)
(* fails.  RO_STATE_PRESERVE_TAC instead matches the assumption by COMPONENT     *)
(* (read C s = .. with the same C as the goal's read C (write..s)).             *)
(* ========================================================================= *)

let RO_STATE_PRESERVE_TAC =
  RULE_ASSUM_TAC(REWRITE_RULE[ALL;NONOVERLAPPING_CLAUSES]) THEN REPEAT GEN_TAC THEN
  CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (ASSUME_TAC o CONV_RULE(TOP_DEPTH_CONV BETA_CONV)) MP_TAC) THEN
  REWRITE_TAC[MAYCHANGE; SEQ_ID; SOME_FLAGS] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
  PURE_REWRITE_TAC[ASSIGNS_SEQ] THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  REWRITE_TAC[ASSIGNS_THM] THEN REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REPEAT(FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC o check(is_conj o concl))) THEN
  FIRST_X_ASSUM(SUBST1_TAC o SYM o
    check (fun th -> is_eq(concl th) &&
                     (match rand(concl th) with Var(n,_) -> n="s2" | _ -> false))) THEN
  REPEAT CONJ_TAC THEN
  W(fun (asl,gl) ->
     let cg = rand(rator(lhs gl)) in
     FIRST_X_ASSUM(fun th ->
       if is_eq(concl th) && can (fun t -> rand(rator(lhs(concl t)))) th &&
          rand(rator(lhs(concl th))) = cg
       then GEN_REWRITE_TAC RAND_CONV [SYM th] else failwith "nc")) THEN
  READ_OVER_WRITE_ORTHOGONAL_TAC;;

(* prove_framed_group_ro: like prove_framed_group but uses RO_STATE_PRESERVE_TAC  *)
(* for the readonly side and a flattened-ALL ASM_REWRITE for the lemma's hyp.    *)
let prove_framed_group_ro lem rtm hyptm =
  let ens_of th = let c = concl(SPEC_ALL th) in if is_imp c then snd(dest_imp c) else c in
  let ens_pre th = let e = ens_of th in rand(rator(rator e)) in
  let ens_post th = let e = ens_of th in rand(rator e) in
  let ens_frame th = let e = ens_of th in rand e in
  let v = `s:x86state` in
  let conj_pred p = mk_abs(v, mk_conj(mk_comb(p,v), mk_comb(rtm,v))) in
  prove
   (mk_imp(hyptm,
      list_mk_comb(`ensures x86`,
        [conj_pred (ens_pre lem); conj_pred (ens_post lem); ens_frame lem])),
    STRIP_TAC THEN MATCH_MP_TAC ENSURES_FRAME_RO THEN CONJ_TAC THENL
     [RO_STATE_PRESERVE_TAC;
      MATCH_MP_TAC lem THEN
      RULE_ASSUM_TAC(REWRITE_RULE[ALL;NONOVERLAPPING_CLAUSES]) THEN
      ASM_REWRITE_TAC[ALL;NONOVERLAPPING_CLAUSES]]);;

(* R_STATE: the state buffer facts the add-back tail consumes, readonly across   *)
(* the whole compression.  a..h are the input hash words (= the PROLOGUE's        *)
(* working-var inputs), so EL i [a;..;h] is the input hash for the add-back.     *)
let R_STATE = `\s:x86state.
    read (memory :> bytes64 (word_add stackpointer (word 64))) s = statep /\
    read (memory :> bytes32 statep) s = word_zx (a:int32) /\
    read (memory :> bytes32 (word_add statep (word 4))) s = word_zx (b:int32) /\
    read (memory :> bytes32 (word_add statep (word 8))) s = word_zx (c:int32) /\
    read (memory :> bytes32 (word_add statep (word 12))) s = word_zx (d:int32) /\
    read (memory :> bytes32 (word_add statep (word 16))) s = word_zx (e:int32) /\
    read (memory :> bytes32 (word_add statep (word 20))) s = word_zx (f:int32) /\
    read (memory :> bytes32 (word_add statep (word 24))) s = word_zx (g:int32) /\
    read (memory :> bytes32 (word_add statep (word 28))) s = word_zx (h:int32)`;;

(* framing hyps: PROLOGUE/LOOP own hyps PLUS the statep nonoverlap (so R_STATE is  *)
(* preserved and the tail's nonoverlapping (statep,32)(word pc,..) is in scope).  *)
let PL_FRAME_HYPS = `riprel32_within_bounds kbytes (pc + 0x57) /\
    ALL (nonoverlapping (stackpointer:int64, 64))
        [(word pc:int64, 4465); (word kbytes:int64, 677); (datap:int64, 64); (statep:int64, 32)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (word pc:int64, 4465)`;;
let LOOP_FRAME_HYPS = `LENGTH (s:int32 list) = 8 /\ word_add (pa:int32) (s0:int32) = EL 0 s /\
    ALL (nonoverlapping (stackpointer:int64, 64))
        [(word pc:int64, 4465); (word kbytes:int64, 677); (datap:int64, 64); (statep:int64, 32)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (word pc:int64, 4465)`;;

let SHA256_NOHW_PROLOGUE_RO =
  prove_framed_group_ro SHA256_BLOCK_DATA_ORDER_NOHW_PROLOGUE R_STATE PL_FRAME_HYPS;;

(* ========================================================================= *)
(* PHASE 8: seam PROLOGUE ; ROUNDS_16_XX_LOOP at tmc 0x6e6 (-> 0x4e -> 0x1103).*)
(* The LOOP's precondition needs (a) the working vars over an opaque s, (b) all *)
(* 48 doubled-K reads K[16..63] @ kbytes+128..492 + 3 sentinels (R_ALL is only   *)
(* the 256..492 subset; the iteration-0 groups also need 128..236), (c) R_STATE.  *)
(* PROLOGUE.post exposes only the K[12..15] reads, so we thread the full K/      *)
(* sentinel block (K_FULL_PRED) through PROLOGUE read-only via the committed      *)
(* KFRAME prove_framed_group (concrete word-k reads -- KFRAME-friendly).  R_STATE *)
(* is threaded by the component-matching prove_framed_group_ro.  We compose       *)
(* against the ORIGINAL LOOP (concrete-K pre), NOT the bytelist-public form: the  *)
(* bytelist read cannot be framed (its LENGTH won't reduce for the orthogonality  *)
(* -- session-015's wall), so the public bytelist promotion is deferred to the    *)
(* full-block level (mirrors PROLOGUE/LOOP_PUB).                                   *)
(* The seam instantiates the LOOP's opaque s := the exact compress_round nest      *)
(* PROLOGUE.post exposes (so EL i s matches by syntactic identity); the deferred-  *)
(* add hyp word_add pa s0 = EL 0 s is SHA256_ACOMPLETE at the seam state.           *)
(* ========================================================================= *)

(* K_FULL_PRED: the 48 K[16..63] bytes32 reads + 3 sentinel bytes8, extracted     *)
(* from the committed LOOP precondition (correct-by-construction).                *)
let K_FULL_PRED =
  let (pp,_,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_ROUNDS_16_XX_LOOP)) in
  let is_kf t =
    is_eq t &&
    (can (term_match [] `read (memory :> bytes32 (word_add (word kbytes) (word n))) ss`) (lhs t) ||
     can (term_match [] `read (memory :> bytes8 (word_add (word kbytes) (word n))) ss`) (lhs t)) &&
    (is_comb(rhs t) && (try fst(dest_const(rator(rhs t)))="word" with _ -> false)) in
  mk_abs(sx_state, list_mk_conj (filter is_kf (conjuncts(fullbeta_tm(mk_comb(pp,sx_state))))));;

(* PROLOGUE with R_STATE AND the full K/sentinel block in pre/post. *)
let SHA256_NOHW_PROLOGUE_RO_K =
  prove_framed_group SHA256_NOHW_PROLOGUE_RO K_FULL_PRED PL_FRAME_HYPS;;

(* the original LOOP (concrete-K pre) with R_STATE framed. *)
let SHA256_NOHW_LOOP_RO_ORIG =
  prove_framed_group_ro SHA256_BLOCK_DATA_ORDER_NOHW_ROUNDS_16_XX_LOOP R_STATE LOOP_FRAME_HYPS;;

(* seam instantiation: s := the exact PROLOGUE.post compress_round nest. *)
let (prol_state, prol_pa, prol_s0) =
  let (_,q,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_PROLOGUE)) in
  sha256_nohw_seam_of q;;
let pl_seam_inst t =
  vsubst [prol_state, `s:int32 list`; prol_pa, `pa:int32`; prol_s0, `s0:int32`] t;;
let PL_SEAM_GHYP_TAC =
  REWRITE_TAC[SHA256_COMPRESS_ROUND_LENGTH; SHA256_ACOMPLETE] THEN
  ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES];;

(* PROLOGUE ; LOOP composed: tmc 0x4e -> 0x1103. *)
let SHA256_NOHW_PL_LOOP =
  sha256_nohw_compose_seam SHA256_NOHW_PROLOGUE_RO_K SHA256_NOHW_LOOP_RO_ORIG
    `pc + 0x6e6` pl_seam_inst PL_SEAM_GHYP_TAC;;

(* ========================================================================= *)
(* PHASE 8: seam PL_LOOP ; TAIL at tmc 0x1103 -> the raw one-block ensures      *)
(* (tmc 0x4e -> 0x114a).  The TAIL frame (writes bytes(statep,32) + RSI) differs *)
(* from the PL_LOOP frame (writes bytes(stackpointer,64) + RBP/R12..R15), so we   *)
(* widen BOTH to the union frame C_FULL via ENSURES_FRAME_SUBSUMED before          *)
(* ENSURES_SEQUENCE.  The seam instantiates the TAIL's opaque N := the PL_LOOP     *)
(* exit compress^64 nest, the deferred-add (pa,s0) off the exit RAX/R14, and the    *)
(* input hash h := [a;..;h] (the PROLOGUE's working-var inputs, held read-only in   *)
(* [statep+4i] via R_STATE).  The waypoint->TAIL.pre bridge needs EL_CONV (to       *)
(* reduce EL i [a;..;h] = the R_STATE input-hash reads).                            *)
(* ========================================================================= *)

let C_FULL =
  `MAYCHANGE [RIP; RDI; RSI; RBP; RAX; RBX; RCX; RDX; R8; R9; R10; R11; R12; R13; R14; R15] ,,
   MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events] ,,
   MAYCHANGE [memory :> bytes(stackpointer, 64)] ,,
   MAYCHANGE [memory :> bytes(statep, 32)]`;;

(* TAIL instantiation from the PL_LOOP exit state. *)
let (tail_N, tail_pa, tail_s0) =
  let (_,q,_) = dest_ens_x86 (ens_concl (SPEC_ALL SHA256_NOHW_PL_LOOP)) in
  let strip_zx t = match t with Comb(Const("word_zx",_),u)->u | _ -> t in
  let cs = conjuncts(fullbeta_tm(mk_comb(q,sx_state))) in
  let reg rn = rhs(find (fun t -> is_eq t &&
     (match lhs t with Comb(Comb(Const("read",_),Const(r,_)),_)->r=rn|_->false)) cs) in
  (rand (strip_zx (reg "R11")), strip_zx (reg "RAX"), strip_zx (reg "R14"));;
let tail_h = `[a;b;c;d;e;f;g;h]:int32 list`;;
let tail_inst t =
  vsubst [tail_N,`N:int32 list`; tail_pa,`pa:int32`; tail_s0,`s0:int32`;
          tail_h,`h:int32 list`] t;;

(* PL_LOOP ; TAIL composed under C_FULL: tmc 0x4e -> 0x114a.  Post writes the      *)
(* add-back word_add (EL i [a;..;h]) (EL i (compress^64 [a;..;h])) to [statep+4i].  *)
let SHA256_NOHW_FULLBLOCK_RAW =
  let ae = REWRITE_RULE[SOME_FLAGS] (SPEC_ALL SHA256_NOHW_PL_LOOP) in
  let be = REWRITE_RULE[SOME_FLAGS] (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_TAIL) in
  let (pa_,qa_,ca_) = dest_ens_x86 (ens_concl ae) in
  let (pb_,qb_,cb_) = dest_ens_x86 (ens_concl be) in
  let pbi = tail_inst pb_ and qbi = tail_inst qb_ in
  let cfull = rhs(concl(REWRITE_CONV[SOME_FLAGS] C_FULL)) in
  let goal = mk_imp(fst(dest_imp(concl ae)),
               list_mk_comb(`ensures x86`, [canon_pred pa_; canon_pred qbi; cfull])) in
  prove
   (goal,
    DISCH_THEN(fun th -> ASSUME_TAC th THEN MP_TAC th) THEN
    REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    ENSURES_SEQUENCE_TAC `pc + 0x1103` (canon_rest qa_) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
      EXISTS_TAC ca_ THEN CONJ_TAC THENL
       [REWRITE_TAC[SOME_FLAGS] THEN SUBSUMED_MAYCHANGE_TAC;
        MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
        MAP_EVERY EXISTS_TAC [pa_; qa_] THEN
        REPEAT CONJ_TAC THENL
         [SHA256_NOHW_SEAM_BRIDGE_TAC; SHA256_NOHW_SEAM_BRIDGE_TAC;
          MATCH_MP_TAC ae THEN ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES]]];
      MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
      EXISTS_TAC cb_ THEN CONJ_TAC THENL
       [REWRITE_TAC[SOME_FLAGS] THEN SUBSUMED_MAYCHANGE_TAC;
        MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
        MAP_EVERY EXISTS_TAC [pbi; qbi] THEN
        REPEAT CONJ_TAC THENL
         [GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
          CONV_TAC(DEPTH_CONV EL_CONV) THEN ASM_REWRITE_TAC[];
          GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
          ASM_REWRITE_TAC[];
          MATCH_MP_TAC be THEN
          REWRITE_TAC[SHA256_COMPRESS_ROUND_LENGTH; LENGTH] THEN
          CONV_TAC NUM_REDUCE_CONV THEN
          ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN
          REWRITE_TAC[SHA256_ACOMPLETE]]]]);;

(* ========================================================================= *)
(* PHASE 8: fold the raw add-back post to the sha256_block spec form and       *)
(* promote the precondition to bytelist-only -> the one-full-block CORE.        *)
(* SHA256_COMPRESS_64_FROM_4 folds the explicit 64-deep compress_round nest      *)
(* (the FULLBLOCK_RAW exit shape, bottoming at compress m 4) back to             *)
(* sha256_compress m 64; SHA256_BLOCK_EL then gives                              *)
(*   EL i (sha256_block m h) = word_add (EL i h) (EL i (compress m 64 h)),        *)
(* matching the raw add-back post.  The public pre drops the 48 K[16..63] reads   *)
(* + 3 sentinels (recovered from the K256_data bytelist via KVALS_16_63 +         *)
(* SENTINEL_BYTES).                                                               *)
(* ========================================================================= *)

let SHA256_COMPRESS_64_FROM_4 = prove
 (`!m s:int32 list. sha256_compress m 64 s = sha256_compress_round m 63 (sha256_compress_round m 62 (sha256_compress_round m 61 (sha256_compress_round m 60 (sha256_compress_round m 59 (sha256_compress_round m 58 (sha256_compress_round m 57 (sha256_compress_round m 56 (sha256_compress_round m 55 (sha256_compress_round m 54 (sha256_compress_round m 53 (sha256_compress_round m 52 (sha256_compress_round m 51 (sha256_compress_round m 50 (sha256_compress_round m 49 (sha256_compress_round m 48 (sha256_compress_round m 47 (sha256_compress_round m 46 (sha256_compress_round m 45 (sha256_compress_round m 44 (sha256_compress_round m 43 (sha256_compress_round m 42 (sha256_compress_round m 41 (sha256_compress_round m 40 (sha256_compress_round m 39 (sha256_compress_round m 38 (sha256_compress_round m 37 (sha256_compress_round m 36 (sha256_compress_round m 35 (sha256_compress_round m 34 (sha256_compress_round m 33 (sha256_compress_round m 32 (sha256_compress_round m 31 (sha256_compress_round m 30 (sha256_compress_round m 29 (sha256_compress_round m 28 (sha256_compress_round m 27 (sha256_compress_round m 26 (sha256_compress_round m 25 (sha256_compress_round m 24 (sha256_compress_round m 23 (sha256_compress_round m 22 (sha256_compress_round m 21 (sha256_compress_round m 20 (sha256_compress_round m 19 (sha256_compress_round m 18 (sha256_compress_round m 17 (sha256_compress_round m 16 (sha256_compress_round m 15 (sha256_compress_round m 14 (sha256_compress_round m 13 (sha256_compress_round m 12 (sha256_compress_round m 11 (sha256_compress_round m 10 (sha256_compress_round m 9 (sha256_compress_round m 8 (sha256_compress_round m 7 (sha256_compress_round m 6 (sha256_compress_round m 5 (sha256_compress_round m 4 (sha256_compress m 4 s))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))`,
  REWRITE_TAC[num_CONV `64`; num_CONV `63`; num_CONV `62`; num_CONV `61`; num_CONV `60`; num_CONV `59`; num_CONV `58`; num_CONV `57`; num_CONV `56`; num_CONV `55`; num_CONV `54`; num_CONV `53`; num_CONV `52`; num_CONV `51`; num_CONV `50`; num_CONV `49`; num_CONV `48`; num_CONV `47`; num_CONV `46`; num_CONV `45`; num_CONV `44`; num_CONV `43`; num_CONV `42`; num_CONV `41`; num_CONV `40`; num_CONV `39`; num_CONV `38`; num_CONV `37`; num_CONV `36`; num_CONV `35`; num_CONV `34`; num_CONV `33`; num_CONV `32`; num_CONV `31`; num_CONV `30`; num_CONV `29`; num_CONV `28`; num_CONV `27`; num_CONV `26`; num_CONV `25`; num_CONV `24`; num_CONV `23`; num_CONV `22`; num_CONV `21`; num_CONV `20`; num_CONV `19`; num_CONV `18`; num_CONV `17`; num_CONV `16`; num_CONV `15`; num_CONV `14`; num_CONV `13`; num_CONV `12`; num_CONV `11`; num_CONV `10`; num_CONV `9`; num_CONV `8`; num_CONV `7`; num_CONV `6`; num_CONV `5`] THEN
  REWRITE_TAC[sha256_compress]);;

(* EL i of a full block = input word + compressed word (i<8). *)
let SHA256_BLOCK_EL = prove
 (`!m (h:int32 list) i. LENGTH h = 8 /\ i < 8
     ==> EL i (sha256_block m h) = word_add (EL i h) (EL i (sha256_compress m 64 h))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[sha256_block; sha256_addback] THEN
  SUBGOAL_THEN `LENGTH (sha256_compress m 64 (h:int32 list)) = 8` ASSUME_TAC THENL
   [ASM_MESON_TAC[SHA256_COMPRESS_LENGTH]; ALL_TAC] THEN
  MP_TAC(ISPECL [`word_add:int32->int32->int32`; `h:int32 list`;
                 `sha256_compress m 64 h`; `i:num`] EL_MAP2) THEN
  ASM_REWRITE_TAC[]);;

(* the one-full-block CORE ensures: tmc 0x4e -> 0x114a, bytelist-only public pre, *)
(* post writes state'[i] = EL i (sha256_block m [a;..;h]) to [statep+4i].         *)
let SHA256_BLOCK_DATA_ORDER_NOHW_CORE =
  let raw = SHA256_NOHW_FULLBLOCK_RAW in
  let (rp,rq,rc) = dest_ens_x86 (ens_concl (SPEC_ALL raw)) in
  let blk i = vsubst[mk_small_numeral i,`i:num`] `EL i (sha256_block m [a;b;c;d;e;f;g;h]):int32` in
  let raw_i i = mk_comb(mk_comb(`word_add:int32->int32->int32`,
                   vsubst[mk_small_numeral i,`i:num`] `EL i [a;b;c;d;e;f;g;h]:int32`),
                   mk_comb(mk_comb(`EL:num->int32 list->int32`,mk_small_numeral i),tail_N)) in
  let postsub = map (fun i -> (blk i, raw_i i)) (0--7) in
  let specq = mk_abs(sx_state, subst postsub (fullbeta_tm(mk_comb(rq,sx_state)))) in
  let is_kf t = is_eq t &&
    (can (term_match [] `read (memory :> bytes32 (word_add (word kbytes) (word n))) ss`) (lhs t) ||
     can (term_match [] `read (memory :> bytes8 (word_add (word kbytes) (word n))) ss`) (lhs t)) &&
    (is_comb(rhs t) && (try fst(dest_const(rator(rhs t)))="word" with _ -> false)) in
  let blread = mk_eq(mk_comb(mk_comb(`read:(x86state,byte list)component->x86state->byte list`,
      `memory :> bytelist (word kbytes, LENGTH K256_data)`), sx_state), `K256_data`) in
  let pubp = mk_abs(sx_state, list_mk_conj
     ((filter (fun t -> not(is_kf t)) (conjuncts(fullbeta_tm(mk_comb(rp,sx_state))))) @ [blread])) in
  let goal = mk_imp(fst(dest_imp(concl (SPEC_ALL raw))),
               list_mk_comb(`ensures x86`, [pubp; specq; rc])) in
  prove
   (goal,
    STRIP_TAC THEN
    MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN EXISTS_TAC rp THEN CONJ_TAC THENL
     [GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
      FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP (SPEC_ALL SHA256_NOHW_KVALS_16_63)) THEN
      FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP (SPEC_ALL SHA256_NOHW_SENTINEL_BYTES)) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN EXISTS_TAC rq THEN CONJ_TAC THENL
       [GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
        ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN (mk_eq(tail_N, `sha256_compress m 64 [a;b;c;d;e;f;g;h]`))
          SUBST1_TAC THENL
         [REWRITE_TAC[SHA256_COMPRESS_64_FROM_4]; ALL_TAC] THEN
        SIMP_TAC[SHA256_BLOCK_EL; LENGTH; ARITH] THEN
        CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[];
        MATCH_MP_TAC raw THEN ASM_REWRITE_TAC[]]]);;

(* ========================================================================= *)
(* PHASE 9: multi-block outer loop.  Wide single-block body + ENSURES_WHILE_   *)
(* PUP_TAC over num_blocks.                                                    *)
(* ========================================================================= *)

(* TAIL_WIDE_CORE: tail 0x1103->0x114a, wide post (regs+RSI+CF+state-writes) but    *)
(* WITHOUT the [sp+64]/[sp+80] bookkeeping reads in the post (those are threaded     *)
(* on later via ENSURES_FRAME_RO since the tail never writes the stack).             *)
let SHA256_BLOCK_DATA_ORDER_NOHW_TAIL_WIDE_CORE = prove
 (`!(N:int32 list) (pa:int32) (s0:int32) (h:int32 list).
   !m:num->int32. !kbytes:num. !pc stackpointer:int64. !datap statep ri dend:int64.
    LENGTH N = 8 /\ LENGTH h = 8 /\ word_add pa s0 = EL 0 N /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64); (statep, 32)] /\
    nonoverlapping (statep, 32) (word pc:int64, 4465)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x1103) /\
              read RSP s = stackpointer /\
              read RSI s = ri /\
              read (memory :> bytes64 (word_add stackpointer (word 64))) s = statep /\
              read (memory :> bytes64 (word_add stackpointer (word 80))) s = dend /\
              read (memory :> bytes32 statep) s = word_zx (EL 0 h) /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx (EL 1 h) /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx (EL 2 h) /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx (EL 3 h) /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx (EL 4 h) /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx (EL 5 h) /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx (EL 6 h) /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx (EL 7 h) /\
              read RAX s = word_zx pa /\ read R14 s = word_zx s0 /\
              read RBX s = word_zx (EL 1 N) /\ read RCX s = word_zx (EL 2 N) /\
              read RDX s = word_zx (EL 3 N) /\ read R8 s = word_zx (EL 4 N) /\
              read R9 s = word_zx (EL 5 N) /\ read R10 s = word_zx (EL 6 N) /\
              read R11 s = word_zx (EL 7 N))
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x114a) /\
              read RSP s = stackpointer /\
              read RSI s = word_add ri (word 64) /\
              (read CF s <=> val (word_add ri (word 64):int64) < val (dend:int64)) /\
              read RAX s = word_zx (word_add (EL 0 h) (EL 0 N)) /\
              read RBX s = word_zx (word_add (EL 1 h) (EL 1 N)) /\
              read RCX s = word_zx (word_add (EL 2 h) (EL 2 N)) /\
              read RDX s = word_zx (word_add (EL 3 h) (EL 3 N)) /\
              read R8 s = word_zx (word_add (EL 4 h) (EL 4 N)) /\
              read R9 s = word_zx (word_add (EL 5 h) (EL 5 N)) /\
              read R10 s = word_zx (word_add (EL 6 h) (EL 6 N)) /\
              read R11 s = word_zx (word_add (EL 7 h) (EL 7 N)) /\
              read (memory :> bytes32 statep) s = word_zx (word_add (EL 0 h) (EL 0 N)) /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx (word_add (EL 1 h) (EL 1 N)) /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx (word_add (EL 2 h) (EL 2 N)) /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx (word_add (EL 3 h) (EL 3 N)) /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx (word_add (EL 4 h) (EL 4 N)) /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx (word_add (EL 5 h) (EL 5 N)) /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx (word_add (EL 6 h) (EL 6 N)) /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx (word_add (EL 7 h) (EL 7 N)))
         (MAYCHANGE [RIP; RDI; RSI; RAX; RBX; RCX; RDX; R8; R9; R10; R11] ,,
          MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(statep, 32)])`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--20) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  SIMP_TAC[WORD_ZX_ZX; DIMINDEX_32; DIMINDEX_64; LE_REFL; ARITH; WORD_ZX_TRIVIAL] THEN
  FIRST_ASSUM(fun th -> let _ = term_match [] `word_add pa s0 = EL 0 N` (concl th) in
                        REWRITE_TAC[SYM th]) THEN
  REPEAT CONJ_TAC THEN
  TRY AP_TERM_TAC THEN CONV_TAC WORD_RULE);;
(* ========================================================================= *)
(* PHASE 9: TAIL_WIDE — the add-back tail (tmc 0x1103 -> 0x114a) with a WIDE   *)
(* post for use as the multi-block loop body.  TAIL_WIDE_CORE gives the regs/   *)
(* RSI/CF/state-writes; the loop-bookkeeping reads [sp+64]=statep, [sp+80]=dend *)
(* are conjoined read-only via ENSURES_FRAME_RO.  The tail writes only          *)
(* bytes(statep,32) (+ regs/flags/events), so with the bookkeeping region       *)
(* (sp+64,32) nonoverlapping (statep,32) the two reads survive.                 *)
(* ========================================================================= *)
let TAIL_WIDE_RO_PRED = `\s:x86state.
    read (memory :> bytes64 (word_add stackpointer (word 64))) s = statep /\
    read (memory :> bytes64 (word_add stackpointer (word 80))) s = dend`;;

(* preservation of TAIL_WIDE_RO_PRED across the tail MAYCHANGE frame *)
let TAIL_RO_PRESERVE_TAC =
  RULE_ASSUM_TAC(REWRITE_RULE[ALL;NONOVERLAPPING_CLAUSES]) THEN REPEAT GEN_TAC THEN
  CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (ASSUME_TAC o CONV_RULE(TOP_DEPTH_CONV BETA_CONV)) MP_TAC) THEN
  REWRITE_TAC[MAYCHANGE; SEQ_ID; SOME_FLAGS] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
  PURE_REWRITE_TAC[ASSIGNS_SEQ] THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  REWRITE_TAC[ASSIGNS_THM] THEN REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REPEAT(FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC o check(is_conj o concl))) THEN
  FIRST_X_ASSUM(SUBST1_TAC o SYM o
    check (fun th -> is_eq(concl th) &&
                     (match rand(concl th) with Var(n,_) -> n="s2" | _ -> false))) THEN
  REPEAT CONJ_TAC THEN
  W(fun (asl,gl) ->
     let cg = rand(rator(lhs gl)) in
     FIRST_ASSUM(fun th ->
       if is_eq(concl th) && can (fun t -> rand(rator(lhs(concl t)))) th &&
          rand(rator(lhs(concl th))) = cg
       then GEN_REWRITE_TAC RAND_CONV [SYM th] else failwith "nc")) THEN
  READ_OVER_WRITE_ORTHOGONAL_TAC;;

let SHA256_BLOCK_DATA_ORDER_NOHW_TAIL_WIDE =
  let lem = SHA256_BLOCK_DATA_ORDER_NOHW_TAIL_WIDE_CORE in
  let c = concl(SPEC_ALL lem) in
  let hyptm0 = fst(dest_imp c) in
  let extrahyp = `nonoverlapping (word_add stackpointer (word 64):int64, 32) (statep:int64,32)` in
  let hyptm = mk_conj(hyptm0, extrahyp) in
  let ens = snd(dest_imp c) in
  let pre = rand(rator(rator ens)) and post = rand(rator ens) and frame = rand ens in
  let v = `s:x86state` in
  let conj_pred p = mk_abs(v, mk_conj(mk_comb(p,v), mk_comb(TAIL_WIDE_RO_PRED,v))) in
  prove
   (mk_imp(hyptm,
      list_mk_comb(`ensures x86`, [conj_pred pre; conj_pred post; frame])),
    STRIP_TAC THEN MATCH_MP_TAC ENSURES_FRAME_RO THEN CONJ_TAC THENL
     [TAIL_RO_PRESERVE_TAC;
      MATCH_MP_TAC lem THEN EXISTS_TAC `datap:int64` THEN
      ASM_REWRITE_TAC[ALL;NONOVERLAPPING_CLAUSES]]);;

(* PL_LOOP_D: PL_LOOP with [sp+80]=dend threaded read-only (preserved by offset   *)
(* alone: PL_LOOP frame writes only bytes(stackpointer,64), sp+80 is outside).    *)
let DEND_PRED = `\s:x86state. read (memory :> bytes64 (word_add stackpointer (word 80))) s = dend`;;

let DEND_PRESERVE_TAC =
  RULE_ASSUM_TAC(REWRITE_RULE[ALL;NONOVERLAPPING_CLAUSES]) THEN REPEAT GEN_TAC THEN
  CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (ASSUME_TAC o CONV_RULE(TOP_DEPTH_CONV BETA_CONV)) MP_TAC) THEN
  REWRITE_TAC[MAYCHANGE; SEQ_ID; SOME_FLAGS] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
  PURE_REWRITE_TAC[ASSIGNS_SEQ] THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  REWRITE_TAC[ASSIGNS_THM] THEN REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REPEAT(FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC o check(is_conj o concl))) THEN
  FIRST_X_ASSUM(SUBST1_TAC o SYM o
    check (fun th -> is_eq(concl th) &&
                     (match rand(concl th) with Var(n,_) -> n="s2" | _ -> false))) THEN
  W(fun (asl,gl) ->
     let cg = rand(rator(lhs gl)) in
     FIRST_ASSUM(fun th ->
       if is_eq(concl th) && can (fun t -> rand(rator(lhs(concl t)))) th &&
          rand(rator(lhs(concl th))) = cg
       then GEN_REWRITE_TAC RAND_CONV [SYM th] else failwith "nc")) THEN
  READ_OVER_WRITE_ORTHOGONAL_TAC;;

let SHA256_NOHW_PL_LOOP_D =
  let lem = SHA256_NOHW_PL_LOOP in
  let c = concl(SPEC_ALL lem) in
  let hyptm = fst(dest_imp c) in
  let ens = snd(dest_imp c) in
  let pre = rand(rator(rator ens)) and post = rand(rator ens) and frame = rand ens in
  let v = `s:x86state` in
  let conj_pred p = mk_abs(v, mk_conj(mk_comb(p,v), mk_comb(DEND_PRED,v))) in
  prove
   (mk_imp(hyptm,
      list_mk_comb(`ensures x86`, [conj_pred pre; conj_pred post; frame])),
    STRIP_TAC THEN MATCH_MP_TAC ENSURES_FRAME_RO THEN CONJ_TAC THENL
     [DEND_PRESERVE_TAC;
      MATCH_MP_TAC lem THEN ASM_REWRITE_TAC[ALL;NONOVERLAPPING_CLAUSES]]);;
(* C_FULL_W: union frame for the wide block — PL_LOOP_D writes bytes(sp,64),      *)
(* TAIL_WIDE writes bytes(statep,32); RSI is in both register frames.             *)
let C_FULL_W =
  `MAYCHANGE [RIP; RDI; RSI; RBP; RAX; RBX; RCX; RDX; R8; R9; R10; R11; R12; R13; R14; R15] ,,
   MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events] ,,
   MAYCHANGE [memory :> bytes(stackpointer, 64)] ,,
   MAYCHANGE [memory :> bytes(statep, 32)]`;;

(* TAIL_WIDE instantiation from the PL_LOOP_D exit state: N/pa/s0 from regs,       *)
(* h := [a;..;h], ri := datap (RSI value PL_LOOP exits with), dend stays dend.     *)
let twv_inst t =
  vsubst [tail_N,`N:int32 list`; tail_pa,`pa:int32`; tail_s0,`s0:int32`;
          tail_h,`h:int32 list`; `datap:int64`,`ri:int64`] t;;

let SHA256_NOHW_FULLBLOCK_WIDE =
  let ae = REWRITE_RULE[SOME_FLAGS] (SPEC_ALL SHA256_NOHW_PL_LOOP_D) in
  let be = REWRITE_RULE[SOME_FLAGS] (SPEC_ALL SHA256_BLOCK_DATA_ORDER_NOHW_TAIL_WIDE) in
  let (pa_,qa_,ca_) = dest_ens_x86 (ens_concl ae) in
  let (pb_,qb_,cb_) = dest_ens_x86 (ens_concl be) in
  let pbi = twv_inst pb_ and qbi = twv_inst qb_ in
  let cfull = rhs(concl(REWRITE_CONV[SOME_FLAGS] C_FULL_W)) in
  let extrahyp = `nonoverlapping (word_add stackpointer (word 64):int64, 32) (statep:int64,32)` in
  let goal = mk_imp(mk_conj(fst(dest_imp(concl ae)), extrahyp),
               list_mk_comb(`ensures x86`, [canon_pred pa_; canon_pred qbi; cfull])) in
  prove
   (goal,
    DISCH_THEN(fun th -> ASSUME_TAC th THEN MP_TAC th) THEN
    REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    ENSURES_SEQUENCE_TAC `pc + 0x1103` (canon_rest qa_) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
      EXISTS_TAC ca_ THEN CONJ_TAC THENL
       [REWRITE_TAC[SOME_FLAGS] THEN SUBSUMED_MAYCHANGE_TAC;
        MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
        MAP_EVERY EXISTS_TAC [pa_; qa_] THEN
        REPEAT CONJ_TAC THENL
         [SHA256_NOHW_SEAM_BRIDGE_TAC; SHA256_NOHW_SEAM_BRIDGE_TAC;
          MATCH_MP_TAC ae THEN ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES]]];
      MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
      EXISTS_TAC cb_ THEN CONJ_TAC THENL
       [REWRITE_TAC[SOME_FLAGS] THEN SUBSUMED_MAYCHANGE_TAC;
        MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
        MAP_EVERY EXISTS_TAC [pbi; qbi] THEN
        REPEAT CONJ_TAC THENL
         [GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
          CONV_TAC(DEPTH_CONV EL_CONV) THEN ASM_REWRITE_TAC[];
          GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
          ASM_REWRITE_TAC[];
          MATCH_MP_TAC be THEN
          REWRITE_TAC[SHA256_COMPRESS_ROUND_LENGTH; LENGTH] THEN
          CONV_TAC NUM_REDUCE_CONV THEN
          ASM_REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN
          REWRITE_TAC[SHA256_ACOMPLETE]]]]);;

(* FULLBLOCK_WIDE_SPEC: fold FULLBLOCK_WIDE's raw add-back register/memory post     *)
(* (word_add (EL k [a..h]) (EL k (compress^64-nest m [a..h]))) to the spec form     *)
(* word_zx (EL k (sha256_block m [a;..;h])), via SHA256_COMPRESS_64_FROM_4 (nest ->  *)
(* sha256_compress m 64) + SHA256_BLOCK_EL.  RSI/CF/[sp+64]/[sp+80] facts unchanged. *)
let SHA256_NOHW_FULLBLOCK_WIDE_SPEC =
  let raw = SHA256_NOHW_FULLBLOCK_WIDE in
  let (rp,rq,rc) = dest_ens_x86 (ens_concl (SPEC_ALL raw)) in
  (* raw_i i = the raw RHS argument word_add (EL i [a..h]) (EL i tail_N) *)
  let raw_i i = mk_comb(mk_comb(`word_add:int32->int32->int32`,
                   vsubst[mk_small_numeral i,`i:num`] `EL i [a;b;c;d;e;f;g;h]:int32`),
                   mk_comb(mk_comb(`EL:num->int32 list->int32`,mk_small_numeral i),tail_N)) in
  let blk i = vsubst[mk_small_numeral i,`i:num`] `EL i (sha256_block m [a;b;c;d;e;f;g;h]):int32` in
  let postsub = map (fun i -> (blk i, raw_i i)) (0--7) in
  let specq = mk_abs(sx_state, subst postsub (fullbeta_tm(mk_comb(rq,sx_state)))) in
  let goal = mk_imp(fst(dest_imp(concl (SPEC_ALL raw))),
               list_mk_comb(`ensures x86`, [rp; specq; rc])) in
  prove
   (goal,
    STRIP_TAC THEN
    MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN EXISTS_TAC rq THEN CONJ_TAC THENL
     [GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN (mk_eq(tail_N, `sha256_compress m 64 [a;b;c;d;e;f;g;h]`))
        SUBST1_TAC THENL
       [REWRITE_TAC[SHA256_COMPRESS_64_FROM_4]; ALL_TAC] THEN
      SIMP_TAC[SHA256_BLOCK_EL; LENGTH; ARITH] THEN
      CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[];
      MATCH_MP_TAC raw THEN ASM_REWRITE_TAC[]]);;
(* FULLBLOCK_WIDE_PUB: promote FULLBLOCK_WIDE_SPEC's precondition to bytelist-only  *)
(* (drop the 48 concrete K[16..63] reads + 3 sentinels, keep the single K256_data   *)
(* bytelist read), recovering them internally via KVALS_16_63 + SENTINEL_BYTES.     *)
(* Exactly CORE's promotion, but the post is the wide block-result form.            *)
let SHA256_NOHW_FULLBLOCK_WIDE_PUB =
  let lem = SHA256_NOHW_FULLBLOCK_WIDE_SPEC in
  let (lp,lq,lc) = dest_ens_x86 (ens_concl (SPEC_ALL lem)) in
  let is_kf t = is_eq t &&
    (can (term_match [] `read (memory :> bytes32 (word_add (word kbytes) (word n))) ss`) (lhs t) ||
     can (term_match [] `read (memory :> bytes8 (word_add (word kbytes) (word n))) ss`) (lhs t)) &&
    (is_comb(rhs t) && (try fst(dest_const(rator(rhs t)))="word" with _ -> false)) in
  let blread = mk_eq(mk_comb(mk_comb(`read:(x86state,byte list)component->x86state->byte list`,
      `memory :> bytelist (word kbytes, LENGTH K256_data)`), sx_state), `K256_data`) in
  let kept = filter (fun t -> not(is_kf t)) (conjuncts(fullbeta_tm(mk_comb(lp,sx_state)))) in
  let pubp = mk_abs(sx_state, list_mk_conj (kept @ [blread])) in
  let goal = mk_imp(fst(dest_imp(concl (SPEC_ALL lem))),
               list_mk_comb(`ensures x86`, [pubp; lq; lc])) in
  prove
   (goal,
    STRIP_TAC THEN MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN EXISTS_TAC lp THEN CONJ_TAC THENL
     [GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
      FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP (SPEC_ALL SHA256_NOHW_KVALS_16_63)) THEN
      FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP (SPEC_ALL SHA256_NOHW_SENTINEL_BYTES)) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC lem THEN ASM_REWRITE_TAC[]]);;

(* ---- Phase 9 loop-wiring helpers ---- *)
(* list-of-8 reconstruction: a length-8 list equals the list of its 8 elements.  *)
(* (used to fold sha256_block over [EL 0 hb;..;EL 7 hb] back to sha256_block hb)  *)
let LIST_OF_8_EL = prove
 (`!l:int32 list. LENGTH l = 8
       ==> [EL 0 l;EL 1 l;EL 2 l;EL 3 l;EL 4 l;EL 5 l;EL 6 l;EL 7 l] = l`,
  GEN_TAC THEN
  REWRITE_TAC[ARITH_RULE `8 = SUC(SUC(SUC(SUC(SUC(SUC(SUC(SUC 0)))))))`;
              LENGTH_EQ_CONS] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[LENGTH_EQ_CONS; LENGTH_EQ_NIL]) THEN
  ASM_REWRITE_TAC[] THEN CONV_TAC(DEPTH_CONV EL_CONV) THEN REWRITE_TAC[]);;
(* val(datap + 64*k) = val datap + 64*k when the whole buffer fits in 2^64.       *)
let VAL_DATAP_ADD = prove
 (`!datap:int64 num_blocks k.
     val datap + 64 * num_blocks < 2 EXP 64 /\ k <= num_blocks
     ==> val (word_add datap (word (64 * k)):int64) = val datap + 64 * k`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[VAL_WORD_ADD; VAL_WORD; DIMINDEX_64] THEN
  SUBGOAL_THEN `(64 * k) MOD 2 EXP 64 = 64 * k` SUBST1_TAC THENL
   [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC; ALL_TAC] THEN
  MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC);;

(* CF after `cmp dend,rsi` with rsi=datap+64*k, dend=datap+64*num_blocks:          *)
(*   val(datap+64*k) < val(datap+64*num_blocks)  <=>  k < num_blocks.              *)
let CF_BLOCK_LT = prove
 (`!datap:int64 num_blocks k.
     val datap + 64 * num_blocks < 2 EXP 64 /\ k <= num_blocks
     ==> (val (word_add datap (word (64 * k)):int64) <
          val (word_add datap (word (64 * num_blocks)):int64)
          <=> k < num_blocks)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `val (word_add datap (word (64 * k)):int64) = val datap + 64 * k /\
                val (word_add datap (word (64 * num_blocks)):int64) = val datap + 64 * num_blocks`
    (CONJUNCTS_THEN SUBST1_TAC) THENL
   [CONJ_TAC THEN MATCH_MP_TAC VAL_DATAP_ADD THEN
    EXISTS_TAC `num_blocks:num` THEN ASM_REWRITE_TAC[LE_REFL];
    ASM_ARITH_TAC]);;

(* ========================================================================= *)
(* PHASE 9: multi-block outer loop -> SHA256_BLOCK_DATA_ORDER_NOHW_CORRECT.    *)
(* Wrap the one-full-block FULLBLOCK_WIDE_PUB in the do-while outer loop via    *)
(* ENSURES_WHILE_PUP_TAC over num_blocks.  Entry tmc 0x31 (the 8 state-load     *)
(* movs run ONCE = the PUP init); loop top tmc 0x4e; back-edge jb at tmc 0x114a *)
(* (-> 0x4e taken when CF set; -> 0x1150 fall-through); exit tmc 0x1150.        *)
(* Registers a..h CARRY between blocks (no per-block reload).  The invariant    *)
(* carries the running hash sha256_hash_blocks i in both RAX..R11 and           *)
(* [statep+4k], the loop bookkeeping ([sp+64]=statep, [sp+80]=data-end), the    *)
(* readonly K256_data bytelist, and the GLOBAL message data-forall over the     *)
(* loop-base datap.  The block frame writes only bytes(statep,32)+              *)
(* bytes(stackpointer,64); both the data-forall (subregion of the buffer,       *)
(* j<16*num_blocks) and the bytelist (nonoverlapping statep/sp) survive via      *)
(* READ_OVER_WRITE_ORTHOGONAL_TAC (the bytelist length reduces through KLEN).   *)
(* ========================================================================= *)


(* ===== Phase 9 BODY infrastructure (session-029) ===== *)
(* The loop-invariant readonly predicate R threaded across the block frame via   *)
(* ENSURES_FRAME_RO: the GLOBAL message data-forall over loop-base datap, AND     *)
(* the K256_data readonly bytelist (FULLBLOCK_WIDE_PUB's post drops the bytelist).  *)

let LOOP_RO_PRED = `\s:x86state.
   (!j. j < 16 * num_blocks
        ==> read (memory :> bytes32 (word_add datap (word (4 * j)))) s =
            word_bytereverse (data j)) /\
   read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data`;;

(* FULLBLOCK_WIDE_PUB instantiated at iteration i (datap-> datap+64i, m, dend,    *)
(* a..h -> EL k (hash_blocks i data [a..h])).                                      *)
let body_subst =
  let hbi = `sha256_hash_blocks i data [a;b;c;d;e;f;g;h]` in
  let elh k = mk_comb(mk_comb(`EL:num->int32 list->int32`,mk_small_numeral k), hbi) in
  [`word_add datap (word (64 * i)):int64`, `datap:int64`;
   `\t:num. data (16 * i + t):int32`, `m:num->int32`;
   `word_add datap (word (64 * num_blocks)):int64`, `dend:int64`;
   elh 0, `a:int32`; elh 1, `b:int32`; elh 2, `c:int32`; elh 3, `d:int32`;
   elh 4, `e:int32`; elh 5, `f:int32`; elh 6, `g:int32`; elh 7, `h:int32`];;
let FULLBLOCK_AT_I = INST body_subst (SPEC_ALL SHA256_NOHW_FULLBLOCK_WIDE_PUB);;


(* LENGTH K256_data = 677 (K256_data is opaque; reduce via the relocs eqn). *)
let KLEN =
  (REWRITE_CONV(filter (fun th -> try lhs(concl th) = `K256_data:byte list` with _ -> false)
                  sha256_block_data_order_nohw_constants_data) THENC LENGTH_CONV)
    `LENGTH K256_data`;;

(* Preservation of LOOP_RO_PRED across the block frame C.  The goal after MATCH_MP *)
(* ENSURES_FRAME_RO is `!s s2. (R s) /\ C s s2 ==> R s2`.  R s is a CONJUNCTION    *)
(* (data-forall /\ bytelist) so we label its two halves immediately (dforall,blist)*)
(* before touching the C s s2 assumption, then derive s2=write..s and discharge    *)
(* each conjunct by read-over-write orthogonality.                                 *)
let LOOP_RO_PRESERVE_TAC =
  RULE_ASSUM_TAC(REWRITE_RULE[ALL;NONOVERLAPPING_CLAUSES]) THEN
  REWRITE_TAC[] THEN REPEAT GEN_TAC THEN
  CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  DISCH_THEN(CONJUNCTS_THEN2
     (CONJUNCTS_THEN2 (LABEL_TAC "dforall") (LABEL_TAC "blist")) MP_TAC) THEN
  REWRITE_TAC[MAYCHANGE; SEQ_ID; SOME_FLAGS] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
  PURE_REWRITE_TAC[ASSIGNS_SEQ] THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
  REWRITE_TAC[ASSIGNS_THM] THEN REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REPEAT(FIRST_X_ASSUM(CONJUNCTS_THEN ASSUME_TAC o check(is_conj o concl))) THEN
  FIRST_X_ASSUM(SUBST1_TAC o SYM o
    check (fun th -> is_eq(concl th) &&
                     (match rand(concl th) with Var(n,_) -> n="s2" | _ -> false))) THEN
  REWRITE_TAC[KLEN] THEN
  CONJ_TAC THENL
   [(* data-forall conjunct *)
    X_GEN_TAC `j:num` THEN DISCH_TAC THEN
    REMOVE_THEN "dforall" (MP_TAC o SPEC `j:num`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    READ_OVER_WRITE_ORTHOGONAL_TAC;
    (* bytelist conjunct *)
    REMOVE_THEN "blist" (MP_TAC o REWRITE_RULE[KLEN]) THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    READ_OVER_WRITE_ORTHOGONAL_TAC];;


(* BODY_FRAMED: FULLBLOCK_AT_I framed with LOOP_RO_PRED via ENSURES_FRAME_RO.    *)
(* Produces: LOOPHYP ==> ensures (FB.pre /\ LOOP_RO) (FB.post /\ LOOP_RO) C.       *)
(* LOOPHYP carries the LOOP-LEVEL hyps (buffer nonoverlaps over loop-base datap,  *)
(* statep<->kbytes) so the preservation can find its orthogonality facts AND the   *)
(* FB.pre subregion hyps (datap+64i,64) can be derived from (datap,64*nb).         *)
let BODY_LOOPHYP = `0 < num_blocks /\
    val datap + 64 * num_blocks < 2 EXP 64 /\
    i < num_blocks /\
    riprel32_within_bounds kbytes (pc + 0x57) /\
    ALL (nonoverlapping (stackpointer:int64, 64))
        [(word pc:int64, 4465); (word kbytes:int64, 677);
         (datap:int64, 64 * num_blocks); (statep:int64, 32)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (word pc:int64, 4465) /\
    nonoverlapping (statep:int64, 32) (word kbytes:int64, 677) /\
    nonoverlapping (word_add stackpointer (word 64):int64, 32) (statep:int64, 32) /\
    nonoverlapping (statep:int64, 32) (datap:int64, 64 * num_blocks)`;;

(* discharge FULLBLOCK_AT_I's instantiated `ALL` nonoverlap hyps from the loop      *)
(* hyps: the per-block window (datap+64i,64) is a subregion of (datap,64*nb).       *)
(* For each window-nonoverlap, MP_TAC the matching big-region nonoverlap (so its    *)
(* metavars are determined), then subregion via NONOVERLAPPING_MODULO_SUBREGIONS.   *)
(* The single remaining goal is the per-block window nonoverlap                    *)
(*   nonoverlapping_modulo (2^64) (val stackpointer,64) (val(window),64)            *)
(* where window = word_add datap (word(64*i)).  MP_TAC the matching big region      *)
(* (val stackpointer,64)(val datap,64*nb) and close via SUBREGIONS (sp unchanged    *)
(* via REFL, window contained in the buffer since i<num_blocks).                    *)
let SUBREGION_FROM_BIG_TAC =
  FIRST_X_ASSUM(fun th ->
     if aconv (concl th)
        `nonoverlapping_modulo (2 EXP 64) (val(stackpointer:int64),64)
            (val(datap:int64),64*num_blocks)`
     then MP_TAC th else NO_TAC) THEN
  MATCH_MP_TAC(ONCE_REWRITE_RULE[IMP_CONJ_ALT] NONOVERLAPPING_MODULO_SUBREGIONS) THEN
  REWRITE_TAC[CONTAINED_MODULO_REFL; LE_REFL] THEN CONTAINED_TAC;;

let BLOCK_NOV_TAC =
  REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ALL; NONOVERLAPPING_CLAUSES]) THEN
  REPEAT(FIRST_X_ASSUM(STRIP_ASSUME_TAC o check(is_conj o concl))) THEN
  REPEAT CONJ_TAC THEN
  TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  SUBREGION_FROM_BIG_TAC;;

let BODY_FRAMED =
  let lem = FULLBLOCK_AT_I in
  let (p,q,c) = dest_ens_x86 (ens_concl lem) in
  let v = `s:x86state` in
  let conj_pred pr = mk_abs(v, mk_conj(mk_comb(pr,v), mk_comb(LOOP_RO_PRED,v))) in
  prove
   (mk_imp(BODY_LOOPHYP, list_mk_comb(`ensures x86`, [conj_pred p; conj_pred q; c])),
    STRIP_TAC THEN MATCH_MP_TAC ENSURES_FRAME_RO THEN CONJ_TAC THENL
     [LOOP_RO_PRESERVE_TAC;
      MATCH_MP_TAC lem THEN BLOCK_NOV_TAC]);;


(* ===== BODY subgoal: p i -> p(i+1) /\ q(i+1), tmc 0x4e (pc+78) -> 0x114a (pc+4426) ===== *)
(* Bridge the loop body to BODY_FRAMED via ENSURES_PREPOSTCONDITION_THM.            *)

(* LENGTH(hash_blocks i data [a..h]) = 8 — for LIST_OF_8_EL fold in the post. *)
let HBI_LEN = prove
 (`!i. LENGTH(sha256_hash_blocks i data [a;b;c;d;e;f;g;h]) = 8`,
  GEN_TAC THEN MATCH_MP_TAC SHA256_HASH_BLOCKS_LENGTH THEN
  REWRITE_TAC[LENGTH] THEN ARITH_TAC);;

(* block-fold: sha256_block (\t.data(16i+t)) [EL 0 hbi;..;EL 7 hbi] = hash_blocks(i+1). *)
let HB_SUC_FOLD = prove
 (`!i. sha256_block (\t. data (16 * i + t))
         [EL 0 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
          EL 1 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
          EL 2 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
          EL 3 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
          EL 4 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
          EL 5 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
          EL 6 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
          EL 7 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])] =
       sha256_hash_blocks (i + 1) data [a;b;c;d;e;f;g;h]`,
  GEN_TAC THEN
  SUBGOAL_THEN
   `[EL 0 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
     EL 1 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
     EL 2 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
     EL 3 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
     EL 4 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
     EL 5 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
     EL 6 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h]);
     EL 7 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])] =
    sha256_hash_blocks i data [a;b;c;d;e;f;g;h]`
   SUBST1_TAC THENL
   [MATCH_MP_TAC LIST_OF_8_EL THEN REWRITE_TAC[HBI_LEN]; ALL_TAC] THEN
  REWRITE_TAC[GSYM ADD1; sha256_hash_blocks]);;

let BODY_TAC =
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC ENSURES_PREPOSTCONDITION_THM THEN
  MAP_EVERY EXISTS_TAC
   [rand(rator(rator(ens_concl(SPEC_ALL BODY_FRAMED))));
    rand(rator(ens_concl(SPEC_ALL BODY_FRAMED)))] THEN
  REPEAT CONJ_TAC THENL
   [(* PRE: body p i ==> FB.pre /\ LOOP_RO *)
    GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
    X_GEN_TAC `t:num` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `word_add (word_add datap (word (64 * i))) (word (4 * t)):int64 =
      word_add datap (word (4 * (16 * i + t)))`
     SUBST1_TAC THENL [CONV_TAC WORD_RULE; ALL_TAC] THEN
    FIRST_ASSUM(MP_TAC o SPEC `16 * i + t:num`) THEN
    ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    (* POST: FB.post /\ LOOP_RO ==> p(i+1) /\ q(i+1) *)
    GEN_TAC THEN CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN STRIP_TAC THEN
    (* normalise the post's window-advanced RSI/CF addresses datap+64i+64 -> datap+64(i+1) *)
    SUBGOAL_THEN
     `word_add (word_add datap (word (64 * i))) (word 64):int64 =
      word_add datap (word (64 * (i + 1)))`
     ASSUME_TAC THENL [CONV_TAC WORD_RULE; ALL_TAC] THEN
    (* CF: val(datap+64(i+1)) < val(datap+64*nb) <=> i+1<num_blocks *)
    MP_TAC(SPECL [`datap:int64`; `num_blocks:num`; `i + 1`] CF_BLOCK_LT) THEN
    ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN DISCH_TAC THEN
    ASM_REWRITE_TAC[HB_SUC_FOLD];
    (* the ensures *)
    MATCH_MP_TAC BODY_FRAMED THEN ASM_REWRITE_TAC[]];;


(* INIT subgoal: entry (tmc 0x31, pc+49) -> loop top (tmc 0x4e, pc+78), establish p 0.
   The 8 state-load movs (eax..r11d from [rdi+0..28]) + jmp. RDI=statep on entry. *)
let INIT_TAC =
  REWRITE_TAC[SUB_0; MULT_CLAUSES; ADD_CLAUSES; WORD_ADD_0] THEN
  ENSURES_INIT_TAC "s0" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--9) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[sha256_hash_blocks] THEN
  CONV_TAC(DEPTH_CONV EL_CONV) THEN
  ASM_REWRITE_TAC[WORD_ZX_TRIVIAL];;


(* ===== BACKEDGE subgoal: jb taken, RIP=pc+4426 (0x114a) -> pc+78 (0x4e), CF true ===== *)
(* The single `jb 0x52` (mc 0x114e). q i gives CF<=>i<num_blocks; body hyp i<num_blocks   *)
(* makes CF true so the branch is taken to the loop top. p i preserved (jb writes no state).*)
(* The state-buffer bytes32 reads normalise word_zx(EL k hbi):int32 = EL k hbi -> close     *)
(* with WORD_ZX_TRIVIAL (word_zx at equal width is identity).                               *)
let EDGE_CLOSE_TAC =
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[WORD_ZX_TRIVIAL; DIMINDEX_32; LE_REFL] THEN
  ASM_REWRITE_TAC[WORD_ZX_TRIVIAL];;

let BACKEDGE_TAC =
  REPEAT STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--1) THEN
  EDGE_CLOSE_TAC;;

(* ===== EXIT subgoal: jb fall-through, RIP=pc+4426 (0x114a) -> pc+4432 (0x1150), CF false ==*)
(* At i=num_blocks, q gives CF<=>num_blocks<num_blocks = F, so jb falls through. The post   *)
(* is the public state-buffer postcondition = hash_blocks num_blocks (already in p).         *)
let EXIT_TAC =
  REWRITE_TAC[LT_REFL] THEN
  REPEAT STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--1) THEN
  EDGE_CLOSE_TAC;;


let sha256nohw_pq = `\i s.
  (read RSP s = stackpointer /\
   read RSI s = word_add datap (word (64 * i)) /\
   read (memory :> bytes64 (word_add stackpointer (word 64))) s = statep /\
   read (memory :> bytes64 (word_add stackpointer (word 80))) s =
        word_add datap (word (64 * num_blocks)) /\
   read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
   read RAX s = word_zx (EL 0 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read RBX s = word_zx (EL 1 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read RCX s = word_zx (EL 2 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read RDX s = word_zx (EL 3 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read R8 s = word_zx (EL 4 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read R9 s = word_zx (EL 5 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read R10 s = word_zx (EL 6 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read R11 s = word_zx (EL 7 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read (memory :> bytes32 statep) s = word_zx (EL 0 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read (memory :> bytes32 (word_add statep (word 4))) s = word_zx (EL 1 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read (memory :> bytes32 (word_add statep (word 8))) s = word_zx (EL 2 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read (memory :> bytes32 (word_add statep (word 12))) s = word_zx (EL 3 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read (memory :> bytes32 (word_add statep (word 16))) s = word_zx (EL 4 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read (memory :> bytes32 (word_add statep (word 20))) s = word_zx (EL 5 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read (memory :> bytes32 (word_add statep (word 24))) s = word_zx (EL 6 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   read (memory :> bytes32 (word_add statep (word 28))) s = word_zx (EL 7 (sha256_hash_blocks i data [a;b;c;d;e;f;g;h])) /\
   (!j. j < 16 * num_blocks
        ==> read (memory :> bytes32 (word_add datap (word (4 * j)))) s =
            word_bytereverse (data j))) /\
  (read CF s <=> i < num_blocks)`;;


let SHA256_BLOCK_DATA_ORDER_NOHW_CORRECT_GOAL = `
   !a b c d e f g h:int32.
   !data:num->int32. !num_blocks:num.
   !kbytes:num. !pc stackpointer:int64. !datap statep:int64.
    0 < num_blocks /\
    val datap + 64 * num_blocks < 2 EXP 64 /\
    riprel32_within_bounds kbytes (pc + 0x57) /\
    ALL (nonoverlapping (stackpointer, 64))
        [(word pc, 4465); (word kbytes, 677); (datap, 64 * num_blocks); (statep, 32)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (word pc:int64, 4465) /\
    nonoverlapping (statep:int64, 32) (word kbytes:int64, 677) /\
    nonoverlapping (word_add stackpointer (word 64):int64, 32) (statep:int64, 32) /\
    nonoverlapping (statep:int64, 32) (datap:int64, 64 * num_blocks)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word (pc + 0x31) /\
              read RDI s = statep /\
              read RSI s = datap /\
              read RSP s = stackpointer /\
              read (memory :> bytes64 (word_add stackpointer (word 64))) s = statep /\
              read (memory :> bytes64 (word_add stackpointer (word 80))) s =
                   word_add datap (word (64 * num_blocks)) /\
              read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
              read (memory :> bytes32 statep) s = word_zx a /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx b /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx c /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx d /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx e /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx f /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx g /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx h /\
              (!j. j < 16 * num_blocks
                   ==> read (memory :> bytes32 (word_add datap (word (4 * j)))) s =
                       word_bytereverse (data j)))
         (\s. read RIP s = word (pc + 0x1150) /\
              read (memory :> bytes32 statep) s = word_zx (EL 0 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx (EL 1 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx (EL 2 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx (EL 3 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx (EL 4 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx (EL 5 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx (EL 6 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx (EL 7 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])))
         (MAYCHANGE [RIP; RDI; RSI; RBP; RAX; RBX; RCX; RDX; R8; R9; R10; R11; R12; R13; R14; R15] ,,
          MAYCHANGE [CF; PF; AF; ZF; SF; OF] ,, MAYCHANGE [events] ,,
          MAYCHANGE [memory :> bytes(stackpointer, 64)] ,,
          MAYCHANGE [memory :> bytes(statep, 32)])`;;


(* The Phase-9 deliverable: multi-block correctness against sha256_hash_blocks.   *)
let SHA256_BLOCK_DATA_ORDER_NOHW_CORRECT = prove
 (SHA256_BLOCK_DATA_ORDER_NOHW_CORRECT_GOAL,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_WHILE_PUP_TAC `num_blocks:num` `pc + 0x4e` `pc + 0x114a` sha256nohw_pq THEN
  CONJ_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL [INIT_TAC; BODY_TAC; BACKEDGE_TAC; EXIT_TAC]);;


(* ========================================================================= *)
(* Phase 10: subroutine wrapper.                                             *)
(*                                                                           *)
(* The core _CORRECT theorem above covers tmc pc+0x31 -> pc+0x1150 (the      *)
(* state-load through the final state-store), taking the *in-frame* (already *)
(* 64-byte-aligned) stack pointer as its abstract `stackpointer`.  Here we   *)
(* wrap it with the ABI prologue/epilogue to obtain the entry-to-return      *)
(* subroutine theorem.                                                       *)
(*                                                                           *)
(* The prologue (mc 0x4..0x34, i.e. tmc 0x0..0x30) is:                       *)
(*   mov %rsp,%rax ; push rbx/rbp/r12/r13/r14/r15 ; shl $4,%rdx ;            *)
(*   sub $0x60,%rsp ; lea (%rsi,%rdx,4),%rdx ; and $-64,%rsp ;               *)
(*   mov %rdi/%rsi/%rdx/%rax -> [rsp+0x40/0x48/0x50/0x58]                     *)
(* so the in-frame RSP is (entry_rsp - 144) AND ~63 -- NOT a fixed offset    *)
(* from entry_rsp.  We therefore hand-assemble the wrapper (the canned       *)
(* X86_*_RETURN_STACK_TAC assume a fixed sub-rsp frame), mirroring the       *)
(* dynamic-alignment delta+BITBLAST recipe in sha3_keccak4_f1600.ml and the  *)
(* 6-callee-save ENSURES_PRESERVED_TAC pattern in bignum_emontredc_8n.ml.    *)
(* mc/tmc are relocs functions of (pc,kbytes); the IBT lift uses             *)
(* ADD_IBT_RULE ~bridge per curve25519_x25519base.ml.                        *)
(* ------------------------------------------------------------------------- *)

(* mc pc kbytes = APPEND [ENDBR64] (tmc (pc+4) kbytes): relates the trimmed   *)
(* core code (used everywhere above) to the full machine code with the       *)
(* leading 4-byte CET landing pad, for the ADD_IBT_RULE lift below.          *)
let SHA256_BLOCK_DATA_ORDER_NOHW_MC_BRIDGE = prove
 (`!pc kbytes.
     sha256_block_data_order_nohw_mc pc kbytes =
     APPEND [word 0xf3:byte; word 0x0f; word 0x1e; word 0xfa]
            (sha256_block_data_order_nohw_tmc (pc + 4) kbytes)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[sha256_block_data_order_nohw_mc;
              sha256_block_data_order_nohw_tmc; APPEND] THEN
  REWRITE_TAC[GSYM INT_OF_NUM_ADD] THEN
  AP_TERM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[INT_ARITH `&pc + &91 = (&pc + &4) + &87:int`]);;

(* ------------------------------------------------------------------------- *)
(* Sub-lemma (2): NOIBT subroutine wrapper over the trimmed mc.              *)
(*                                                                           *)
(* Hand-assembled (the canned X86_*_RETURN_STACK_TAC assume a fixed sub-rsp  *)
(* frame, but the `andq $-64,%rsp` makes the in-frame RSP                     *)
(* (entry_rsp - 144) AND ~63 -- NOT a fixed offset).  We mirror the dynamic- *)
(* alignment delta+BITBLAST recipe of sha3_keccak4_f1600.ml and the          *)
(* 6-callee-save ENSURES_PRESERVED_TAC pattern of bignum_emontredc_8n.ml.    *)
(*                                                                           *)
(* Frame layout (entry RSP = stackpointer + 208 after WORD_FORALL_OFFSET):    *)
(*   push rbx/rbp/r12/r13/r14/r15  -> saved at [sp+160..200]                  *)
(*   sub $0x60 ; and $-64          -> in-frame RSP = sp+delta, delta<=64      *)
(*   bookkeeping: [sp+delta+64]=rdi(statep), [sp+delta+72]=rsi(datap),        *)
(*               [sp+delta+80]=rdx(data-end), [sp+delta+88]=rax(entry RSP)    *)
(*   return address at [sp+208] (= entry RSP).                               *)
(*                                                                           *)
(* The core's MAYCHANGE frame is bytes(sp+delta,64) (the aligned 64-byte     *)
(* schedule window) plus bytes(statep,32); both are provably disjoint from   *)
(* the return-address slot [sp+208,+8) given delta<=64, so the RA read        *)
(* SURVIVES the core bigstep automatically (no ENSURES_FRAME_RO needed --     *)
(* session-030's RA-drop worry was overcautious, like session-028's BODY     *)
(* "blocker").  X86_BIGSTEP_TAC's MAYCHANGE_STATE_UPDATE_TAC discharges the   *)
(* disjointness from delta<=64 in context.                                   *)
(* ------------------------------------------------------------------------- *)

let SHA256_BLOCK_DATA_ORDER_NOHW_NOIBT_SUBROUTINE_CORRECT = prove
 (`!a b c d e f g h:int32.
   !data:num->int32. !num_blocks:num.
   !kbytes:num. !pc:num. !stackpointer:int64. !returnaddress:int64.
   !datap statep:int64.
    0 < num_blocks /\
    val datap + 64 * num_blocks < 2 EXP 64 /\
    riprel32_within_bounds kbytes (pc + 0x57) /\
    ALL (nonoverlapping (word_sub stackpointer (word 208), 208))
        [(word pc, 4465); (word kbytes, 677); (datap, 64 * num_blocks)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (word pc:int64, 4465) /\
    nonoverlapping (statep:int64, 32) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (datap:int64, 64 * num_blocks) /\
    nonoverlapping (word_sub stackpointer (word 208):int64, 216) (statep:int64, 32)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word pc /\
              read RSP s = stackpointer /\
              read (memory :> bytes64 stackpointer) s = returnaddress /\
              C_ARGUMENTS [statep; datap; word num_blocks] s /\
              read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
              read (memory :> bytes32 statep) s = word_zx a /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx b /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx c /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx d /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx e /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx f /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx g /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx h /\
              (!j. j < 16 * num_blocks
                   ==> read (memory :> bytes32 (word_add datap (word (4 * j)))) s =
                       word_bytereverse (data j)))
         (\s. read RIP s = returnaddress /\
              read RSP s = word_add stackpointer (word 8) /\
              read (memory :> bytes32 statep) s = word_zx (EL 0 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx (EL 1 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx (EL 2 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx (EL 3 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx (EL 4 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx (EL 5 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx (EL 6 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx (EL 7 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])))
         (MAYCHANGE [RSP] ,, MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI ,,
          MAYCHANGE [memory :> bytes(statep, 32);
                     memory :> bytes(word_sub stackpointer (word 208), 208)])`,
  (* offset stackpointer so the spill base rebases to `stackpointer`        *)
  (* (entry RSP becomes stackpointer + 208).                                *)
  REPLICATE_TAC 12 GEN_TAC THEN WORD_FORALL_OFFSET_TAC 208 THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI; C_ARGUMENTS; SOME_FLAGS;
              fst SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC] THEN
  REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN
  (* KLEN-rewrite BEFORE stepping: makes the bytelist read concrete-length    *)
  (* so X86_STEPS_TAC preserves it across the prologue.                       *)
  REWRITE_TAC[KLEN] THEN
  REPEAT STRIP_TAC THEN
  MAP_EVERY (fun c -> ENSURES_PRESERVED_TAC ("init_"^fst(dest_const c)) c)
            (dest_list `[RBX; RBP; R12; R13; R14; R15]`) THEN
  REWRITE_TAC(!simulation_precanon_thms) THEN
  ENSURES_INIT_TAC "s0" THEN
  (* prologue: 11 instrs through the `and $-64,%rsp` *)
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--11) THEN
  ABBREV_TAC
   `delta = val(word_sub (word_and (word_add stackpointer (word 64))
                                   (word 18446744073709551552)) stackpointer:int64)` THEN
  SUBGOAL_THEN `delta <= 64` ASSUME_TAC THENL
   [EXPAND_TAC "delta" THEN CONV_TAC BITBLAST_RULE; ALL_TAC] THEN
  SUBGOAL_THEN
   `word_and (word_add stackpointer (word 64)) (word 18446744073709551552):int64 =
    word_add stackpointer (word delta)`
  SUBST_ALL_TAC THENL
   [EXPAND_TAC "delta" THEN CONV_TAC BITBLAST_RULE; ALL_TAC] THEN
  (* prologue: 4 bookkeeping stores at [sp+delta+64/72/80/88] *)
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (12--15) THEN
  (* normalize the data-end value (rdx = datap + 4*(num_blocks<<4)) *)
  SUBGOAL_THEN `val(word_shl (word num_blocks) 4 :int64) = 16 * num_blocks`
   ASSUME_TAC THENL
   [REWRITE_TAC[VAL_WORD_SHL; VAL_WORD; DIMINDEX_64] THEN
    SUBGOAL_THEN `num_blocks MOD 2 EXP 64 = num_blocks` SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(2 EXP 4 * num_blocks) MOD 2 EXP 64 = 2 EXP 4 * num_blocks`
     SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC; ARITH_TAC]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(word_shl (word num_blocks) 4 :int64) = 16 * num_blocks`]) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ARITH_RULE `4 * 16 * num_blocks = 64 * num_blocks`]) THEN
  (* apply the committed core at the in-frame RSP = stackpointer+delta *)
  MP_TAC(SPECL
   [`a:int32`; `b:int32`; `c:int32`; `d:int32`; `e:int32`; `f:int32`; `g:int32`; `h:int32`;
    `data:num->int32`; `num_blocks:num`; `kbytes:num`; `pc:num`;
    `word_add stackpointer (word delta):int64`; `datap:int64`; `statep:int64`]
   SHA256_BLOCK_DATA_ORDER_NOHW_CORRECT) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN NONOVERLAPPING_TAC; ALL_TAC] THEN
  (* core bigstep; subgoal 1 = the precondition match at s15 (state, K, dend). *)
  X86_BIGSTEP_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC "s16" THENL
   [REWRITE_TAC[WORD_RULE
      `word_add (word_add q (word d)) (word n):int64 = word_add q (word (d + n))`;
     KLEN] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* epilogue: 9 instrs (mov rsi,[sp+delta+88]; 6 restores; lea rsp,[rsi]; ret) *)
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (17--25) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[WORD_ZX_TRIVIAL]);;

(* ------------------------------------------------------------------------- *)
(* Sub-lemma (3): the full subroutine theorem over the un-trimmed mc (with    *)
(* the leading ENDBR64 / CET landing pad).  Lifted from the NOIBT theorem by  *)
(* ADD_IBT_RULE + the MC_BRIDGE equation (curve25519_x25519base.ml pattern).  *)
(* ADD_IBT_RULE bumps every `pc + n` and `(word pc, n)` by 4: pc+0x57->pc+0x5b *)
(* and codesize 4465->4469; K256_data/677/64*num_blocks/statep are unchanged.  *)
(*                                                                           *)
(* NOTE on `0 < num_blocks`: the C signature                                  *)
(*   void sha256_block_data_order_nohw(uint32_t state[8],                      *)
(*                                      const uint8_t *data, size_t num_blocks)*)
(* permits num_blocks = 0, but the assembly is a DO-WHILE loop (it always      *)
(* processes at least one 64-byte block before testing the back-edge), so the  *)
(* theorem is only meaningful -- and only provable -- for num_blocks >= 1.     *)
(* This precondition is carried visibly and FLAGGED for human review.          *)
(* ------------------------------------------------------------------------- *)

let SHA256_BLOCK_DATA_ORDER_NOHW_SUBROUTINE_CORRECT = prove
 (`!a b c d e f g h:int32.
   !data:num->int32. !num_blocks:num.
   !kbytes:num. !pc:num. !stackpointer:int64. !returnaddress:int64.
   !datap statep:int64.
    0 < num_blocks /\
    val datap + 64 * num_blocks < 2 EXP 64 /\
    riprel32_within_bounds kbytes (pc + 0x5b) /\
    ALL (nonoverlapping (word_sub stackpointer (word 208), 208))
        [(word pc, 4469); (word kbytes, 677); (datap, 64 * num_blocks)] /\
    nonoverlapping (word pc:int64, 4469) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (word pc:int64, 4469) /\
    nonoverlapping (statep:int64, 32) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (datap:int64, 64 * num_blocks) /\
    nonoverlapping (word_sub stackpointer (word 208):int64, 216) (statep:int64, 32)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_mc pc kbytes) /\
              read RIP s = word pc /\
              read RSP s = stackpointer /\
              read (memory :> bytes64 stackpointer) s = returnaddress /\
              C_ARGUMENTS [statep; datap; word num_blocks] s /\
              read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
              read (memory :> bytes32 statep) s = word_zx a /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx b /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx c /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx d /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx e /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx f /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx g /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx h /\
              (!j. j < 16 * num_blocks
                   ==> read (memory :> bytes32 (word_add datap (word (4 * j)))) s =
                       word_bytereverse (data j)))
         (\s. read RIP s = returnaddress /\
              read RSP s = word_add stackpointer (word 8) /\
              read (memory :> bytes32 statep) s = word_zx (EL 0 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx (EL 1 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx (EL 2 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx (EL 3 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx (EL 4 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx (EL 5 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx (EL 6 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])) /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx (EL 7 (sha256_hash_blocks num_blocks data [a;b;c;d;e;f;g;h])))
         (MAYCHANGE [RSP] ,, MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI ,,
          MAYCHANGE [memory :> bytes(statep, 32);
                     memory :> bytes(word_sub stackpointer (word 208), 208)])`,
  MATCH_ACCEPT_TAC(ADD_IBT_RULE ~bridge:(Some SHA256_BLOCK_DATA_ORDER_NOHW_MC_BRIDGE)
                    SHA256_BLOCK_DATA_ORDER_NOHW_NOIBT_SUBROUTINE_CORRECT));;

(* ========================================================================= *)
(* PHASE 11: constant-time + memory-safety side spec.                         *)
(* The functional theorems above say the OUTPUT is correct; the safety side    *)
(* spec says the function touches only memory it is allowed to and its memory-  *)
(* event TRACE depends only on PUBLIC inputs (no secret-dependent addresses /   *)
(* branches => constant-time).                                                  *)
(*                                                                              *)
(* SHA256_NOHW_FULLBLOCK_SAFE is the factored, standalone, committable one-      *)
(* block safety lemma (advisor-ratified session-039): entry tmc 0x4e ->         *)
(* exit 0x114a, fresh events e0, the PERMISSIVE frame (= FULLBLOCK_WIDE_PUB's,   *)
(* already includes MAYCHANGE[events] + callee-saves).  Its conclusion is an     *)
(*   ?f_ev_block. !e0 a..h m datap statep dend pc kbytes stackpointer. ...        *)
(* with f_ev_block (the trace function) EXISTS-quantified OUTSIDE the secret      *)
(* variables a..h, m and the incoming trace e0 -- that quantifier order IS the    *)
(* constant-time guarantee: the produced event trace cannot depend on secrets.    *)
(* The post records `e2 = f_ev_block <public args> /\ memaccess_inbounds e2       *)
(* [readable] [writable]`, i.e. every load/store address lies in a public,        *)
(* bounds-checked region.  Mirrors bignum_inv_p25519's CORE_INV_P25519_SAFE        *)
(* callee-lemma shape; it is INST'd into the multi-block CORE_SAFE while-body      *)
(* (next sub-step) exactly as the functional FULLBLOCK_WIDE_PUB is INST'd into     *)
(* the _CORRECT loop body.                                                         *)
(*                                                                              *)
(* The goal term is built programmatically from the proven functional            *)
(* SHA256_NOHW_FULLBLOCK_WIDE_PUB (reuse its hyps / pre / permissive frame).      *)
(* The proof is straight-line inline single-stepping of the whole ~2800-instr     *)
(* body (the inner rounds_16_xx loop unrolled 3x; events discard the SHA working  *)
(* state so the proof is non-exploding -- ~29 hyps / ~96 events at the iter-0      *)
(* back-edge).  Two essential mechanics:                                          *)
(*   (1) fold RBP via RIP_REL_ADDR_FOLD right after the prologue                  *)
(*       `lea K256(%rip),%rbp` so RBP = word kbytes; this keeps every K-table      *)
(*       event address (and the loop-termination cmpb byte read) in the clean      *)
(*       `word_add (word kbytes) (word N)` form -- so the sentinel byte matches     *)
(*       and memaccess_inbounds recognises the K range.                            *)
(*   (2) at each inner back-edge, X86_BYTECMP_STEP_TAC reduces the 8-bit           *)
(*       `cmpb $0,3(%rbp)` to a concrete ZF (RBP is clean), then FB_REDUCE_ZF_TAC  *)
(*       collapses ONLY that ZF hypothesis (NOT a blanket RULE_ASSUM_TAC, which     *)
(*       would rewrite `val(word pc)` -> `pc` in the nonoverlapping_modulo hyps     *)
(*       and break the next iteration's W-store NONSELFMODIFYING check), and the    *)
(*       jne resolves (iters 0,1 sentinel K[259]=39/K[387]=25 <>0 -> taken to       *)
(*       0x6e6; iter 2 K[515]=0 -> fall-through to 0x1103).  The 3 sentinel bytes   *)
(*       are derived at s0 from the K256_data bytelist (they survive stepping; the  *)
(*       LENGTH-677 bytelist does not).                                            *)
(* ========================================================================= *)

needs "x86/proofs/consttime.ml";;
needs "x86/proofs/subroutine_signatures.ml";;

let sha_fullblock_safe_goal =
  let gl = concl (SPEC_ALL SHA256_NOHW_FULLBLOCK_WIDE_PUB) in
  let asms, ens = dest_imp gl in
  let op, args = strip_comb ens in
  let arch = el 0 args and pre = el 1 args
  and frame = el 3 args in
  let sv, prebody = dest_gabs pre in
  let e0 = `e0:(uarch_event)list` in
  let evread = vsubst [sv,`s:x86state`] `read events s = e0` in
  let pre' = mk_gabs (sv, list_mk_conj (conjuncts prebody @ [evread])) in
  let postbody =
    `read RIP s = word (pc + 0x114a) /\
     read RSP s = stackpointer /\
     read RSI s = word_add datap (word 64) /\
     read (memory :> bytes64 (word_add stackpointer (word 64))) s = statep /\
     read (memory :> bytes64 (word_add stackpointer (word 80))) s = dend /\
     (read CF s <=> val (word_add datap (word 64)) < val dend) /\
     (?e2. read events s = APPEND e2 e0 /\
           e2 = f_ev_block datap statep dend pc kbytes stackpointer /\
           memaccess_inbounds e2
             [statep,32; datap,64; stackpointer,96; word kbytes:int64,677]
             [statep,32; stackpointer,64])` in
  let postbody = vsubst [sv,`s:x86state`] postbody in
  let post' = mk_gabs (sv, postbody) in
  let f_ev = find_term (fun t -> is_var t && fst(dest_var t) = "f_ev_block") postbody in
  let ens' = list_mk_comb (op, [arch; pre'; post'; frame]) in
  let quants =
   [e0; `a:int32`;`b:int32`;`c:int32`;`d:int32`;`e:int32`;`f:int32`;`g:int32`;`h:int32`;
    `m:num->int32`; `datap:int64`; `statep:int64`; `dend:int64`;
    `pc:num`; `kbytes:num`; `stackpointer:int64`] in
  mk_exists (f_ev, list_mk_forall (quants, mk_imp (asms, ens')));;

(* <=100-step batched stepping over [lo,hi]. *)
let FB_STEP_RANGE lo hi =
  let rec batches a = if a > hi then []
    else let b = min hi (a+99) in (a,b)::batches (b+1) in
  EVERY (map (fun (a,b) -> X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (a--b))
             (batches lo));;

(* reduce ONLY the freshly-emitted ZF hyp `read ZF sN <=> val(word_sub .. ..) = 0` *)
(* to concrete; matched by the word_sub/ZF pattern so the nonoverlapping_modulo     *)
(* hyps are never touched.                                                          *)
let FB_REDUCE_ZF_TAC =
  FIRST_X_ASSUM(fun th ->
    let c = concl th in
    if is_iff c && can (find_term (fun t -> is_comb t && is_const(rator t) &&
                                            fst(dest_const(rator t)) = "word_sub")) c &&
       (match lhs c with Comb(Comb(Const("read",_),Const("ZF",_)),_) -> true | _ -> false)
    then ASSUME_TAC(CONV_RULE(RAND_CONV(WORD_REDUCE_CONV THENC NUM_REDUCE_CONV)) th)
    else failwith "not-zf");;

(* full back-edge: BYTECMP the cmpb at cmpb_state, reduce ZF, step the jne. *)
let FB_BACKEDGE cmpb_state jne_idx =
  X86_BYTECMP_STEP_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC cmpb_state THEN
  FB_REDUCE_ZF_TAC THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (jne_idx--jne_idx);;

let SHA256_NOHW_FULLBLOCK_SAFE = prove
 (sha_fullblock_safe_goal,
  META_EXISTS_TAC THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP (SPEC_ALL SHA256_NOHW_SENTINEL_BYTES)) THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--2) THEN
  FIRST_X_ASSUM (fun th -> MP_TAC th THEN IMP_REWRITE_TAC[RIP_REL_ADDR_FOLD] THEN DISCH_TAC) THEN
  FB_STEP_RANGE 3 515 THEN
  FB_STEP_RANGE 516 1267 THEN
  FB_BACKEDGE "s1268" 1269 THEN
  FB_STEP_RANGE 1270 2021 THEN
  FB_BACKEDGE "s2022" 2023 THEN
  FB_STEP_RANGE 2024 2775 THEN
  FB_BACKEDGE "s2776" 2777 THEN
  FB_STEP_RANGE 2778 2797 THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  DISCHARGE_SAFETY_PROPERTY_TAC);;

(* ========================================================================= *)
(* FULLBLOCK_SAFE_CT: the CONTENT-AGNOSTIC one-block CT/safety lemma.          *)
(* Identical to SHA256_NOHW_FULLBLOCK_SAFE above EXCEPT its precondition       *)
(* DROPS the 8 register state-word pins (read RAX..R11 = word_zx a..h) and     *)
(* the 8 memory state-word pins (read bytes32 statep+4k = word_zx a..h).       *)
(* The event trace and every memory-access ADDRESS produced by the block are   *)
(* independent of those secret values (that independence IS the constant-time  *)
(* guarantee), so the proof is the identical inline single-stepping tactic.    *)
(*                                                                             *)
(* WHY: the multi-block CORE_SAFE loop composes one of these per block.  A     *)
(* safety lemma whose pre PINS the secret running hash would force the loop     *)
(* invariant to carry that hash AND its post to re-establish it -- but a CT     *)
(* lemma's minimal post (RIP/RSP/RSI/[sp+64]/[sp+80]/CF + events) cannot.  The  *)
(* content-agnostic shape matches the canonical safety precedent               *)
(* bignum_inv_p25519.ml:4242 (LOCAL_WORD_DIVSTEP59_SAFE), whose pre is          *)
(* bytes_loaded/RIP/RSP/read-events only and whose CORE loop invariant carries  *)
(* no secret state.  SHA256_NOHW_FULLBLOCK_SAFE (above) is superseded by this   *)
(* for the loop and may be removed once CORE_SAFE lands.                        *)
(* ========================================================================= *)

let is_state_pin t =
  is_eq t &&
  (let l = lhs t in
   ((try let r = rand(rator l) in is_const r &&
      mem (fst(dest_const r)) ["RAX";"RBX";"RCX";"RDX";"R8";"R9";"R10";"R11"]
     with _ -> false) ||
   (can (term_match [] `read (memory :> bytes32 statep) ss`) l) ||
   (can (term_match [] `read (memory :> bytes32 (word_add statep (word n))) ss`) l)));;

let sha_fullblock_safe_ct_goal =
  let gl = concl (SPEC_ALL SHA256_NOHW_FULLBLOCK_WIDE_PUB) in
  let asms, ens = dest_imp gl in
  let op, args = strip_comb ens in
  let arch = el 0 args and pre = el 1 args and frame = el 3 args in
  let sv, prebody = dest_gabs pre in
  let kept = filter (fun t -> not (is_state_pin t)) (conjuncts prebody) in
  let e0 = `e0:(uarch_event)list` in
  let evread = vsubst [sv,`s:x86state`] `read events s = e0` in
  let pre' = mk_gabs (sv, list_mk_conj (kept @ [evread])) in
  let postbody =
    `read RIP s = word (pc + 0x114a) /\
     read RSP s = stackpointer /\
     read RSI s = word_add datap (word 64) /\
     read (memory :> bytes64 (word_add stackpointer (word 64))) s = statep /\
     read (memory :> bytes64 (word_add stackpointer (word 80))) s = dend /\
     (read CF s <=> val (word_add datap (word 64)) < val dend) /\
     (?e2. read events s = APPEND e2 e0 /\
           e2 = f_ev_block datap statep dend pc kbytes stackpointer /\
           memaccess_inbounds e2
             [statep,32; datap,64; stackpointer,96; word kbytes:int64,677]
             [statep,32; stackpointer,64])` in
  let postbody = vsubst [sv,`s:x86state`] postbody in
  let post' = mk_gabs (sv, postbody) in
  let f_ev = find_term (fun t -> is_var t && fst(dest_var t) = "f_ev_block") postbody in
  let ens' = list_mk_comb (op, [arch; pre'; post'; frame]) in
  let body = mk_imp (asms, ens') in
  let quants = e0 :: subtract (frees body) [e0; f_ev] in
  mk_exists (f_ev, list_mk_forall (quants, body));;

let SHA256_NOHW_FULLBLOCK_SAFE_CT = prove
 (sha_fullblock_safe_ct_goal,
  META_EXISTS_TAC THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  REWRITE_TAC[SOME_FLAGS] THEN ENSURES_INIT_TAC "s0" THEN
  FIRST_ASSUM(STRIP_ASSUME_TAC o MATCH_MP (SPEC_ALL SHA256_NOHW_SENTINEL_BYTES)) THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--2) THEN
  FIRST_X_ASSUM (fun th -> MP_TAC th THEN IMP_REWRITE_TAC[RIP_REL_ADDR_FOLD] THEN DISCH_TAC) THEN
  FB_STEP_RANGE 3 515 THEN
  FB_STEP_RANGE 516 1267 THEN
  FB_BACKEDGE "s1268" 1269 THEN
  FB_STEP_RANGE 1270 2021 THEN
  FB_BACKEDGE "s2022" 2023 THEN
  FB_STEP_RANGE 2024 2775 THEN
  FB_BACKEDGE "s2776" 2777 THEN
  FB_STEP_RANGE 2778 2797 THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  DISCHARGE_SAFETY_PROPERTY_TAC);;

(* ========================================================================= *)
(* PHASE 11 CORE_SAFE: the multi-block CT/memory-safety core lemma.            *)
(* Entry tmc 0x31 -> exit 0x1150.  Hand-built term = _CORRECT's precond        *)
(* verbatim + `read events s = e0`; post = RIP=word(pc+0x1150) + the safety     *)
(* property `?e2. read events s = APPEND e2 e0 /\ e2 = f_events <PUBLIC args>   *)
(*  /\ memaccess_inbounds e2 [reads][writes]` -- the event TRACE depends ONLY    *)
(* on public inputs (datap,statep,num_blocks,kbytes,pc,stackpointer), NOT on    *)
(* the secret message data j or running hash a..h => constant-time + in-bounds. *)
(* Frame = _CORRECT's PERMISSIVE frame (callee-saves allowed) ,, events.        *)
(* Proved by CONCRETIZE_F_EVENTS_TAC (3-part epil/loop/prol trace) +            *)
(* ENSURES_EVENTS_WHILE_UP2_TAC over num_blocks; BODY composes the committed     *)
(* content-agnostic FULLBLOCK_SAFE_CT per block (BODY_SAFE_FRAMED = FRAME_RO     *)
(* with LOOP_RO_PRED).  EXIT is a 0-step ensures (RIP already at pc2, events     *)
(* come from the loop invariant not stepping) -> ENSURES_ALREADY discharge.     *)
(* Mirrors curve25519 CORE_INV_P25519_SAFE composition (bignum_inv_p25519.ml).  *)
(* ========================================================================= *)

(* ---- goal + invariant ---- *)
let sha_core_safe_goal =
  let gl = SHA256_BLOCK_DATA_ORDER_NOHW_CORRECT_GOAL in
  let quants, imp = strip_forall gl in
  let asms, ens = dest_imp imp in
  let op, args = strip_comb ens in
  let arch = el 0 args and pre = el 1 args and frame = el 3 args in
  let sv, prebody = dest_gabs pre in
  let e = `e0:(uarch_event)list` in
  let evread = vsubst [sv,`s:x86state`] `read events s = e0` in
  let pre' = mk_gabs (sv, list_mk_conj (conjuncts prebody @ [evread])) in
  let postbody =
    `read RIP s = word (pc + 0x1150) /\
     (?e2. read events s = APPEND e2 e0 /\
           e2 = f_events datap statep num_blocks kbytes pc stackpointer /\
           memaccess_inbounds e2
             [statep,32; datap, 64 * num_blocks;
              stackpointer,96; word kbytes:int64,677]
             [statep,32; stackpointer,64])` in
  let postbody = vsubst [sv,`s:x86state`] postbody in
  let post' = mk_gabs (sv, postbody) in
  let f_ev = find_term (fun t -> is_var t && fst(dest_var t) = "f_events") postbody in
  let ens' = list_mk_comb (op, [arch; pre'; post'; frame]) in
  mk_exists (f_ev, list_mk_forall (e::quants, mk_imp (asms, ens')));;

let core_safe_inv = `\i s.
   read RSP s = stackpointer /\
   read RSI s = word_add datap (word (64 * i)) /\
   read (memory :> bytes64 (word_add stackpointer (word 64))) s = statep /\
   read (memory :> bytes64 (word_add stackpointer (word 80))) s =
        word_add datap (word (64 * num_blocks)) /\
   read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
   (!j. j < 16 * num_blocks
        ==> read (memory :> bytes32 (word_add datap (word (4 * j)))) s =
            word_bytereverse (data j))`;;

(* ---- BODY_SAFE_FRAMED (FULLBLOCK_SAFE_CT @ i framed with LOOP_RO) ---- *)
let SAFE_FB_SEL = SELECT_RULE SHA256_NOHW_FULLBLOCK_SAFE_CT;;
let SAFE_FB_AT_I =
  INST [`word_add datap (word (64 * i)):int64`, `datap:int64`;
        `\t:num. data (16 * i + t):int32`, `m:num->int32`;
        `word_add datap (word (64 * num_blocks)):int64`, `dend:int64`]
       (SPEC_ALL SAFE_FB_SEL);;
let BODY_SAFE_FRAMED =
  let lem = SAFE_FB_AT_I in
  let (p,q,c) = dest_ens_x86 (ens_concl lem) in
  let v = `s:x86state` in
  let conj_pred pr = mk_abs(v, mk_conj(mk_comb(pr,v), mk_comb(LOOP_RO_PRED,v))) in
  prove
   (mk_imp(BODY_LOOPHYP, list_mk_comb(`ensures x86`, [conj_pred p; conj_pred q; c])),
    STRIP_TAC THEN MATCH_MP_TAC ENSURES_FRAME_RO THEN CONJ_TAC THENL
     [LOOP_RO_PRESERVE_TAC;
      MATCH_MP_TAC lem THEN BLOCK_NOV_TAC]);;

(* PRE-window helper: align block i's data-forall window. *)
let FB_PRE_WINDOW_TAC =
  X_GEN_TAC `t:num` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `word_add (word_add datap (word (64 * i))) (word (4 * t)):int64 =
    word_add datap (word (4 * (16 * i + t)))` SUBST1_TAC THENL
   [CONV_TAC WORD_RULE; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `16 * i + t:num`) THEN
  ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]);;

(* memaccess closer (BODY): normalize goal AND e2/e2' def-eqn asms with APPEND_NIL *)
(* so the GSYM-fold binds; split via MEMACCESS_INBOUNDS_APPEND; per-leaf close.     *)
let FB_MEMACCESS_WIDEN_TAC =
  REWRITE_TAC[APPEND_NIL] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[APPEND_NIL]) THEN
  W (fun (asl,w) ->
    let edefs = mapfilter (fun (_,th) ->
        let c = concl th in
        if is_eq c && is_var (lhs c) && not (is_var (rhs c))
           && mem (fst(dest_var(lhs c))) ["e2";"e2'"]
        then th else fail()) asl in
    PURE_REWRITE_TAC (map GSYM edefs)) THEN
  REWRITE_TAC[MEMACCESS_INBOUNDS_APPEND] THEN
  REPEAT CONJ_TAC THEN
  ((FIRST_ASSUM ACCEPT_TAC)
   ORELSE
   (DISCHARGE_CONCRETE_MEMACCESS_INBOUNDS_TAC THEN NO_TAC)
   ORELSE
   (FIRST_X_ASSUM (fun th ->
       if (try name_of(fst(strip_comb(concl th)))="memaccess_inbounds" with _->false)
       then MP_TAC th else NO_TAC) THEN
    MATCH_MP_TAC MEMACCESS_INBOUNDS_CONTAINED THEN
    DISCHARGE_CONCRETE_MEMACCESS_INBOUNDS_TAC THEN NO_TAC));;

(* manual events-eq (BODY): advance the ENUMERATEL accumulator by one block. *)
let FB_EVENTSEQ_TAC =
  FIRST_ASSUM(fun th ->
    if can (term_match [] `e2 = APPEND a b`) (concl th)
    then SUBST1_TAC th else NO_TAC) THEN
  PURE_REWRITE_TAC[APPEND_NIL; CONJUNCT1 APPEND] THEN
  REWRITE_TAC[APPEND_ASSOC] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN
  REWRITE_TAC[ENUMERATEL_ADD1] THEN
  AP_THM_TAC THEN AP_TERM_TAC THEN
  UNIFY_F_EVENTS_TAC;;

(* discard the e2/e2'/read-events EQUATION assumptions before MONOTONE_MAYCHANGE  *)
(* (their @f_ev_block SELECT body is maychange_term-TRUE -> FIRST_ASSUM grabs the  *)
(* wrong asm -> MATCH_MP pth RAND_CONV crash).                                     *)
let FB_DISCARD_EVENT_EQNS_TAC =
  REPEAT(FIRST_X_ASSUM(fun th ->
    let c = concl th in
    if is_eq c &&
       ((try let n = fst(dest_var(lhs c)) in n="e2" || n="e2'" with _ -> false) ||
        (match lhs c with Comb(Comb(Const("read",_),Const("events",_)),_) -> true
                        | _ -> false))
    then ALL_TAC else NO_TAC));;

(* BODY: compose the framed one-block FULLBLOCK_SAFE_CT, advance events + memaccess. *)
let CORE_SAFE_BODY_TAC =
  X_GEN_TAC `i:num` THEN STRIP_TAC THEN
  ENSURES_INIT_TAC "s0" THEN STRIP_EXISTS_ASSUM_TAC THEN
  MP_TAC(INST [`APPEND (e2:(uarch_event)list) e0`,`e0:(uarch_event)list`]
              BODY_SAFE_FRAMED) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN ASM_REWRITE_TAC[] THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  X86_BIGSTEP_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC "s1" THENL
   [CONV_TAC(TOP_DEPTH_CONV BETA_CONV) THEN ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    FB_PRE_WINDOW_TAC;
    ALL_TAC] THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (2--2) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[WORD_RULE
    `word_add (word_add datap (word (64 * i))) (word 64):int64 =
     word_add datap (word (64 * (i + 1)))`] THEN
  MP_TAC(SPECL [`datap:int64`;`num_blocks:num`;`i + 1`] CF_BLOCK_LT) THEN
  ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  CONJ_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[COND_RAND] THEN TRY COND_CASES_TAC THEN REWRITE_TAC[] THEN
      TRY REFL_TAC;
      SAFE_META_EXISTS_TAC allowed_vars_e THEN
      CONJ_TAC THENL [ EXISTS_E2_TAC allowed_vars_e; ALL_TAC ] THEN
      CONJ_TAC THENL
       [FB_EVENTSEQ_TAC;
        FB_MEMACCESS_WIDEN_TAC]];
    FB_DISCARD_EVENT_EQNS_TAC THEN MONOTONE_MAYCHANGE_TAC];;

(* PREFIX: concretize the 3-part trace + open the events-while over num_blocks. *)
let CORE_SAFE_PREFIX_TAC =
  CONCRETIZE_F_EVENTS_TAC
   `\(datap:int64) (statep:int64) (num_blocks:num) (kbytes:num) (pc:num) (stackpointer:int64).
      APPEND (f_ev_epil datap statep num_blocks kbytes pc stackpointer)
        (APPEND (ENUMERATEL num_blocks (\i. f_ev_loop datap statep num_blocks kbytes pc stackpointer i))
                (f_ev_prol datap statep num_blocks kbytes pc stackpointer)) :(uarch_event)list` THEN
  REPEAT META_EXISTS_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN STRIP_TAC THEN
  ENSURES_EVENTS_WHILE_UP2_TAC `num_blocks:num` `pc + 0x4e` `pc + 0x1150` core_safe_inv;;

(* INIT: 8 state-loads + jmp (0x31 -> 0x4e), establish loopinv 0 + prologue trace. *)
let CORE_SAFE_INIT_TAC =
  REWRITE_TAC[KLEN; SUB_0; MULT_CLAUSES; ADD_CLAUSES; WORD_ADD_0] THEN
  ENSURES_INIT_TAC "s0" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--9) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ENUMERATEL; APPEND] THEN DISCHARGE_SAFETY_PROPERTY_TAC;;

(* EXIT: a genuine 0-step ensures (pre-RIP = post-RIP = pc+0x1150; the back-edge   *)
(* jb folds into the WHILE_UP2 BODY).  Events come from the loop INVARIANT, not     *)
(* stepping, so ENSURES_FINAL_STATE_TAC/EXISTS_E2_TAC are the wrong tools.          *)
(* ENSURES_ALREADY reduces it to (!x. p x ==> q x) /\ (=) subsumed C: GEN+STRIP     *)
(* exposes the precond `?e2` as assumptions; witness e2'':=e2; f_ev_epil unifies    *)
(* to [] via NIL_IMPLIES_APPEND_EQ; memaccess/events-content by ACCEPT; the frame   *)
(* permits identity by SUBSUMED_ID_MAYCHANGE_TAC.                                   *)
let CORE_SAFE_EXIT_TAC =
  MATCH_MP_TAC ENSURES_ALREADY THEN CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN
    RULE_ASSUM_TAC(CONV_RULE(TRY_CONV BETA_CONV)) THEN
    CONV_TAC(TRY_CONV BETA_CONV) THEN
    FIRST_X_ASSUM(STRIP_ASSUME_TAC o check(fun th ->
      can (find_term (fun t -> is_const t && fst(dest_const t)="bytes_loaded"))
          (concl th))) THEN
    CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM(fun th ->
        match concl th with
          Comb(Comb(Const("=",_),
            Comb(Comb(Const("read",_),Const("events",_)),_)),
            Comb(Comb(Const("APPEND",_),w),_)) -> EXISTS_TAC w
        | _ -> NO_TAC) THEN
      CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      CONJ_TAC THENL
       [FIRST_ASSUM(fun th ->
          if can (term_match [] `e2 = APPEND a b`) (concl th)
          then GEN_REWRITE_TAC LAND_CONV [th] else NO_TAC) THEN
        MATCH_MP_TAC NIL_IMPLIES_APPEND_EQ THEN
        CONJ_TAC THENL [REFL_TAC; UNIFY_REFL_TAC];
        FIRST_ASSUM ACCEPT_TAC]];
    SUBSUMED_ID_MAYCHANGE_TAC];;

(* ---- assemble ---- *)
let SHA256_BLOCK_DATA_ORDER_NOHW_CORE_SAFE = prove
 (sha_core_safe_goal,
  CORE_SAFE_PREFIX_TAC THEN
  REPEAT CONJ_TAC THENL
   [ASM_ARITH_TAC;
    CORE_SAFE_INIT_TAC;
    CORE_SAFE_BODY_TAC;
    CORE_SAFE_EXIT_TAC]);;

(* ========================================================================= *)
(* Session 050: Phase 11 step (3) — the SAFETY WRAPPER (NOVEL hand-rolled).   *)
(* CORE_SAFE (entry tmc 0x31 -> exit 0x1150) -> NOIBT_SUBROUTINE_SAFE          *)
(* (entry pc -> return), then _SUBROUTINE_SAFE via ADD_IBT_RULE.              *)
(*                                                                           *)
(* No canned tactic applies: the `andq $-64,%rsp` dynamic alignment makes the *)
(* in-frame RSP = word_and(sp+64)(~63), not a fixed offset.  We clone the      *)
(* Phase-10 functional NOIBT wrapper and graft the safety events threading.    *)
(*                                                                           *)
(* CRUX (the delta<->word_and tension): stepping the prologue stores needs the *)
(* in-frame SP in DELTA form (word_add sp (word delta), delta<=64) so          *)
(* NONSELFMODIFYING discharges; but the events-content clause needs it as a    *)
(* function of the PUBLIC stackpointer (UNIFY_F_EVENTS_TAC allows NO free      *)
(* `delta`).  Resolved by the FRSP-INDIRECTION: abbreviate frsp = word_and(..),*)
(* then SUBST_ALL frsp := word_add sp (word delta).  Because SUBST rewrites    *)
(* `frsp` (not `word_and`), the abbrev-def `frsp = word_and(..)` becomes the   *)
(* SURVIVING fold `word_add sp (word delta) = word_and(..)` (word_and intact). *)
(* Stepping runs in delta form; at discharge we fold delta->word_and on the    *)
(* events-content clause (-> a function of stackpointer) and keep delta-offset *)
(* on the memaccess clause (CONTAINED via delta<=64).                          *)
(* ========================================================================= *)

let SHA256_NOHW_SAFE_DELTA_FOLD = prove
 (`!q:int64. word_add q (word(val(word_sub
      (word_and (word_add q (word 64)) (word 18446744073709551552)) q))) =
    word_and (word_add q (word 64)) (word 18446744073709551552)`,
  GEN_TAC THEN CONV_TAC WORD_RULE);;

let SHA256_BLOCK_DATA_ORDER_NOHW_NOIBT_SUBROUTINE_SAFE = prove
 (`?f_events:int64->int64->num->num->num->int64->int64->(uarch_event)list.
   !e:(uarch_event)list.
   !a:int32. !b:int32. !c:int32. !d:int32. !ee:int32. !f:int32. !g:int32. !h:int32.
   !data:num->int32. !num_blocks:num.
   !kbytes:num. !pc:num. !stackpointer:int64. !returnaddress:int64.
   !datap statep:int64.
    0 < num_blocks /\
    val datap + 64 * num_blocks < 2 EXP 64 /\
    riprel32_within_bounds kbytes (pc + 0x57) /\
    ALL (nonoverlapping (word_sub stackpointer (word 208), 208))
        [(word pc, 4465); (word kbytes, 677); (datap, 64 * num_blocks)] /\
    nonoverlapping (word pc:int64, 4465) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (word pc:int64, 4465) /\
    nonoverlapping (statep:int64, 32) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (datap:int64, 64 * num_blocks) /\
    nonoverlapping (word_sub stackpointer (word 208):int64, 216) (statep:int64, 32)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_tmc pc kbytes) /\
              read RIP s = word pc /\
              read RSP s = stackpointer /\
              read (memory :> bytes64 stackpointer) s = returnaddress /\
              C_ARGUMENTS [statep; datap; word num_blocks] s /\
              read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
              read (memory :> bytes32 statep) s = word_zx a /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx b /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx c /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx d /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx ee /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx f /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx g /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx h /\
              (!j. j < 16 * num_blocks
                   ==> read (memory :> bytes32 (word_add datap (word (4 * j)))) s =
                       word_bytereverse (data j)) /\
              read events s = e)
         (\s. read RIP s = returnaddress /\
              read RSP s = word_add stackpointer (word 8) /\
              (?e2. read events s = APPEND e2 e /\
                    e2 = f_events datap statep num_blocks kbytes pc
                                  (word_sub stackpointer (word 208)) returnaddress /\
                    memaccess_inbounds e2
                      [statep,32; datap, 64 * num_blocks;
                       word_sub stackpointer (word 208),216; word kbytes:int64,677]
                      [statep,32; word_sub stackpointer (word 208),208]))
         (MAYCHANGE [RSP] ,, MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI ,,
          MAYCHANGE [memory :> bytes(statep, 32);
                     memory :> bytes(word_sub stackpointer (word 208), 208)])`,
  (* (1) strip CORE_SAFE's exists f_events; introduce the goal's f_events metavar. *)
  ASSUME_CALLEE_SAFETY_TAC SHA256_BLOCK_DATA_ORDER_NOHW_CORE_SAFE "H_CORE" THEN
  META_EXISTS_TAC THEN
  (* (2) Phase-10 prologue setup: offset stackpointer (entry RSP = sp+208). *)
  GEN_TAC (* e *) THEN
  REPLICATE_TAC 12 GEN_TAC THEN WORD_FORALL_OFFSET_TAC 208 THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI; C_ARGUMENTS; SOME_FLAGS;
              fst SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC] THEN
  REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN
  REWRITE_TAC[KLEN] THEN
  REPEAT STRIP_TAC THEN
  MAP_EVERY (fun c -> ENSURES_PRESERVED_TAC ("init_"^fst(dest_const c)) c)
            (dest_list `[RBX; RBP; R12; R13; R14; R15]`) THEN
  REWRITE_TAC(!simulation_precanon_thms) THEN
  ENSURES_INIT_TAC "s0" THEN
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (1--11) THEN
  (* (3) FRSP-indirection: abbreviate the andq-aligned in-frame SP, then SUBST   *)
  (* frsp := word_add sp (word delta).  The abbrev-def survives as the FOLD       *)
  (* equation `word_add sp (word delta) = word_and(sp+64)~63` (word_and intact).  *)
  ABBREV_TAC
   `frsp:int64 = word_and (word_add stackpointer (word 64))
                          (word 18446744073709551552)` THEN
  ABBREV_TAC `delta = val(word_sub (frsp:int64) stackpointer)` THEN
  SUBGOAL_THEN `delta <= 64` ASSUME_TAC THENL
   [MAP_EVERY EXPAND_TAC ["delta";"frsp"] THEN CONV_TAC BITBLAST_RULE; ALL_TAC] THEN
  SUBGOAL_THEN `frsp:int64 = word_add stackpointer (word delta)` SUBST_ALL_TAC THENL
   [EXPAND_TAC "delta" THEN CONV_TAC WORD_RULE; ALL_TAC] THEN
  (* prologue bookkeeping stores at [sp+delta+64/72/80/88] (delta form). *)
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (12--15) THEN
  (* normalize the data-end value (rdx = datap + 4*(num_blocks<<4)). *)
  SUBGOAL_THEN `val(word_shl (word num_blocks) 4 :int64) = 16 * num_blocks`
   ASSUME_TAC THENL
   [REWRITE_TAC[VAL_WORD_SHL; VAL_WORD; DIMINDEX_64] THEN
    SUBGOAL_THEN `num_blocks MOD 2 EXP 64 = num_blocks` SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(2 EXP 4 * num_blocks) MOD 2 EXP 64 = 2 EXP 4 * num_blocks`
     SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_ARITH_TAC; ARITH_TAC]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `val(word_shl (word num_blocks) 4 :int64) = 16 * num_blocks`]) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ARITH_RULE `4 * 16 * num_blocks = 64 * num_blocks`]) THEN
  (* (4) apply CORE_SAFE at the in-frame RSP = word_add stackpointer (word delta).*)
  (* e0pro = read events s15 (s-free) so the events post survives the epilogue.   *)
  ABBREV_TAC `e0pro:(uarch_event)list = read events s15` THEN
  REMOVE_THEN "H_CORE" (fun cth -> MP_TAC(SPECL
   [`e0pro:(uarch_event)list`;
    `a:int32`; `b:int32`; `c:int32`; `d:int32`; `ee:int32`; `f:int32`; `g:int32`; `h:int32`;
    `data:num->int32`; `num_blocks:num`; `kbytes:num`; `pc:num`;
    `word_add stackpointer (word delta):int64`;
    `datap:int64`; `statep:int64`]
   cth)) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ALL; NONOVERLAPPING_CLAUSES] THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    ASM_REWRITE_TAC[] THEN NONOVERLAPPING_TAC; ALL_TAC] THEN
  (* core bigstep; subgoal 1 = the precondition match at s15 (state, K, dend, events). *)
  X86_BIGSTEP_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC "s16" THENL
   [ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[WORD_RULE
      `word_add (word_add q (word d)) (word n):int64 = word_add q (word (d + n))`;
     KLEN] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* epilogue: 9 instrs (mov rsi,[sp+delta+88]; 6 restores; lea rsp,[rsi]; ret) *)
  X86_STEPS_TAC SHA256_BLOCK_DATA_ORDER_NOHW_TMC_EXEC (17--25) THEN
  ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
  (* (5) discharge the safety property.  Manual session-036 split: the         *)
  (* events-content clause folds delta->word_and (a function of the public      *)
  (* stackpointer, so UNIFY_F_EVENTS accepts it); the memaccess clause keeps     *)
  (* delta-offset form (CONTAINED via delta<=64).                                *)
  SAFE_META_EXISTS_TAC allowed_vars_e THEN
  CONJ_TAC THENL [ EXISTS_E2_TAC allowed_vars_e; ALL_TAC ] THEN
  CONJ_TAC THENL
   [FIRST_X_ASSUM(fun th ->
      if can (term_match []
            `word_and (word_add stackpointer (word 64)) (word 18446744073709551552):int64 =
             word_add stackpointer (word delta)`) (concl th)
      then ASSUME_TAC th THEN GEN_REWRITE_TAC ONCE_DEPTH_CONV [GSYM th]
      else NO_TAC) THEN
    FULL_UNIFY_F_EVENTS_TAC;
    FIRST_ASSUM(fun th ->
      if can (term_match []
            `word_and (word_add stackpointer (word 64)) (word 18446744073709551552):int64 =
             word_add stackpointer (word delta)`) (concl th)
      then GEN_REWRITE_TAC ONCE_DEPTH_CONV [th]
      else NO_TAC) THEN
    DISCHARGE_MEMACCESS_INBOUNDS_TAC]);;

(* (3) The full subroutine SAFE theorem over the un-trimmed mc (ENDBR64).      *)
(* Lifted from the NOIBT theorem by ADD_IBT_RULE + the MC_BRIDGE equation.      *)
(* ADD_IBT_RULE bumps pc+0x57->0x5b and codesize 4465->4469.                    *)
let SHA256_BLOCK_DATA_ORDER_NOHW_SUBROUTINE_SAFE = prove
 (`?f_events:int64->int64->num->num->num->int64->int64->(uarch_event)list.
   !e:(uarch_event)list.
   !a:int32. !b:int32. !c:int32. !d:int32. !ee:int32. !f:int32. !g:int32. !h:int32.
   !data:num->int32. !num_blocks:num.
   !kbytes:num. !pc:num. !stackpointer:int64. !returnaddress:int64.
   !datap statep:int64.
    0 < num_blocks /\
    val datap + 64 * num_blocks < 2 EXP 64 /\
    riprel32_within_bounds kbytes (pc + 0x5b) /\
    ALL (nonoverlapping (word_sub stackpointer (word 208), 208))
        [(word pc, 4469); (word kbytes, 677); (datap, 64 * num_blocks)] /\
    nonoverlapping (word pc:int64, 4469) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (word pc:int64, 4469) /\
    nonoverlapping (statep:int64, 32) (word kbytes:int64, 677) /\
    nonoverlapping (statep:int64, 32) (datap:int64, 64 * num_blocks) /\
    nonoverlapping (word_sub stackpointer (word 208):int64, 216) (statep:int64, 32)
    ==> ensures x86
         (\s. bytes_loaded s (word pc) (sha256_block_data_order_nohw_mc pc kbytes) /\
              read RIP s = word pc /\
              read RSP s = stackpointer /\
              read (memory :> bytes64 stackpointer) s = returnaddress /\
              C_ARGUMENTS [statep; datap; word num_blocks] s /\
              read (memory :> bytelist (word kbytes, LENGTH K256_data)) s = K256_data /\
              read (memory :> bytes32 statep) s = word_zx a /\
              read (memory :> bytes32 (word_add statep (word 4))) s = word_zx b /\
              read (memory :> bytes32 (word_add statep (word 8))) s = word_zx c /\
              read (memory :> bytes32 (word_add statep (word 12))) s = word_zx d /\
              read (memory :> bytes32 (word_add statep (word 16))) s = word_zx ee /\
              read (memory :> bytes32 (word_add statep (word 20))) s = word_zx f /\
              read (memory :> bytes32 (word_add statep (word 24))) s = word_zx g /\
              read (memory :> bytes32 (word_add statep (word 28))) s = word_zx h /\
              (!j. j < 16 * num_blocks
                   ==> read (memory :> bytes32 (word_add datap (word (4 * j)))) s =
                       word_bytereverse (data j)) /\
              read events s = e)
         (\s. read RIP s = returnaddress /\
              read RSP s = word_add stackpointer (word 8) /\
              (?e2. read events s = APPEND e2 e /\
                    e2 = f_events datap statep num_blocks kbytes pc
                                  (word_sub stackpointer (word 208)) returnaddress /\
                    memaccess_inbounds e2
                      [statep,32; datap, 64 * num_blocks;
                       word_sub stackpointer (word 208),216; word kbytes:int64,677]
                      [statep,32; word_sub stackpointer (word 208),208]))
         (MAYCHANGE [RSP] ,, MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI ,,
          MAYCHANGE [memory :> bytes(statep, 32);
                     memory :> bytes(word_sub stackpointer (word 208), 208)])`,
  MATCH_ACCEPT_TAC(ADD_IBT_RULE ~bridge:(Some SHA256_BLOCK_DATA_ORDER_NOHW_MC_BRIDGE)
                    SHA256_BLOCK_DATA_ORDER_NOHW_NOIBT_SUBROUTINE_SAFE));;
